window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0090", [{"word":"nesting","ipa_uk":"/ˈnestɪŋ/","ipa_us":"/ˈnestɪŋ/","definition_zh":"筑巢；巢居；（动物）在巢中繁殖；嵌套；套叠","definition_en":"the act or period of building and using a nest, or of placing one thing inside another","core_image":"枯枝与干草被一圈圈编成一个碗形的窝，鸟伏在中间，把身体压进这个刚好合身的凹处","scene":"春天一到，芦苇丛里的水鸟开始筑巢，雌鸟守在窝里不肯离开。 Nesting peaks in April, when reed beds fill with hidden cups of woven grass.","sceneCN":"这里 nesting 指「筑巢、在巢中繁殖」（第 1 个义项：鸟类筑巢并伏窝的行为与时期）；句意为四月是筑巢高峰，芦苇丛里布满用草编成的隐蔽小窝。","pos":[{"tag":"n.","zh":"筑巢；巢居；（动物的）繁殖期筑巢行为"},{"tag":"adj.","zh":"筑巢用的；筑巢期的"},{"tag":"v. (present participle)","zh":"正在筑巢；嵌套；套叠"}],"collocations":[{"phrase":"nesting season","zh":"筑巢期"},{"phrase":"nesting site","zh":"筑巢地点"},{"phrase":"nesting colony","zh":"筑巢群体；营巢群落"},{"phrase":"nesting success","zh":"筑巢成功率"},{"phrase":"nesting habitat","zh":"筑巢生境"},{"phrase":"nesting behavior","zh":"筑巢行为"}],"forms":[{"label":"原形（动词）","form":"nest"},{"label":"三单（he/she/it）","form":"nests"},{"label":"过去式","form":"nested"},{"label":"现在分词 / 动名词","form":"nesting"},{"label":"名词（巢）","form":"nest"},{"label":"施事名词（筑巢者）","form":"nester"}],"derivatives":[{"word":"nest","pos":"n./v.","zh":"巢；筑巢；嵌套"},{"word":"nester","pos":"n.","zh":"筑巢的鸟；营巢者"},{"word":"nested","pos":"adj.","zh":"嵌套的；套叠的"},{"word":"nestling","pos":"n.","zh":"还不会离巢的雏鸟"},{"word":"nest box","pos":"n.","zh":"人工巢箱"}],"senses":[{"no":"01","title":"Birds building and sitting on a nest","titleCN":"鸟类筑巢并伏窝","definition":"the behaviour of a bird that builds a nest and stays on it to lay and incubate eggs","definitionCN":"鸟类建造巢并在其上产卵、孵卵的行为","example":"Nesting starts as soon as the reeds are tall enough to hide a nest.","exampleCN":"芦苇一长到足以藏住鸟巢的高度，筑巢就开始了。","why":"the -ing form names the activity itself and, by extension, the whole occupied period, because what a bird does at this stage is simply be on the nest.","whyCN":"-ing 形式命名行为本身，并顺势指整段占用巢的时期，因为鸟在这一阶段做的就是待在巢上。"},{"no":"02","title":"The breeding season defined by nests","titleCN":"以筑巢为标志的繁殖季","definition":"the part of the year when a species builds nests and raises young","definitionCN":"某物种筑巢育雏的那一段年度时期","example":"The survey counts birds only during nesting, from March to June.","exampleCN":"这项调查只在三月至六月的筑巢期统计鸟的数量。","why":"a season is named after its most visible activity, and for many birds the nest is the calendar marker.","whyCN":"季节常以其最显眼的活动命名，而对许多鸟来说巢就是历法标记。"},{"no":"03","title":"Choosing and defending a nest site","titleCN":"选择并守护筑巢地点","definition":"the process of selecting a place for a nest and keeping rivals away from it","definitionCN":"为巢选址并把竞争者赶离该处的过程","example":"Nesting in dense thickets is what keeps the eggs out of sight.","exampleCN":"在密灌木中筑巢，正是让鸟卵不被看见的原因。","why":"the word covers the whole act, and site choice is the first decision inside that act rather than a separate word.","whyCN":"这个词覆盖整个行为，选址是这一行为里的第一个决定，而不是另立一词。"},{"no":"04","title":"Colonial nesting","titleCN":"群居筑巢","definition":"the habit of many pairs nesting close together in one colony","definitionCN":"许多对鸟在同一个群体中彼此紧邻筑巢的习性","example":"Colonial nesting makes thousands of nests visible from the cliff path.","exampleCN":"群居筑巢让成千上万个巢从崖边小路上一眼可见。","why":"a habit is named by the activity, so the adjective colonial simply tells how the nesting is arranged.","whyCN":"习性以其活动命名，因此形容词 colonial 只是说明筑巢在空间上如何排列。"},{"no":"05","title":"Nesting failure and success","titleCN":"筑巢失败与成功率","definition":"the outcome of a nesting attempt, measured by whether young fledge","definitionCN":"一次筑巢尝试的结果，以雏鸟能否离巢为准","example":"Flooding cut nesting success along the lower marsh.","exampleCN":"洪水降低了低处沼泽的筑巢成功率。","why":"field biologists measure a season by its attempts, so nesting became a countable noun phrase meaning one attempt.","whyCN":"野外生物学家以尝试次数衡量季节，因此 nesting 成了一个可计数的「一次尝试」。"},{"no":"06","title":"Animals that nest in cavities","titleCN":"在洞穴中营巢","definition":"the use of a hole, burrow or box rather than an open cup","definitionCN":"使用洞、穴或巢箱而非敞口碗状巢","example":"Cavity nesting suits species that cannot defend an open nest.","exampleCN":"洞穴筑巢适合那些守不住敞口巢的物种。","why":"the -ing form is used attributively as a technical label, so cavity nesting is one recognised nesting type.","whyCN":"-ing 形式作定语成为术语标签，因此洞穴筑巢是被承认的一种筑巢类型。"},{"no":"07","title":"Metaphor: living in a settled base","titleCN":"比喻：安顿下来、建立自己的窝","definition":"figurative, the stage of settling into a home and raising a family","definitionCN":"比喻用法，指安定下来成家育子的阶段","example":"After years of moving, they spoke of nesting in the small house.","exampleCN":"漂泊多年后，他们说起在那间小屋里安顿下来。","why":"the metaphor keeps only the settling aspect of nest building: building a base and staying in it.","whyCN":"比喻只保留筑巢中「安顿」的一面：建好基址并留在里面。"},{"no":"08","title":"Computing: placing structures one inside another","titleCN":"计算机：把结构一层套一层","definition":"in computing, the arrangement of a structure inside another of the same kind","definitionCN":"计算机中把一种结构放进同类结构内部的安排","example":"Deep nesting of folders makes the archive slow to search.","exampleCN":"文件夹层层嵌套会让这个档案库检索变慢。","why":"the technical sense borrows the shape of a nest: boxes within boxes, as cups within cups.","whyCN":"技术义借用了巢的形状：盒中有盒，正如碗中有碗。"}],"etymology":{"intro":{"en":"Nesting is the -ing form of nest, a word recorded in Old English as nest and shared with other Germanic languages. Its deeper origin is disputed.","cn":"nesting 是 nest 的 -ing 形式；nest 在古英语中已作 nest，并与其它日耳曼语共有同一形式。其更深来源有争议。"},"items":[{"era":"OLD ENGLISH NEST","en":"Old English nest meant both the structure a bird builds and the young reared in it, a double sense still visible in nestling.","cn":"古英语 nest 既指鸟筑成的结构，也指在其中育成的雏鸟，这双重含义仍见于 nestling。"},{"era":"GERMANIC COGNATES","en":"The same form appears in Old Norse, Old High German and Middle Dutch, which points to a common Germanic word rather than a Latin borrowing.","cn":"同一形式见于古诺斯语、古高地德语与中古荷兰语，说明它是共同的日耳曼词，而非拉丁借词。"},{"era":"LATIN NIDUS HYPOTHESIS","en":"The resemblance to Latin nidus 'nest' is often mentioned, but the two are usually treated as parallel formations; a direct borrowing is not demonstrated.","cn":"常有人提到它与拉丁 nidus「巢」相似，但两者通常被视为平行构词；直接借用的关系并未得到证明。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the pre-Germanic origin of nest is unresolved, and the common Indo-European root usually offered is a reconstruction, not an attested form.","cn":"来源不确定（词根）：nest 在日耳曼语之前的来源尚无定论，通常给出的原始印欧词根只是重构形式，并非有证形式。"},{"era":"-ING AS A NOUN","en":"The -ing form shifted from a participle into a name for the activity, then into a name for the season and for one attempt.","cn":"-ing 形式由分词转为行为的名称，再转为指季节与一次尝试。"},{"era":"TECHNICAL EXTENSION","en":"In the twentieth century nesting spread to computing, where it describes structures placed inside one another.","cn":"20 世纪 nesting 扩展到计算机领域，指放进彼此内部的结构。"}]},"similar":{"note":{"en":"Group one separates the nest family itself, where -ing, -ling and the bare noun are easily mixed up; group two separates nesting from the stages around it.","cn":"第一组区分 nest 词族内部，-ing、-ling 与原形名词最易混；第二组区分筑巢与其前后的阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nest","ipa":"/nest/","tag":"the thing or the act","definition":"The bare noun is the structure itself, and the bare verb is the act of building it; nesting is the act viewed as a process.","definitionCN":"原形名词指结构本身，原形动词指建造动作；nesting 指作为过程看待的这一动作。"},{"word":"nestling","ipa":"/ˈnestlɪŋ/","tag":"the young bird","definition":"A nestling is the chick still in the nest, so the -ling suffix marks a small occupant, not the activity.","definitionCN":"nestling 是仍在巢中的雏鸟，-ling 后缀标记幼小的居留者，而非活动。"},{"word":"nester","ipa":"/ˈnestə/","tag":"the bird","definition":"A nester is the bird that nests, marked by the agent suffix -er; it names the doer, not the doing.","definitionCN":"nester 是筑巢的鸟，由施事后缀 -er 标记；它命名执行者，而非动作。"},{"word":"nest box","ipa":"/ˈnest bɒks/","tag":"a built substitute","definition":"A nest box is a human-made cavity offered to birds; it is an object, not a behaviour.","definitionCN":"nest box 是供鸟使用的人工洞穴，是物件而非行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"breeding","ipa":"/ˈbriːdɪŋ/","tag":"the wider stage","definition":"Breeding covers courtship, mating, nesting and rearing; nesting is only the building-and-sitting part.","definitionCN":"breeding 覆盖求偶、交配、筑巢与育雏；nesting 只是其中建巢与伏窝的部分。"},{"word":"incubation","ipa":"/ˌɪŋkjuˈbeɪʃən/","tag":"the sitting and warming","definition":"Incubation is keeping eggs warm until they hatch; nesting includes it but also includes building and site choice.","definitionCN":"incubation 是保温孵卵直到出壳；nesting 包含它，但还包含建巢与选址。"},{"word":"roosting","ipa":"/ˈruːstɪŋ/","tag":"sleeping perch","definition":"Roosting is settling for the night on a perch, done outside the breeding season as well; nesting is tied to reproduction.","definitionCN":"roosting 是夜间栖于枝头，非繁殖季也会发生；nesting 与繁殖绑定。"},{"word":"burrowing","ipa":"/ˈbʌrəʊɪŋ/","tag":"digging a hole","definition":"Burrowing is digging into soil or sediment; a burrow can serve as a nest, but the digging itself is not nesting.","definitionCN":"burrowing 是掘入土壤或沉积物；洞穴可作巢使用，但挖掘本身不是筑巢。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real compounds and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实复合词与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"nest + -ing: the -ing turns the verb into the name of the activity and of the season.","cn":"nest + -ing：-ing 把动词变成行为与季节的名称。"},{"en":"The family runs nest, nesting, nester, nestling, nest box.","cn":"同族词包括 nest、nesting、nester、nestling、nest box。"},{"en":"Field reports use fixed phrases: nesting season, nesting site, nesting success.","cn":"野外报告使用固定搭配：筑巢期、筑巢地点、筑巢成功率。"},{"en":"The metaphor appears in the phrase nesting instinct, borrowed from animal behaviour.","cn":"比喻义见于 nesting instinct 一词，本身借自动物行为研究。"},{"en":"In computing the same word describes folders inside folders.","cn":"在计算机领域，同一个词描述文件夹套文件夹。"}],"abstract":[{"en":"Picture a bowl of twigs that fits the body sitting in it exactly.","cn":"想象一只树枝编成的碗，恰好贴合伏在其中的身体。"},{"en":"Picture a calendar where the year is cut into before, during and after the nest.","cn":"想象一张日历，把一年切成筑巢前、筑巢中、筑巢后。"},{"en":"Picture boxes placed inside boxes until the smallest one is hard to find.","cn":"想象盒子一层层装进盒子，最小的那只越来越难找。"}]},"examples":[{"en":"Nesting begins earlier on warm coasts than on cold uplands.","cn":"温暖海岸的筑巢开始得比寒冷高地早。"},{"en":"The wardens rope off the cliff during nesting to keep visitors away.","cn":"筑巢期间巡护员用绳围住崖壁，让游客远离。"},{"en":"Folder nesting three levels deep slows down every search.","cn":"文件夹嵌套三层会让每次检索都变慢。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nest（巢）+ ing（正在）」——正在编巢、正在伏窝 → 筑巢；引申为层层套住","word":"nesting"},"root":"古英语 nest「巢；巢中雏鸟」，与古诺斯语、古高地德语同形，属日耳曼共有词；与拉丁 nidus「巢」的相似多为平行构词，直接借用未获证明；日耳曼语之前的词根来源不确定。","sensesIntro":{"en":"Eight senses follow one act: a bird builds a cup of twigs, sits on it, and that single act is then read as a season, a site choice, a colony habit, a measured outcome, a cavity strategy, a human settling-down and finally a box inside a box.","cn":"八个义项沿同一个动作展开：鸟编成一只树枝碗并伏在上面；这一个动作随后被读成季节、选址、群体习性、可测的结果、洞穴策略、人的安顿，最后读成盒中之盒。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bowl woven from twigs that fits the sitting body exactly.","cn":"核心意象：一只树枝编成的碗，恰好贴合伏在其中的身体。"},"chain":["BUILD THE CUP","SIT AND WARM","MARK THE SEASON","HOLD A SITE","MEASURE THE ATTEMPT","FIT ONE INSIDE ANOTHER"],"branches":[{"senses":"S1 · S2","en":"OCCUPIED CUP: the building and the sitting together define the period.","cn":"占用的碗：建造与伏窝合起来定义了那段时间。"},{"senses":"S3 · S4","en":"PLACED TOGETHER: site choice and colonial crowding are the same cup seen in space.","cn":"成组安放：选址与群居拥挤是同一只碗在空间上的两种样子。"},{"senses":"S5","en":"COUNTED ATTEMPT: once one nest can fail, nesting becomes a number.","cn":"可数的尝试：一只巢可能失败，nesting 就成了一个数字。"},{"senses":"S6","en":"CAVITY VARIANT: the cup is replaced by a hole, and the word follows the function, not the shape.","cn":"洞穴变体：碗被洞取代，词跟着功能走，而不是跟着形状走。"},{"senses":"S7 · S8","en":"NEST SHAPE TRANSFERRED: a person settles into a home, a folder sits inside a folder.","cn":"巢形的转移：人安顿进一个家，文件夹放进另一个文件夹。"}]},"affixes":{"intro":{"en":"Nesting is a native Germanic word with a productive suffix, so its morphology is short and transparent rather than Latin.","cn":"nesting 是本族日耳曼词加能产后缀，形态短而透明，并非拉丁式。"},"latinIntro":{"en":"No Latin root is involved in nest itself; the Latin items listed below are only the learned words that English borrowed for the same idea.","cn":"nest 本身不含拉丁词根；下列拉丁条目只是英语为同一概念借入的学术词。"},"items":[{"word":"nest","structure":"nest (Old English noun and verb)","meaning":"a bird's structure; to build one","meaningCN":"鸟巢；筑巢","example":"Swallows nest under the eaves.","exampleCN":"燕子在屋檐下筑巢。"},{"word":"-ing","structure":"-ing (Old English present participle and gerund ending)","meaning":"the act, or the act in progress","meaningCN":"动作；正在进行的动作","example":"Nesting is a process, not a single moment.","exampleCN":"筑巢是一个过程，不是一个瞬间。"},{"word":"-er","structure":"nester = nest + -er (agent)","meaning":"one that nests","meaningCN":"筑巢者","example":"Cavity nesters lose when old trees are felled.","exampleCN":"老树被伐时，洞穴筑巢者最受损。"},{"word":"-ling","structure":"nestling = nest + -ling (diminutive)","meaning":"a small one in the nest","meaningCN":"巢中的幼小者","example":"The nestlings gaped as the adult arrived.","exampleCN":"成鸟一回来，雏鸟就张大了嘴。"},{"word":"nested","structure":"nest + -ed (adjectival past participle)","meaning":"placed inside another","meaningCN":"被套在另一个里面的","example":"The tables are deeply nested.","exampleCN":"这些表格层层嵌套。"},{"word":"nest box","structure":"nest + box (compound noun)","meaning":"a substitute cavity","meaningCN":"替代性的洞穴","example":"A nest box can replace a lost hollow.","exampleCN":"一只巢箱可以替代失去的树洞。"},{"word":"nesting season","structure":"nesting + season (compound)","meaning":"the period of nesting","meaningCN":"筑巢的时期","example":"The path is closed in the nesting season.","exampleCN":"这条路在筑巢期关闭。"},{"word":"nesting site","structure":"nesting + site (compound)","meaning":"a chosen place for a nest","meaningCN":"选定的筑巢处","example":"The same nesting site is reused for years.","exampleCN":"同一处筑巢点会被连年使用。"},{"word":"nest egg","structure":"nest + egg (idiomatic compound)","meaning":"savings set aside","meaningCN":"留作储备的钱","example":"The first payment became their nest egg.","exampleCN":"第一笔款成了他们的储备金。"}],"latinEntries":[{"word":"nidus","structure":"nidus, nidi (m., second declension)","meaning":"nest, brood","meaningCN":"巢；一窝雏"},{"word":"nidificare","structure":"nidificare, nidificavi, nidificatum (verb, first conjugation)","meaning":"to build a nest","meaningCN":"筑巢"},{"word":"incubare","structure":"incubare, incubui, incubitum (verb, first conjugation)","meaning":"to lie upon, brood","meaningCN":"伏在上面；孵"}]}},{"word":"nest","ipa_uk":"/nest/","ipa_us":"/nest/","definition_zh":"巢；窝；（鸟、昆虫等的）巢穴；一窝（雏鸟、卵）；筑巢；嵌套；窝藏","definition_en":"a structure built or hollowed out by an animal for laying eggs and raising young","core_image":"树杈间一只用泥与草茎抹成的碗，内壁被压得光滑，四枚带斑点的卵并排躺在正中","scene":"孩子在谷仓梁上发现了一个旧巢，里面还留着去年的一片蛋壳。 A sparrow's nest sat wedged against the beam, three eggs warm inside it.","sceneCN":"这里 nest 指「鸟巢、窝」（第 1 个义项：动物为产卵育雏而筑的结构）；句意为一只麻雀的巢卡在梁边，里面三枚卵还是温的。","pos":[{"tag":"n.","zh":"巢；窝；巢穴；一窝（卵或雏）"},{"tag":"v.","zh":"筑巢；巢居；嵌套；层层套放"}],"collocations":[{"phrase":"build a nest","zh":"筑巢"},{"phrase":"bird's nest","zh":"鸟巢"},{"phrase":"nest of eggs","zh":"一窝蛋"},{"phrase":"leave the nest","zh":"离巢"},{"phrase":"nest egg","zh":"储备金"},{"phrase":"empty nest","zh":"空巢（子女离家的家）"},{"phrase":"nest in","zh":"在……中筑巢"}],"forms":[{"label":"原形","form":"nest"},{"label":"复数","form":"nests"},{"label":"三单（he/she/it）","form":"nests"},{"label":"过去式","form":"nested"},{"label":"过去分词","form":"nested"},{"label":"现在分词","form":"nesting"}],"derivatives":[{"word":"nesting","pos":"n./adj.","zh":"筑巢；筑巢期的"},{"word":"nester","pos":"n.","zh":"筑巢的鸟；营巢者"},{"word":"nestling","pos":"n.","zh":"巢中雏鸟"},{"word":"nested","pos":"adj.","zh":"嵌套的"},{"word":"nest box","pos":"n.","zh":"巢箱"}],"senses":[{"no":"01","title":"A structure built to hold eggs","titleCN":"为盛放卵而筑成的结构","definition":"a structure of twigs, mud, grass or other material in which a bird lays and incubates eggs","definitionCN":"用树枝、泥、草等材料筑成、鸟在其中产卵与孵卵的结构","example":"A sparrow's nest sat wedged against the beam.","exampleCN":"一只麻雀的巢卡在梁边。","why":"the core sense is simply the object, because everything else the word names is derived from this built container.","whyCN":"核心义就是这件物体，因为这个词命名的其它一切都是由这个容器引申出来的。"},{"no":"02","title":"The home of a whole brood","titleCN":"一窝雏鸟共同的家","definition":"the place where a brood is reared, viewed as the young family's home","definitionCN":"一窝雏被养育之处，被看作这个幼小家庭的家","example":"The whole nest begged whenever the adult landed.","exampleCN":"成鸟一落下，整窝雏鸟都乞食。","why":"the container and its occupants merge, so nest may name the family inside as much as the structure.","whyCN":"容器与其居住者合并，因此 nest 既可指结构，也可指里面的全家。"},{"no":"03","title":"A clutch counted as one unit","titleCN":"作为一单位的一窝卵","definition":"the set of eggs laid in one nest and incubated together","definitionCN":"在同一巢中产出并一起孵化的一组卵","example":"Rangers recorded a nest of four eggs under the lamp.","exampleCN":"巡护员在灯下记录到一窝四枚卵。","why":"counting by nests is convenient because the nest defines the set, so the container becomes the unit of number.","whyCN":"以巢计数很方便，因为巢定义了这一组，容器于是成了计数单位。"},{"no":"04","title":"A hollow made by another animal","titleCN":"由其它动物挖出的巢穴","definition":"a burrow, hole or cavity used by an insect, mammal or fish for young","definitionCN":"昆虫、哺乳动物或鱼为育幼而使用的洞、穴或腔","example":"Wasps build a paper nest under the roof tiles.","exampleCN":"黄蜂在屋瓦下筑成纸质的巢。","why":"once the word is applied beyond birds, the structure stops being woven and becomes any prepared cavity.","whyCN":"一旦越出鸟类，这个结构就不再是编织的，而成为任何备好的腔室。"},{"no":"05","title":"To build and occupy a nest","titleCN":"筑巢并居于其中","definition":"to build a nest and use it for breeding","definitionCN":"建造巢并将其用于繁殖","example":"Swallows nest every year in the same corner of the barn.","exampleCN":"燕子每年都在谷仓同一个角落筑巢。","why":"the verb is simply the noun turned into an action, so it means to do what the noun names.","whyCN":"动词就是名词转为动作，意为做出名词所指的那件事。"},{"no":"06","title":"To place one thing inside another","titleCN":"把一物套进另一物内部","definition":"to fit objects or structures one inside another, as boxes or data tables","definitionCN":"把物件或结构放进彼此内部，如盒子或数据表","example":"Nest the smaller boxes inside the larger crate.","exampleCN":"把小盒子套进大板条箱里。","why":"the technical sense generalizes the shape of the bird's cup: something held within something else.","whyCN":"技术义把鸟巢的形状一般化：一物被另一物容纳在其中。"},{"no":"07","title":"A graduated set that fits inside itself","titleCN":"可以逐层套放的一组器物","definition":"a set of similar objects of decreasing size that store one inside another, as a nest of tables","definitionCN":"一组大小递减、可以互相套放的同类物件，如套几","example":"The nest of tables slotted under the largest one.","exampleCN":"套几收进最大的那张下面。","why":"the noun is applied to objects that imitate the containment of a nest, so the name follows the shape rather than the bird.","whyCN":"这个名词被用于模仿「巢的容纳关系」的物件，因此名称追随形状而非鸟。"},{"no":"08","title":"A den of troublesome people or things","titleCN":"滋生麻烦的人或事物之处","definition":"a place or group seen as a breeding ground for something harmful, as in a nest of thieves","definitionCN":"被视为有害之物滋生地的场所或群体，如贼窝","example":"The yard had become a nest of infection after the flood.","exampleCN":"洪水之后这个院子成了感染滋生地。","why":"the metaphor keeps only the idea of a sheltered place where something grows, and that something is no longer young.","whyCN":"比喻只保留「有遮蔽之处、某种东西在其中生长」的意思，而生长之物已不再是幼鸟。"}],"etymology":{"intro":{"en":"Nest is an Old English word, nest, with the same form in several old Germanic languages; its relation to Latin nidus is debated rather than settled.","cn":"nest 是古英语词 nest，在数种古老日耳曼语中形式相同；它与拉丁 nidus 的关系属争议，未有定论。"},"items":[{"era":"OLD ENGLISH NEST","en":"Old English nest named both the structure and the brood in it, and the word has kept that double reach.","cn":"古英语 nest 既指结构，也指其中的一窝，这双重范围一直保留。"},{"era":"GERMANIC PARALLELS","en":"Old Norse nest, Old High German nest and Middle Dutch nest show a common Germanic stock, so Latin borrowing is unlikely.","cn":"古诺斯语 nest、古高地德语 nest、中古荷兰语 nest 表明共同的日耳曼来源，因此不太可能是拉丁借词。"},{"era":"LATIN NIDUS","en":"Latin nidus 'nest' looks similar and means the same, but most handbooks treat the resemblance as parallel; a shared Indo-European source is a reconstruction.","cn":"拉丁 nidus「巢」形似义同，但多数辞书把这种相似视为平行；共有印欧来源属重构形式。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the pre-Germanic shape of nest is unresolved; the root commonly printed for it is reconstructed, not attested.","cn":"来源不确定（词根）：nest 在日耳曼语之前的形式无定论；常印出的词根是重构形式，并非有证材料。"},{"era":"VERB FROM NOUN","en":"The verb nest appeared later, formed directly from the noun, and was extended to any placing of one thing inside another.","cn":"动词 nest 出现较晚，直接由名词构成，并被扩展到任何把一物放进另一物的动作。"},{"era":"METAPHORICAL SPREAD","en":"Phrases such as empty nest and nest egg carried the word into family life and household finance.","cn":"empty nest、nest egg 等短语把这个词带进家庭生活与家庭理财。"}]},"similar":{"note":{"en":"Group one separates the near-synonyms for animal homes; group two separates the words built on nest itself.","cn":"第一组区分表示动物居所近义词；第二组区分由 nest 本身构成的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nesting","ipa":"/ˈnestɪŋ/","tag":"the activity","definition":"The -ing form names the building and sitting; the bare nest names the object.","definitionCN":"-ing 形式指建与伏的行为；原形 nest 指物件。"},{"word":"nestling","ipa":"/ˈnestlɪŋ/","tag":"the occupant","definition":"A nestling is a chick too young to leave; it is the content of the nest, not the nest.","definitionCN":"nestling 是尚不能离巢的雏鸟，是巢中之物，而非巢。"},{"word":"nester","ipa":"/ˈnestə/","tag":"the builder","definition":"A nester is the bird regarded as the one that nests, marked by -er.","definitionCN":"nester 是把鸟看作筑巢者，由 -er 标记。"},{"word":"nested","ipa":"/ˈnestɪd/","tag":"the state","definition":"Nested describes something already placed inside another; it is a state, not a place.","definitionCN":"nested 描述已被放进另一物之中的状态，是状态而非地点。"}]},{"heading":"NEAR MEANING","entries":[{"word":"burrow","ipa":"/ˈbʌrəʊ/","tag":"dug in soil","definition":"A burrow is dug into earth or sand; a nest may be built on a branch or in a hole.","definitionCN":"burrow 掘入土或沙；巢可能筑在枝上或洞里。"},{"word":"den","ipa":"/den/","tag":"mammal shelter","definition":"A den is a mammal's shelter, often a cave or hollow, and usually not built from gathered material.","definitionCN":"den 是哺乳动物的居所，常为洞穴，通常不由采集材料筑成。"},{"word":"lair","ipa":"/leə/","tag":"resting place of a predator","definition":"A lair is where a wild animal rests, especially a predator; it carries no idea of eggs.","definitionCN":"lair 是野兽尤其捕食者歇息之处，不含产卵之意。"},{"word":"hive","ipa":"/haɪv/","tag":"a colony's home","definition":"A hive is the home of a bee colony, a special case of an insect nest with a fixed architecture.","definitionCN":"hive 是蜂群的家，是昆虫巢的一种特例，结构固定。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Germanic relatives, real compounds and real idioms.","cn":"正常联想：真实的日耳曼同族词、真实复合词与真实习语。"},"normal":[{"en":"The Germanic relatives are Old Norse nest and Old High German nest, not Latin words.","cn":"日耳曼同族词是古诺斯语 nest 与古高地德语 nest，而非拉丁词。"},{"en":"The family runs nest, nesting, nester, nestling, nested, nest box.","cn":"同族词包括 nest、nesting、nester、nestling、nested、nest box。"},{"en":"Fixed phrases: build a nest, leave the nest, nest of eggs.","cn":"固定搭配：筑巢、离巢、一窝蛋。"},{"en":"The idioms empty nest and nest egg show the word applied to family and savings.","cn":"习语 empty nest 与 nest egg 显示这个词被用于家庭与储蓄。"},{"en":"In computing, nest means to place one structure inside another.","cn":"在计算机中，nest 指把一种结构放进另一种。"}],"abstract":[{"en":"Picture a cup so exactly shaped that the sitter's body closes its opening.","cn":"想象一只碗形制精准，伏者的身体正好封住开口。"},{"en":"Picture a house whose walls keep growing back after each departure.","cn":"想象一座屋子，每次有人离开后墙壁又重新长回。"},{"en":"Picture a set of bowls where the smallest is invisible until lifted out.","cn":"想象一套碗，最小的一只不被提起就看不见。"}]},"examples":[{"en":"The nest was rebuilt on the same branch after the storm.","cn":"风暴过后，巢又在同一根枝上重建。"},{"en":"She found an old nest in the rafters, empty and crumbling.","cn":"她在椽子上发现一只空了的旧巢，正在崩解。"},{"en":"Programmers nest these records inside a parent object.","cn":"程序员把这些记录嵌进一个父对象里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nest（巢）」——树枝围成碗，卵卧其中 → 巢、窝；动作义为筑巢、套住","word":"nest"},"root":"古英语 nest「巢；一窝」，与古诺斯语、古高地德语、中古荷兰语 nest 同出日耳曼共有词；与拉丁 nidus「巢」形似义同，通常视为平行构词，共有印欧来源仅为重构形式，日耳曼以前词根来源不确定。","sensesIntro":{"en":"Eight senses follow one shape: a built cup holds something precious, and the word then names the occupants, the count, a prepared cavity, a den of trouble, the act of building, any placing of one thing inside another, and finally a set of objects made to slot together.","cn":"八个义项沿一个形状展开：一只编成的碗托住贵重之物，词语随后指其居住者、计数单位、备好的腔室、滋生麻烦的窝、建造动作、任何把一物放进另一物的动作，最后指一组可以互相套放的器物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cup woven at the branch fork, its inner walls smoothed by the body inside it.","cn":"核心意象：枝杈分叉处编成的碗，内壁被其中的身体压得光滑。"},"chain":["BUILT CUP","BROOD AT HOME","COUNTED CLUTCH","PREPARED CAVITY","BUILD AND SIT","FIT INSIDE"],"branches":[{"senses":"S1 · S2","en":"CUP AND FAMILY: the container and the family in it are named by the same word.","cn":"碗与家庭：容器与其中的家庭由同一个词命名。"},{"senses":"S3","en":"COUNTED SET: the nest defines the clutch, so the container becomes the unit.","cn":"可数的组：巢定义了这一窝，容器于是成了单位。"},{"senses":"S4 · S8","en":"A SHELTERED PLACE: any animal's cavity, and a den where trouble breeds.","cn":"有遮蔽之处：任何动物的腔室，以及滋生麻烦的窝。"},{"senses":"S5","en":"DOING THE NOUN: the verb is the noun turned into an act.","cn":"做名词所指的事：动词就是名词转为动作。"},{"senses":"S6 · S7","en":"SHAPE EXPORTED: a rule for holding one thing inside another, and objects made to nest.","cn":"形状外输：一条「一物容另一物」的规则，以及照此造出的套叠器物。"}]},"affixes":{"intro":{"en":"Nest is a bare Germanic root that takes English suffixes and compounds; it has no Latin prefix structure.","cn":"nest 是裸露的日耳曼词根，只接英语后缀与复合成分，没有拉丁前缀结构。"},"latinIntro":{"en":"Nest itself has no Latin element; the Latin entries are the learned equivalents English borrowed separately for the same content.","cn":"nest 本身不含拉丁成分；下列拉丁条目是英语为同一内容另行借入的学术词。"},"items":[{"word":"nest","structure":"nest (noun, root)","meaning":"a structure for eggs","meaningCN":"盛卵的结构","example":"The nest held four eggs.","exampleCN":"巢里有四枚卵。"},{"word":"-ing","structure":"nesting = nest + -ing (gerund)","meaning":"the building and sitting","meaningCN":"建巢与伏窝","example":"Nesting lasts about three weeks.","exampleCN":"筑巢期约持续三周。"},{"word":"-er","structure":"nester = nest + -er (agent)","meaning":"one that nests","meaningCN":"筑巢者","example":"Cavity nesters need old trees.","exampleCN":"洞穴筑巢者需要老树。"},{"word":"-ling","structure":"nestling = nest + -ling (diminutive)","meaning":"the small occupant","meaningCN":"巢中的幼小者","example":"Nestlings cannot fly yet.","exampleCN":"雏鸟还不会飞。"},{"word":"-ed","structure":"nested = nest + -ed (past participle)","meaning":"placed inside","meaningCN":"被置于内部","example":"The lists are nested.","exampleCN":"这些列表是嵌套的。"},{"word":"nest egg","structure":"nest + egg (idiom)","meaning":"savings kept for the future","meaningCN":"为将来存下的钱","example":"They used the bonus as a nest egg.","exampleCN":"他们把奖金当作储备金。"},{"word":"empty nest","structure":"empty + nest (idiom)","meaning":"a home after the children leave","meaningCN":"子女离家后的家","example":"The empty nest felt too quiet.","exampleCN":"空巢显得太安静。"},{"word":"nest box","structure":"nest + box (compound)","meaning":"a human-made cavity","meaningCN":"人工洞穴","example":"Volunteers hung forty nest boxes.","exampleCN":"志愿者挂上了四十只巢箱。"},{"word":"hornet's nest","structure":"hornet + -'s + nest (idiom)","meaning":"a situation full of trouble","meaningCN":"麻烦成堆的局面","example":"The ruling stirred a hornet's nest.","exampleCN":"这项裁定捅了马蜂窝。"}],"latinEntries":[{"word":"nidus","structure":"nidus, nidi (m., second declension)","meaning":"nest, brood","meaningCN":"巢；一窝"},{"word":"nidificare","structure":"nidificare, nidificavi, nidificatum (verb, first conjugation)","meaning":"to build a nest","meaningCN":"筑巢"},{"word":"nidulus","structure":"nidulus, niduli (m., second declension, diminutive)","meaning":"a little nest","meaningCN":"小巢"}]}},{"word":"incubation","ipa_uk":"/ˌɪŋkjuˈbeɪʃən/","ipa_us":"/ˌɪnkjuˈbeɪʃən/","definition_zh":"孵卵；孵化；（疾病）潜伏期；（新事物）孕育期；培养","definition_en":"the keeping of eggs warm until they hatch, or any period in which something develops unseen before emerging","core_image":"一只鸟伏在卵上，腹下的羽毛张开成一小片温热的毯子，卵壳里正一寸寸长出血管","scene":"雌鸟伏在卵上十九天，几乎不吃不喝，只偶尔翻动一下身下的蛋。 Incubation lasts about three weeks, and the parent turns the eggs several times a day.","sceneCN":"这里 incubation 指「孵卵、孵化期」（第 1 个义项：亲鸟保温孵卵使胚胎发育的过程）；句意为孵化持续约三周，亲鸟每天翻卵数次。","pos":[{"tag":"n.","zh":"孵卵；孵化；潜伏期；孕育期；（细胞、微生物的）培养"}],"collocations":[{"phrase":"incubation period","zh":"孵化期；潜伏期"},{"phrase":"incubation time","zh":"孵育时间"},{"phrase":"artificial incubation","zh":"人工孵化"},{"phrase":"incubation temperature","zh":"孵化温度"},{"phrase":"incubation behavior","zh":"孵卵行为"},{"phrase":"egg incubation","zh":"卵的孵化"}],"forms":[{"label":"原形","form":"incubation"},{"label":"同根动词","form":"incubate"},{"label":"施事/工具名词","form":"incubator"},{"label":"形容词","form":"incubatory"},{"label":"现在分词（动词）","form":"incubating"}],"derivatives":[{"word":"incubate","pos":"v.","zh":"孵（卵）；潜伏；培育"},{"word":"incubator","pos":"n.","zh":"孵化器；恒温箱；创业孵化机构"},{"word":"incubatory","pos":"adj.","zh":"孵育的；潜伏期的"},{"word":"incubant","pos":"adj.","zh":"正被孵化的；处于潜伏状态的"},{"word":"incubational","pos":"adj.","zh":"孵化阶段的"}],"senses":[{"no":"01","title":"Keeping eggs warm until they hatch","titleCN":"保温孵卵直至出雏","definition":"the process by which a parent, or a machine, keeps eggs at a suitable temperature until the young emerge","definitionCN":"亲体或机器把卵保持在适宜温度、直到幼体破壳的过程","example":"Incubation lasts about three weeks in this species.","exampleCN":"这个物种的孵化期约为三周。","why":"the Latin base incubare means to lie upon something, so incubation names the state of lying on eggs and keeping them warm.","whyCN":"拉丁词基 incubare 意为伏在某物之上，因此 incubation 命名伏在卵上保温的状态。"},{"no":"02","title":"The length of time eggs are covered","titleCN":"卵被覆暖的整段时间","definition":"the period between the first egg being warmed and the last chick hatching","definitionCN":"从开始加温第一枚卵到最后一雏出壳的时期","example":"A shorter incubation means more broods in a single season.","exampleCN":"孵化期较短意味着一个季节里能多养一窝。","why":"a process is easily measured, so the name of the process also names the interval it occupies.","whyCN":"过程便于计量，因此过程的名称也指它所占据的时间段。"},{"no":"03","title":"Artificial warming in an incubator","titleCN":"用孵化器人工加温","definition":"the controlled warming of eggs by a machine rather than a body","definitionCN":"由机器而非身体对卵进行的受控加温","example":"Artificial incubation kept the eggs at a steady thirty-seven degrees.","exampleCN":"人工孵化把卵维持在恒定三十七度。","why":"the process is the same, only the source of heat changes, so the word needs no new form.","whyCN":"过程相同，只是热源更换，因此这个词无需另造形式。"},{"no":"04","title":"Medical: the silent stage of a disease","titleCN":"医学：疾病的无症状潜伏期","definition":"the interval between infection and the first symptoms","definitionCN":"从感染到首次出现症状之间的间隔","example":"The incubation period of the virus is four to ten days.","exampleCN":"这种病毒的潜伏期是四到十天。","why":"the disease is figuratively 'sitting on' the body before it hatches into symptoms, and the nineteenth-century metaphor kept the egg image.","whyCN":"疾病犹如伏在体内，等侯「孵出」症状；19 世纪的这一比喻保留了卵的意象。"},{"no":"05","title":"Microbiology: growing a culture","titleCN":"微生物培养：让菌群长起来","definition":"the controlled keeping of cells or microbes under conditions that let them multiply","definitionCN":"在适宜条件下受控地保存细胞或微生物、使其增殖","example":"Incubation of the samples ran overnight at body temperature.","exampleCN":"样本在体温下培养了一夜。","why":"a culture is warmed and watched in the way eggs are, so the laboratory reused the word without changing its shape.","whyCN":"培养物如卵一样被保温并观察，因此实验室沿用了这个词，未改变其形式。"},{"no":"06","title":"Business: sheltering a young venture","titleCN":"商业：庇护一个新创企业","definition":"a protected early stage in which a new company is supported before it operates alone","definitionCN":"新企业在独立运作之前受到扶持的受保护早期阶段","example":"The studio spent two years in incubation before its first release.","exampleCN":"这家工作室孵化两年才推出第一个作品。","why":"the young firm is treated as an egg that must be kept warm and unexposed until it can survive outside.","whyCN":"新企业被当作必须保温、不可暴露、直到能在外存活的一枚卵。"},{"no":"07","title":"A quiet period of forming an idea","titleCN":"想法在暗处成形的静默期","definition":"a deliberate interval in which a plan or idea is left to develop before being acted on","definitionCN":"有意留出的一段时间，让计划或想法先发展再行动","example":"The proposal needed a month of incubation before anyone could judge it.","exampleCN":"这份提案需要一个月孕育，才有人能判断它。","why":"what is unobservable is described by the word for what is under cover, so incubation fits any hidden growth.","whyCN":"不可见之物借「被覆盖之物」的词来描述，因此 incubation 适用于任何暗中生长。"},{"no":"08","title":"The state of lying on something","titleCN":"伏卧其上的状态（本义残留）","definition":"the literal older sense of resting or lying upon a surface, retained in learned usage","definitionCN":"古义「伏卧、停留在某物表面之上」，在学术语境中仍有保留","example":"The term incubation still echoes the plain Latin sense of lying upon.","exampleCN":"incubation 一词仍回响着拉丁语「伏卧其上」的朴素含义。","why":"the oldest layer survives beneath all the later ones, which is why the word works for both eggs and ideas.","whyCN":"最古老的一层沉淀在所有后起义之下，这正是它既能用于卵又能用于想法的原因。"}],"etymology":{"intro":{"en":"Incubation comes from Latin incubatio, from incubare 'to lie upon', built on in- 'on' and cubare 'to lie down'. Dates below are approximate.","cn":"incubation 来自拉丁 incubatio，出自 incubare「伏卧其上」，由 in-「在上」与 cubare「躺下」构成。下列年代均为约数。"},"items":[{"era":"LATIN CUBARE","en":"Cubare meant 'to lie down, to rest', and it also gives cubicle and concubine; the root is clear, though its further ancestry is debated.","cn":"cubare 意为「躺下、歇息」，也衍生 cubicle 与 concubine；词根清楚，但其更早谱系有争议。"},{"era":"LATIN INCUBARE","en":"In- 'upon' plus cubare produced incubare, 'to lie upon', used of birds on eggs and of anything resting on a surface.","cn":"in-「在上」加 cubare 构成 incubare「伏卧其上」，用于鸟伏卵，也用于任何栖于表面之物。"},{"era":"ENGLISH BORROWING","en":"English took incubation in the seventeenth century first as a learned word for brooding, then broadened it to any hidden maturing.","cn":"英语在 17 世纪借入 incubation，最初是「孵卵」的学术词，随后扩展到任何暗中成熟。"},{"era":"MEDICAL SHIFT","en":"From the early nineteenth century incubation named the silent stage of an infectious disease, a metaphor drawn from eggs.","cn":"自 19 世纪初起，incubation 指传染病的无症状阶段，这一比喻取自卵。"},{"era":"LABORATORY AND BUSINESS","en":"Culturing microbes and, later, sheltering start-up firms extended the word into laboratory work and commerce.","cn":"培养微生物以及后来庇护初创公司，把这个词扩展到实验室工作与商业。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact earliest English record for the business sense is not firmly dated, and the deeper origin of cubare is unsettled.","cn":"来源不确定（首见年代）：商业义最早的英语书证年代不确定，cubare 的更深来源亦无定论。"}]},"similar":{"note":{"en":"Group one separates the words of the same cubare family; group two separates incubation from neighbouring stages of reproduction and growth.","cn":"第一组区分同出 cubare 的词；第二组区分孵化与繁殖、生长中相邻的阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"incubate","ipa":"/ˈɪŋkjubeɪt/","tag":"the verb","definition":"To incubate is to do the warming; incubation is the process viewed as a whole.","definitionCN":"incubate 是做加温这件事；incubation 是作为整体看待的过程。"},{"word":"incubator","ipa":"/ˈɪŋkjubeɪtə/","tag":"the device","definition":"An incubator is the machine or, for premature infants, the enclosed bed that supplies the warmth.","definitionCN":"incubator 是提供热量的机器，对早产儿则指保温箱。"},{"word":"incubatory","ipa":"/ɪnˈkjubətəri/","tag":"the adjective","definition":"Incubatory describes what relates to incubation, as in incubatory period; it modifies rather than names.","definitionCN":"incubatory 描述与孵化有关，如孵育期；它作定语而非名称。"},{"word":"cubicle","ipa":"/ˈkjuːbɪkl/","tag":"same root, different path","definition":"Cubicle also comes from cubare 'to lie', through a small sleeping place; it shares the root but not the prefix.","definitionCN":"cubicle 亦出自 cubare「躺」，经「小睡处」而来；同词根但不同前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hatching","ipa":"/ˈhætʃɪŋ/","tag":"the end point","definition":"Hatching is the moment the young breaks the shell; incubation is everything before that.","definitionCN":"hatching 是幼体破壳的那一刻；incubation 是此前的全部过程。"},{"word":"brooding","ipa":"/ˈbruːdɪŋ/","tag":"sitting on eggs","definition":"Brooding stresses the parent's sitting and covering; incubation stresses the warmth and development that result.","definitionCN":"brooding 强调亲鸟伏坐覆盖；incubation 强调由此产生的温度与发育。"},{"word":"gestation","ipa":"/dʒeˈsteɪʃən/","tag":"development inside a body","definition":"Gestation is development inside the mother; incubation happens outside, in an egg or a machine.","definitionCN":"gestation 是母体内的发育；incubation 发生在体外，在卵中或机器中。"},{"word":"latency","ipa":"/ˈleɪtənsi/","tag":"hidden delay","definition":"Latency is the state of being present but not yet showing, especially in disease; incubation is the interval that state occupies.","definitionCN":"latency 是已存在却尚未显现的状态，尤指疾病；incubation 是该状态所占的时段。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin morphemes, real collocations and real technical extensions.","cn":"正常联想：真实的拉丁语素、真实搭配与真实技术延伸。"},"normal":[{"en":"in- 'upon' + cubare 'to lie' + -ion: the state of lying upon eggs.","cn":"in-「在上」+ cubare「躺」+ -ion：伏在卵上的状态。"},{"en":"The family runs incubate, incubation, incubator, incubatory.","cn":"同族词包括 incubate、incubation、incubator、incubatory。"},{"en":"Fixed phrases mark the three fields: incubation period, artificial incubation, incubation temperature.","cn":"固定搭配标出三个领域：潜伏期／孵化期、人工孵化、孵化温度。"},{"en":"The same word serves eggs, viruses, cell cultures and start-up companies.","cn":"同一个词服务于卵、病毒、细胞培养与新创公司。"},{"en":"Latin cubare also gives cubicle and concubine, a useful root check.","cn":"拉丁 cubare 还衍生 cubicle 与 concubine，可作词根核对。"}],"abstract":[{"en":"Picture a lid held over something until it is ready to lift it itself.","cn":"想象一只盖子罩住某物，直到它自己准备好顶开。"},{"en":"Picture a fire kept banked under ash, neither out nor blazing.","cn":"想象一堆被灰压住的火，既没熄也没旺。"},{"en":"Picture a seed of an idea kept warm and unspoken on purpose.","cn":"想象一颗想法的种子被有意保温、故意不说出口。"}]},"examples":[{"en":"Incubation is shared by both parents in this shorebird.","cn":"这种水鸟由双亲共同孵卵。"},{"en":"The incubation period can be as long as two weeks before a rash appears.","cn":"潜伏期可长达两周，之后才出现皮疹。"},{"en":"The lab shortened incubation to six hours by raising the temperature.","cn":"实验室提高温度，把培养时间缩短到六小时。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（在上）+ cub（躺）+ ation」——伏在蛋上不动 → 孵卵；引申为潜伏、培育","word":"incubation"},"root":"拉丁 incubare「伏卧其上」= in-（在上）+ cubare「躺下、歇息」；cubare 亦衍生 cubicle、concubine，其更深来源有争议。英语 incubation 经 incubatio 借入。","sensesIntro":{"en":"Eight senses follow one posture: something lies covered and warm, and that posture is then extended to the interval it fills, to a machine, to a hidden disease, to a growing culture, to a sheltered firm, to an unspoken idea, and finally back to the plain Latin act of lying upon.","cn":"八个义项沿一个姿态展开：某物被覆住并保温；这个姿态随后扩展到它所占据的时段、机器、隐伏的疾病、生长的培养物、被庇护的公司、未说出的想法，最后回到拉丁语「伏卧其上」的朴素动作。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body lying over eggs, warming them until the shell breaks.","cn":"核心意象：身体伏在卵上，把卵暖到壳破。"},"chain":["LIE UPON","PROVIDE WARMTH","FILL AN INTERVAL","WORK UNSEEN","BREAK OUT AT LAST","SHELTER A BEGINNING"],"branches":[{"senses":"S1 · S8","en":"LYING UPON: the oldest literal posture underlies every later use.","cn":"伏卧其上：最古老的实义姿态支撑着全部后起用法。"},{"senses":"S2 · S3","en":"MEASURED WARMTH: the process becomes a span and then a machine-run span.","cn":"可测的温暖：过程先成为一段时间，再成为机器运行的时段。"},{"senses":"S4","en":"HIDDEN GROWTH: a disease develops without showing, as a chick does inside the shell.","cn":"暗中生长：疾病不显形地发展，正如壳内的雏。"},{"senses":"S5","en":"WATCHED CULTURE: microbes are warmed and observed exactly as eggs are.","cn":"被观察的培养物：微生物被保温观察，与卵完全相同。"},{"senses":"S6 · S7","en":"SHELTERED BEGINNING: a firm or an idea is kept covered until it can stand outside.","cn":"被庇护的开端：公司或想法被罩住，直到能在外自立。"}]},"affixes":{"intro":{"en":"Incubation is a Latin noun of action, so prefix, root and suffix each carry a clear share of the meaning.","cn":"incubation 是拉丁动作名词，前缀、词根、后缀各自承担清晰的一份意义。"},"latinIntro":{"en":"Latin cubare and its compound incubare supply the whole family: incubate, incubation, incubator, incubatory.","cn":"拉丁 cubare 及其复合形式 incubare 提供了整个词族：incubate、incubation、incubator、incubatory。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, on, upon')","meaning":"on; upon","meaningCN":"在上；伏于","example":"The prefix places the body on top of the eggs.","exampleCN":"这个前缀把身体置于卵的上方。"},{"word":"cubare","structure":"cubare (Latin verb, first conjugation)","meaning":"to lie down, rest","meaningCN":"躺下；歇息","example":"The root supplies the posture of lying.","exampleCN":"这个词根提供「躺卧」的姿态。"},{"word":"incubare","structure":"in- + cubare","meaning":"to lie upon, brood","meaningCN":"伏卧其上；孵","example":"The hen incubates the clutch for weeks.","exampleCN":"母鸡伏在窝上孵数周。"},{"word":"-ion","structure":"-ion (Latin noun suffix, action or state)","meaning":"the act or state of","meaningCN":"动作或状态","example":"The suffix turns the verb into a name.","exampleCN":"这个后缀把动词变成名词。"},{"word":"incubate","structure":"incubare > English incubate","meaning":"to keep eggs warm","meaningCN":"孵卵","example":"Birds incubate in shifts.","exampleCN":"鸟轮流孵卵。"},{"word":"incubator","structure":"incubate + -or (agent or instrument)","meaning":"a device that supplies warmth","meaningCN":"提供热量的装置","example":"The incubator holds two hundred eggs.","exampleCN":"这台孵化器可放两百枚卵。"},{"word":"incubatory","structure":"incubate + -ory (relating to)","meaning":"relating to incubation","meaningCN":"与孵化有关的","example":"The incubatory stage is the longest.","exampleCN":"孵育阶段是最长的。"},{"word":"incubation period","structure":"incubation + period (compound)","meaning":"the interval before symptoms or hatching","meaningCN":"症状出现前或出雏前的间隔","example":"The incubation period is seven days.","exampleCN":"潜伏期为七天。"},{"word":"cubicle","structure":"cubare + -culum (diminutive)","meaning":"a small place to lie in","meaningCN":"可躺卧的小隔间","example":"Each cubicle holds one desk.","exampleCN":"每个隔间放一张桌子。"}],"latinEntries":[{"word":"cubare","structure":"cubare, cubui, cubitum (verb, first conjugation)","meaning":"to lie down, rest","meaningCN":"躺下；歇息"},{"word":"incubare","structure":"incubare, incubui, incubitum (verb, first conjugation)","meaning":"to lie upon, brood","meaningCN":"伏卧其上；孵"},{"word":"incubatio","structure":"incubatio, incubationis (f., third declension)","meaning":"a lying upon, brooding","meaningCN":"伏卧；孵卵"},{"word":"cubile","structure":"cubile, cubilis (n., third declension)","meaning":"a bed, couch","meaningCN":"床；卧处"}]}},{"word":"incubate","ipa_uk":"/ˈɪŋkjubeɪt/","ipa_us":"/ˈɪŋkjubeɪt/","definition_zh":"孵（卵）；孵化；（疾病）潜伏；（想法、企业）孕育、培育","definition_en":"to keep eggs warm until they hatch, or to keep something under conditions that let it develop before it emerges","core_image":"一只手掌轻轻盖在几枚温热的卵上，掌心下没有任何声音，只有稳定不变的温度","scene":"母鸡伏在草窝里不肯起身，饲养员只好把饲料和水端到它嘴边。 The hen will incubate the clutch for twenty-one days without leaving it for long.","sceneCN":"这里 incubate 指「孵卵」（第 1 个义项：以体温加温卵使胚胎发育）；句意为母鸡会孵这窝蛋二十一天，中途不会长时间离开。","pos":[{"tag":"vt.","zh":"孵（卵）；使孵化；培育（细菌、细胞）"},{"tag":"vi.","zh":"（卵）被孵化；（疾病）潜伏；（想法）酝酿"}],"collocations":[{"phrase":"incubate eggs","zh":"孵卵"},{"phrase":"incubate a culture","zh":"培养菌群"},{"phrase":"incubate an idea","zh":"孕育一个想法"},{"phrase":"incubate a company","zh":"孵化一家公司"},{"phrase":"incubate overnight","zh":"过夜培养"},{"phrase":"incubate at body temperature","zh":"在体温下培养"}],"forms":[{"label":"原形","form":"incubate"},{"label":"三单（he/she/it）","form":"incubates"},{"label":"过去式","form":"incubated"},{"label":"过去分词","form":"incubated"},{"label":"现在分词","form":"incubating"},{"label":"名词（过程）","form":"incubation"}],"derivatives":[{"word":"incubation","pos":"n.","zh":"孵化；潜伏期；培育期"},{"word":"incubator","pos":"n.","zh":"孵化器；保温箱；孵化机构"},{"word":"incubating","pos":"adj.","zh":"正在孵化的；正在培育的"},{"word":"incubatory","pos":"adj.","zh":"孵育的"},{"word":"incubated","pos":"adj.","zh":"已孵化／已培养的"}],"senses":[{"no":"01","title":"Keep eggs warm until they hatch","titleCN":"保温孵卵直到出雏","definition":"to sit on eggs or supply heat to them so that the embryos develop and the young hatch","definitionCN":"伏在卵上或向其供热，使胚胎发育、幼体破壳","example":"The hen will incubate the clutch for twenty-one days.","exampleCN":"母鸡会孵这窝蛋二十一天。","why":"incubare in Latin means to lie upon, and the verb keeps that physical posture as its core.","whyCN":"拉丁 incubare 意为伏卧其上，这个动词把这一身体姿态保留为核心。"},{"no":"02","title":"Of an egg: to be developing under warmth","titleCN":"（卵）在温度下发育","definition":"of an egg, to be kept at the temperature that lets the embryo grow","definitionCN":"指卵被保持在使胚胎得以生长的温度","example":"The eggs incubate faster in damp sand than in dry.","exampleCN":"卵在湿沙中比在干沙中孵得更快。","why":"the verb is used intransitively because the egg is the thing undergoing the change, not doing it.","whyCN":"这个动词可作不及物用法，因为卵是承受变化者，而不是执行者。"},{"no":"03","title":"Run a mechanical hatchery","titleCN":"用机器进行孵化","definition":"to keep eggs in a warmed device instead of under a body","definitionCN":"把卵放在加温装置中而非身体之下","example":"Hatcheries incubate thousands of eggs at a single temperature.","exampleCN":"孵化场以单一温度孵化成千上万枚卵。","why":"the machine imitates the body's function, so it takes the same verb rather than a new one.","whyCN":"机器模仿身体的功能，因此用同一个动词而非另造一个。"},{"no":"04","title":"Grow a microbial culture","titleCN":"培养微生物或细胞","definition":"to keep cells or microbes at conditions that allow them to multiply","definitionCN":"把细胞或微生物保持在允许其增殖的条件下","example":"Incubate the plates at thirty-seven degrees overnight.","exampleCN":"把培养皿在三十七度下过夜培养。","why":"a culture is warmed and left alone exactly as a clutch is, so laboratory usage is literal, not figurative.","whyCN":"培养物与一窝卵一样被加温并静置，因此实验室用法是字面的，不是比喻。"},{"no":"05","title":"Of a disease: to develop before showing","titleCN":"（疾病）在发展而未显现","definition":"of a pathogen or disease, to be present and multiplying before symptoms appear","definitionCN":"指病原或疾病已存在并增殖，但症状尚未出现","example":"The virus incubates for up to two weeks inside the host.","exampleCN":"病毒在宿主体内潜伏可达两周。","why":"the hidden growth is described by the verb for growth under cover, which is why the disease 'sits' unseen.","whyCN":"隐伏的生长借用「被覆盖下生长」的动词，因此疾病「伏」而不见。"},{"no":"06","title":"Shelter a young company","titleCN":"扶持新创企业度过早期","definition":"to support a new firm in a protected setting before it operates independently","definitionCN":"在受保护的环境中扶持新企业，直到其独立运作","example":"The accelerator incubates twelve teams for six months.","exampleCN":"这家加速器扶持十二个团队六个月。","why":"the firm is treated as an egg needing warmth and shelter, so the biological verb carries over unchanged.","whyCN":"公司被当作需要保温与庇护的卵，因此生物学的动词原样移植过来。"},{"no":"07","title":"Let an idea develop quietly","titleCN":"让想法安静地酝酿","definition":"to hold an idea, plan or work in mind without acting on it until it matures","definitionCN":"把想法、计划或作品留在心里，不加行动，直到它成熟","example":"She incubated the design for a year before showing anyone.","exampleCN":"她把这个设计酝酿了一年才给人看。","why":"nothing visible happens during incubation, and that is precisely the property the metaphor borrows.","whyCN":"孵化期间看不见任何变化，而这正是比喻所借用的性质。"},{"no":"08","title":"Lie upon something, in the older literal sense","titleCN":"古义：伏卧于某物之上","definition":"to rest or lie upon a surface, the original Latin sense now confined to learned prose","definitionCN":"栖卧于某表面之上，这一拉丁本义今仅存于学术文字","example":"In older usage a brooding bird simply incubates the nest.","exampleCN":"在较早的用法里，伏窝的鸟就是「伏在巢上」。","why":"the literal posture explains all the derived senses, including the medical and business ones.","whyCN":"这一实义姿态解释了全部引申义，包括医学与商业义。"}],"etymology":{"intro":{"en":"Incubate is the English form of Latin incubare 'to lie upon', from in- 'upon' and cubare 'to lie down'.","cn":"incubate 是拉丁 incubare「伏卧其上」的英语形式，由 in-「在上」与 cubare「躺下」构成。"},"items":[{"era":"LATIN CUBARE","en":"Cubare 'to lie down' is the base; its further ancestry is debated, and any Indo-European root assigned to it is a reconstruction.","cn":"cubare「躺下」是词基；其更早谱系有争议，为其指定的印欧词根属重构形式。"},{"era":"LATIN INCUBARE","en":"In- plus cubare gave incubare, used for birds on eggs and for anyone lying on a surface.","cn":"in- 加 cubare 构成 incubare，用于鸟伏卵，也用于任何人卧于表面。"},{"era":"ENGLISH VERB","en":"English borrowed the verb in the seventeenth century alongside the noun incubation, at first only for brooding.","cn":"英语在 17 世纪连同名词 incubation 一起借入这个动词，最初只用于孵卵。"},{"era":"SCIENTIFIC WIDENING","en":"Microscopy and bacteriology applied incubate to warmed cultures, and medicine applied it to the silent stage of infection.","cn":"显微学与细菌学把 incubate 用于保温培养，医学则把它用于感染的无症状阶段。"},{"era":"COMMERCIAL USE","en":"In the late twentieth century incubate was extended to start-up firms and to ideas held back from premature exposure.","cn":"20 世纪后期，incubate 被扩展到新创公司与尚未过早公开的想法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (root and first date): the pre-Latin origin of cubare is unsettled, and the first business use is not firmly dated.","cn":"来源不确定（词根与首见年代）：cubare 的拉丁前来源无定论，商业义首见年代亦不确定。"}]},"similar":{"note":{"en":"Group one separates the incubation family; group two separates incubate from the verbs of the same biological neighbourhood.","cn":"第一组区分 incubation 词族；第二组区分 incubate 与同一生物语境中的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"incubation","ipa":"/ˌɪŋkjuˈbeɪʃən/","tag":"the noun","definition":"The process or the interval; the verb names the doing, the noun names the doing as a thing.","definitionCN":"过程或时段；动词指做，名词指作为事物的这个过程。"},{"word":"incubator","ipa":"/ˈɪŋkjubeɪtə/","tag":"the instrument","definition":"The device that performs the warming, marked by -or; a person does not normally incubate with it in the same sentence.","definitionCN":"执行加温的装置，由 -or 标记；同一句里人通常不「用孵化器孵化」。"},{"word":"hatch","ipa":"/hætʃ/","tag":"break out","definition":"Hatch is the event of breaking the shell; incubate is the whole waiting period that ends in it.","definitionCN":"hatch 是破壳事件；incubate 是以此收尾的整段等待。"},{"word":"brood","ipa":"/bruːd/","tag":"sit over","definition":"Brood stresses sitting on and covering; incubate stresses the warmth and the development it allows.","definitionCN":"brood 强调伏坐覆盖；incubate 强调温度及其带来的发育。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nurture","ipa":"/ˈnɜːtʃə/","tag":"care after emergence","definition":"To nurture is to feed and support something already out; incubate covers only the hidden stage before that.","definitionCN":"nurture 是喂养支持已出现之物；incubate 只覆盖此前隐蔽的阶段。"},{"word":"cultivate","ipa":"/ˈkʌltɪveɪt/","tag":"deliberate growing","definition":"Cultivate implies tending soil, cells or skills over time; incubate implies holding under warmth without active tending.","definitionCN":"cultivate 含长期照料土壤、细胞或技能；incubate 含保温静置、不作主动照料。"},{"word":"conceive","ipa":"/kənˈsiːv/","tag":"begin an idea","definition":"To conceive is to form an idea or begin a pregnancy; incubate is what happens to it afterwards.","definitionCN":"conceive 是形成想法或受孕；incubate 是其后的发展阶段。"},{"word":"simmer","ipa":"/ˈsɪmə/","tag":"keep just below boiling","definition":"Simmer is a cooking verb for gentle heat; used of ideas it is informal, where incubate is neutral and technical.","definitionCN":"simmer 是文火慢煮的烹饪动词；用于想法显得口语，而 incubate 中性且技术化。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin parts, real collocations and real domains of use.","cn":"正常联想：真实的拉丁成分、真实搭配与真实使用领域。"},"normal":[{"en":"in- 'upon' + cubare 'lie': to lie upon the eggs.","cn":"in-「在上」+ cubare「躺」：伏在卵上。"},{"en":"The family runs incubate, incubation, incubator, incubatory.","cn":"同族词包括 incubate、incubation、incubator、incubatory。"},{"en":"Fixed phrases: incubate eggs, incubate a culture, incubate an idea.","cn":"固定搭配：孵卵、培养菌群、孕育想法。"},{"en":"Laboratory usage is literal: plates are incubated overnight.","cn":"实验室用法是字面的：培养皿过夜培养。"},{"en":"Latin cubare also gives cubicle, a small lying place.","cn":"拉丁 cubare 还衍生 cubicle，即可躺卧的小间。"}],"abstract":[{"en":"Picture a hand cupped over something until it is strong enough to be uncovered.","cn":"想象一只手罩住某物，直到它强壮到可以被揭开。"},{"en":"Picture a clock running where nobody can see it.","cn":"想象一只钟在没人看得见的地方走。"},{"en":"Picture a song being written in a room with the door shut.","cn":"想象一首歌在关着门的房间里被写出来。"}]},"examples":[{"en":"Both parents incubate, taking turns through the night.","cn":"双亲都参与孵卵，整夜轮流。"},{"en":"The samples were incubated in the dark to prevent drying.","cn":"样本在暗处培养，以防干燥。"},{"en":"He incubated the plan for months before mentioning it to the board.","cn":"他把这个计划酝酿了几个月才向董事会提起。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（在上）+ cub（躺）」——伏在蛋上不动 → 孵卵、孵化；引申为潜伏、孕育","word":"incubate"},"root":"拉丁 incubare「伏卧其上」= in-（在上）+ cubare「躺下、歇息」；cubare 更深来源有争议。英语 incubate 为同一拉丁动词的借形。","sensesIntro":{"en":"Eight senses follow one posture: a body lies over eggs and supplies steady warmth, and the same verb is then given to a machine, to cells, to a virus, to a firm and to an idea that is deliberately kept out of sight.","cn":"八个义项沿一个姿态展开：身体伏在卵上提供稳定温度；同一个动词随后交给机器、细胞、病毒、公司，以及被有意藏起来的想法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a warm hand held still over something that must not be disturbed.","cn":"核心意象：一只温热的手稳稳罩住某物，不容打扰。"},"chain":["LIE UPON","HOLD WARM","KEEP UNDISTURBED","GROW UNSEEN","EMERGE AT LAST","SHELTER EARLY GROWTH"],"branches":[{"senses":"S1 · S8","en":"LYING UPON: the literal posture is the source of every extension.","cn":"伏卧其上：实义姿态是一切引申的来源。"},{"senses":"S2 · S3","en":"HEAT SOURCE: a body or a machine, the warmth is what matters.","cn":"热源：无论是身体还是机器，要紧的是温度。"},{"senses":"S4 · S5","en":"UNSEEN MULTIPLICATION: cells and viruses grow under cover, measured only later.","cn":"不可见的增殖：细胞与病毒在被覆盖下生长，事后才可测。"},{"senses":"S6","en":"PROTECTED VENTURE: a new firm is kept warm until it can stand alone.","cn":"受保护的初创：新公司被保温到能独立站立。"},{"senses":"S7","en":"DELIBERATE DELAY: an idea is held back from exposure on purpose.","cn":"有意的延迟：想法被故意压住不公开。"}]},"affixes":{"intro":{"en":"Incubate is prefix plus root plus a Latin verb ending, and each part can be pointed at directly.","cn":"incubate 是前缀加词根加拉丁动词词尾，每一部分都可直接指出。"},"latinIntro":{"en":"Latin in- and cubare build incubare, and the same root reappears in cubicle and concubine.","cn":"拉丁 in- 与 cubare 构成 incubare，同一词根亦见于 cubicle 与 concubine。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, on')","meaning":"on; upon","meaningCN":"在上；伏于","example":"The bird lies in- over the clutch.","exampleCN":"鸟伏在一窝卵之上。"},{"word":"cubare","structure":"cubare (Latin verb, first conjugation)","meaning":"to lie, rest","meaningCN":"躺卧；歇息","example":"Cubare is the posture of rest.","exampleCN":"cubare 是歇息的姿态。"},{"word":"-ate","structure":"-ate (Latin verb ending, first conjugation)","meaning":"to do, to make","meaningCN":"做；使","example":"The ending marks a first-conjugation verb.","exampleCN":"这个词尾标记第一变位动词。"},{"word":"incubation","structure":"incubate + -ion (action noun)","meaning":"the process of warming eggs","meaningCN":"加温孵卵的过程","example":"Incubation ends when the first egg pipped.","exampleCN":"第一枚卵啄壳时孵化就结束了。"},{"word":"incubator","structure":"incubate + -or (instrument)","meaning":"the warming device","meaningCN":"加温装置","example":"The incubator turns the eggs automatically.","exampleCN":"孵化器自动翻卵。"},{"word":"incubatory","structure":"incubate + -ory (relating to)","meaning":"of or for incubation","meaningCN":"孵育的","example":"The incubatory chamber stays at thirty-seven.","exampleCN":"孵育室保持在三十七度。"},{"word":"incubating","structure":"incubate + -ing (participle)","meaning":"in the act of incubating","meaningCN":"正在孵化的","example":"The incubating adult barely eats.","exampleCN":"正在孵卵的成鸟几乎不进食。"},{"word":"cubicle","structure":"cubare + -culum (diminutive)","meaning":"a small lying place","meaningCN":"可躺卧的小间","example":"The office is a row of cubicles.","exampleCN":"办公室是一排小隔间。"},{"word":"concubine","structure":"con- + cubare + -ina","meaning":"one who lies with another","meaningCN":"同寝者；妾","example":"The word is built on the same lying root.","exampleCN":"这个词也建在同一「躺卧」词根上。"}],"latinEntries":[{"word":"cubare","structure":"cubare, cubui, cubitum (verb, first conjugation)","meaning":"to lie down, rest","meaningCN":"躺下；歇息"},{"word":"incubare","structure":"incubare, incubui, incubitum (verb, first conjugation)","meaning":"to lie upon, brood","meaningCN":"伏卧其上；孵"},{"word":"incubatio","structure":"incubatio, incubationis (f., third declension)","meaning":"a lying upon","meaningCN":"伏卧"}]}},{"word":"hatching","ipa_uk":"/ˈhætʃɪŋ/","ipa_us":"/ˈhætʃɪŋ/","definition_zh":"孵化；出壳；破壳过程；（艺术）晕线排线；阴影线","definition_en":"the process or moment in which a young animal breaks out of its egg, or a set of fine parallel lines used for shading","core_image":"蛋壳顶端出现第一条细缝，一小块壳被顶开，湿漉漉的头先探出来，壳还挂在背上","scene":"巢里的卵已经放了十九天，今天早晨第一枚壳上出现了一道裂缝。 Hatching takes most of a day, and the chick stays wet and weak for hours after it.","sceneCN":"这里 hatching 指「出壳、破壳的过程」（第 1 个义项：幼体用喙或牙顶破卵壳而出的过程）；句意为出壳要花大半天，雏鸟出壳后数小时仍湿而虚弱。","pos":[{"tag":"n.","zh":"孵化；出壳；破壳；（艺术）晕线、排线阴影"},{"tag":"v. (present participle)","zh":"正在孵化；正在策划（秘密）"}],"collocations":[{"phrase":"hatching time","zh":"出壳时间"},{"phrase":"hatching success","zh":"孵化成功率"},{"phrase":"hatching date","zh":"出壳日期"},{"phrase":"hatching asynchrony","zh":"出壳不同步"},{"phrase":"cross-hatching","zh":"交叉晕线"},{"phrase":"hatching pattern","zh":"晕线纹样"}],"forms":[{"label":"原形（动词）","form":"hatch"},{"label":"三单（he/she/it）","form":"hatches"},{"label":"过去式","form":"hatched"},{"label":"过去分词","form":"hatched"},{"label":"现在分词 / 动名词","form":"hatching"},{"label":"名词（刚出壳的幼体）","form":"hatchling"}],"derivatives":[{"word":"hatch","pos":"v./n.","zh":"孵化；破壳；孵出；（船、飞机的）舱口"},{"word":"hatchling","pos":"n.","zh":"刚出壳的幼体"},{"word":"hatchery","pos":"n.","zh":"孵化场"},{"word":"hatched","pos":"adj.","zh":"已孵出的；画有晕线的"},{"word":"hatchback","pos":"n.","zh":"掀背式汽车"}],"senses":[{"no":"01","title":"Breaking out of the egg","titleCN":"幼体顶破卵壳而出","definition":"the moment or process in which a young animal breaks the shell and leaves the egg","definitionCN":"幼体破开卵壳并离开卵的那一刻或过程","example":"Hatching takes most of a day for this species.","exampleCN":"这个物种出壳要花大半天。","why":"the -ing form names the event as an unfolding process, which suits a break that is gradual rather than instantaneous.","whyCN":"-ing 形式把事件看作逐步展开的过程，适合这种并非瞬间完成的破壳。"},{"no":"02","title":"The whole hatching period of a clutch","titleCN":"整窝卵的出壳阶段","definition":"the stretch of time over which all eggs in a nest break","definitionCN":"一巢中所有卵破壳所跨的那段时间","example":"Hatching stretched over three days because laying began early.","exampleCN":"由于产卵开始得早，出壳持续了三天。","why":"eggs laid at different times break at different times, so the event extends into a period.","whyCN":"不同时间产下的卵在不同时间破壳，因此事件延伸成一段时期。"},{"no":"03","title":"The success rate of a hatching attempt","titleCN":"一次孵化的成功率","definition":"the proportion of eggs that produce live young, as recorded in field studies","definitionCN":"在野外研究中记录的、成功孵出活幼体的卵所占比例","example":"Hatching fell to half after the cold snap.","exampleCN":"寒潮之后孵化率掉到一半。","why":"field workers count eggs in and chicks out, so the event becomes a measurable quantity.","whyCN":"野外工作者数进出的卵与雏，事件于是成为可测量的量。"},{"no":"04","title":"Staggered hatching in one nest","titleCN":"同一巢内不同步出壳","definition":"the condition in which eggs in one clutch break at intervals rather than together","definitionCN":"同一窝卵按间隔而非同时破壳的情形","example":"Staggered hatching gives the oldest chick an advantage.","exampleCN":"不同步出壳让最年长的雏占优势。","why":"the word needs only a qualifier to describe timing, since the event itself is unchanged.","whyCN":"只需加一个限定语即可描述时间安排，因为事件本身没有变化。"},{"no":"05","title":"The first food and first steps after hatching","titleCN":"出壳后的最初进食与行动","definition":"the early post-hatching stage in which a young animal learns to feed and move","definitionCN":"幼体学习取食与行动的最初阶段","example":"Hatching is followed by a day of drying out before any feeding.","exampleCN":"出壳之后要先晾干一天才开始进食。","why":"the word is used as a fixed point that later stages are measured from.","whyCN":"这个词被当作一个固定时间点，后续阶段都从它起算。"},{"no":"06","title":"Art: parallel lines used for shading","titleCN":"美术：用平行细线作阴影","definition":"in drawing and engraving, a set of closely spaced parallel lines that create tone","definitionCN":"绘画与版画中一组密集平行线，用来制造明暗层次","example":"Fine hatching gives the cheek its roundness.","exampleCN":"细密的晕线让面颊显出圆润。","why":"the older artistic sense comes from hatching as cutting lines into a surface, and it survives unchanged in studio vocabulary.","whyCN":"较早的美术义来自在表面上刻划线条的 hatching，这一义在画室术语中完整保留。"},{"no":"07","title":"Crossed lines for deeper shadow","titleCN":"交叉排线加深阴影","definition":"two or more sets of hatching laid over each other to darken an area","definitionCN":"两组或更多排线叠在一起使某区域更暗","example":"Cross hatching turned the corner of the wall almost black.","exampleCN":"交叉排线把墙角压得几乎全黑。","why":"the compound merely states that the lines cross, so the base meaning is unchanged.","whyCN":"复合词只说线是交叉的，词基意义并无改变。"},{"no":"08","title":"Figurative: a secret being prepared","titleCN":"比喻：秘密正在被酝酿出来","definition":"figurative, the developing stage of a plot or scheme before it is revealed","definitionCN":"比喻用法，指阴谋或计划在公开之前的发展阶段","example":"They were hatching a plan all winter in the back room.","exampleCN":"他们整个冬天都在后屋里悄悄策划一个方案。","why":"the metaphor keeps the image of something growing out of sight until it suddenly appears.","whyCN":"比喻保留了「某物在看不见处长成，然后突然出现」的意象。"}],"etymology":{"intro":{"en":"Hatching is the -ing form of hatch, a Germanic verb with a disputed deeper origin and a separate artistic sense.","cn":"hatching 是 hatch 的 -ing 形式；hatch 是日耳曼动词，其更深来源有争议，另有一条独立的美术义。"},"items":[{"era":"MIDDLE ENGLISH HACCHE","en":"Middle English hacche meant the act of brooding and of breaking the shell; the form is shared with Middle Dutch and Middle Low German.","cn":"中古英语 hacche 指伏窝与破壳的行为，其形式与中古荷兰语、中古低地德语共有。"},{"era":"GERMANIC STOCK","en":"The Germanic verb carried the idea of producing young from an egg, and also of cutting lines, which produced the artistic sense.","cn":"这个日耳曼动词带「由卵生幼」的意思，也带「刻划线条」的意思，后者产生了美术义。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the pre-Germanic origin of hatch is unresolved; the common Indo-European form quoted for it is a reconstruction.","cn":"来源不确定（词根）：hatch 在日耳曼语之前的来源无定论；常引的印欧形式属重构。"},{"era":"ARTISTIC SENSE","en":"From the fifteenth century hatching named short parallel strokes in drawing, probably from the idea of cutting or striking lines.","cn":"自 15 世纪起，hatching 指绘画中的短平行笔触，可能源自「刻、划线条」的想法。"},{"era":"-ING AS A NAME","en":"The -ing form became the standard name for the event, so field reports speak of hatching success and hatching date.","cn":"-ing 形式成为事件的标准名称，因此野外报告说 hatching success 与 hatching date。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest record of hatching in its technical sense is not firmly dated, and the link between the two senses is inferred rather than documented.","cn":"来源不确定（首见年代）：hatching 技术义的最早书证年代不确定，两个义项之间的联系属推断，未见直接文献。"}]},"similar":{"note":{"en":"Group one separates the hatch family; group two separates the biological hatching from the stages around it.","cn":"第一组区分 hatch 词族；第二组区分生物学意义上的出壳与其前后阶段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hatch","ipa":"/hætʃ/","tag":"the verb or the opening","definition":"The bare verb is to break out or to plan secretly; as a noun it is a hatchway or opening, not the process.","definitionCN":"原形动词指破壳或秘密策划；作名词指舱口、开口，而不是这一过程。"},{"word":"hatchling","ipa":"/ˈhætʃlɪŋ/","tag":"the newly emerged animal","definition":"A hatchling is the animal just out of the egg; hatching is the event, hatchling is its result.","definitionCN":"hatchling 是刚出壳的动物；hatching 是事件，hatchling 是其结果。"},{"word":"hatchery","ipa":"/ˈhætʃəri/","tag":"the place","definition":"A hatchery is where eggs are hatched commercially; the -ery suffix marks a place of activity.","definitionCN":"hatchery 是商业孵卵的场所；-ery 后缀标记活动场所。"},{"word":"hatchback","ipa":"/ˈhætʃbæk/","tag":"an unrelated compound","definition":"Hatchback names a car body style by its rear hatch; it has nothing to do with eggs.","definitionCN":"hatchback 以车尾舱门命名一种车身式样，与卵无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"incubation","ipa":"/ˌɪŋkjuˈbeɪʃən/","tag":"the waiting before","definition":"Incubation is the warming period that ends in hatching, so the two are consecutive stages.","definitionCN":"incubation 是以出壳收尾的保温期，两者是连续的两个阶段。"},{"word":"emergence","ipa":"/ɪˈmɜːdʒəns/","tag":"coming out","definition":"Emergence is any coming out, including insects from pupae; hatching is specific to eggs.","definitionCN":"emergence 泛指任何出现，包括昆虫自蛹中出来；hatching 专指自卵而出。"},{"word":"eclosion","ipa":"/ɪˈkləʊʒən/","tag":"technical term","definition":"Eclosion is the entomologist's word for emerging from an egg or pupa, narrower than hatching.","definitionCN":"eclosion 是昆虫学中自卵或蛹出来的术语，比 hatching 更窄。"},{"word":"stippling","ipa":"/ˈstɪplɪŋ/","tag":"dots, not lines","definition":"Stippling is shading made of dots; hatching is shading made of lines, a common confusion in drawing.","definitionCN":"stippling 用点作阴影；hatching 用线作阴影，素描中常混。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphology, real field terms and real studio vocabulary.","cn":"正常联想：真实形态、真实现场术语与真实画室词汇。"},"normal":[{"en":"hatch + -ing: the verb of breaking out turned into the name of the event.","cn":"hatch + -ing：破壳动词转为事件名称。"},{"en":"The family runs hatch, hatching, hatchling, hatchery, hatched.","cn":"同族词包括 hatch、hatching、hatchling、hatchery、hatched。"},{"en":"Field phrases: hatching success, hatching date, hatching asynchrony.","cn":"现场搭配：孵化成功率、出壳日期、不同步出壳。"},{"en":"In drawing, cross hatching darkens an area with two sets of lines.","cn":"在素描中，交叉排线用两组线把区域压暗。"},{"en":"The idiom hatch a plan reuses the egg image for secrets.","cn":"习语 hatch a plan 把卵的意象用于秘密。"}],"abstract":[{"en":"Picture a crack that spreads slowly, then suddenly gives way.","cn":"想象一道裂缝慢慢延伸，然后突然让开。"},{"en":"Picture two kinds of shade, one drawn with dots, one with strokes.","cn":"想象两种阴影，一种用点画，一种用笔画。"},{"en":"Picture a plan growing in the dark until the day it is spoken aloud.","cn":"想象一个计划在暗处长成，直到被说出口的那一天。"}]},"examples":[{"en":"Hatching began at dawn and was over by noon.","cn":"出壳在黎明开始，中午前结束。"},{"en":"The engraver used dense hatching for the shadowed half of the face.","cn":"版画师用密集晕线处理脸部的暗面。"},{"en":"Cold nights can delay hatching by nearly a week.","cn":"寒夜可让出壳推迟将近一周。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hatch（破壳）+ ing」——壳破小兽出 → 出壳、孵化；美术义为一条条排出的线","word":"hatching"},"root":"中古英语 hacche「孵、破壳」，与中古荷兰语、中古低地德语同形，属日耳曼词；美术义「刻划线条」为另一条引申线；日耳曼语之前的词根来源不确定。","sensesIntro":{"en":"Eight senses follow one break: a shell splits and something wet emerges, and the word then names the period, the success rate, the timing pattern, the stage after it, two kinds of drawn line, and finally a plan that emerges the same way.","cn":"八个义项沿一次破裂展开：壳裂开，一个湿漉漉的东西出来；词语随后指这段时期、成功率、时间格局、其后阶段、两种描画线条，最后指以同样方式出现的计划。"},"semanticMap":{"core":{"en":"CORE IMAGE: the first crack at the top of an egg, and a wet head pushing through it.","cn":"核心意象：卵顶的第一道裂缝，一颗湿漉漉的头从中顶出。"},"chain":["SHELL CRACKS","BODY EMERGES","SPREAD OVER TIME","COUNT THE RESULT","FIRST STEPS OUTSIDE","LINES THAT CUT SHADE"],"branches":[{"senses":"S1 · S8","en":"EMERGENCE: the literal break and the figurative plan share one shape.","cn":"出现：字面的破壳与比喻的计划共享同一形状。"},{"senses":"S2 · S4","en":"TIMING: eggs break at intervals, so the event expands into a schedule.","cn":"时序：卵按间隔破壳，事件于是扩展成一张时间表。"},{"senses":"S3","en":"COUNTED RESULT: what comes out can be counted against what went in.","cn":"可数的结果：出来的可以与进去的对照计数。"},{"senses":"S5","en":"MARKER POINT: later stages are dated from the break.","cn":"标记点：后续阶段从破壳起算。"},{"senses":"S6 · S7","en":"CUT LINES: the studio sense shades with strokes, crossed or single.","cn":"刻线：画室义用单层或交叉的笔触作阴影。"}]},"affixes":{"intro":{"en":"Hatching is a native verb plus the English -ing ending; its artistic sense grew inside English, not from Latin.","cn":"hatching 是本族动词加英语 -ing 词尾；美术义是在英语内部长成的，并非来自拉丁语。"},"latinIntro":{"en":"There is no Latin element in hatch; the Latin entries below are the learned words English borrowed separately for hatching and for emerging.","cn":"hatch 不含拉丁成分；下列拉丁条目是英语为「孵化」与「出现」另行借入的学术词。"},"items":[{"word":"hatch","structure":"hatch (Middle English verb)","meaning":"to break out of an egg","meaningCN":"破壳而出","example":"The first egg hatched at dawn.","exampleCN":"第一枚卵在黎明破壳。"},{"word":"-ing","structure":"-ing (gerund ending)","meaning":"the act or event","meaningCN":"动作或事件","example":"Hatching is a slow business.","exampleCN":"出壳是件缓慢的事。"},{"word":"-ling","structure":"hatchling = hatch + -ling (diminutive)","meaning":"a small newly hatched one","meaningCN":"刚出壳的幼小者","example":"The hatchling could not stand yet.","exampleCN":"雏还站不起来。"},{"word":"-ery","structure":"hatchery = hatch + -ery (place)","meaning":"a place for hatching","meaningCN":"孵化的场所","example":"The hatchery releases fry into the river.","exampleCN":"孵化场把鱼苗放流到河里。"},{"word":"-ed","structure":"hatched = hatch + -ed (participle)","meaning":"already out of the egg","meaningCN":"已出壳的","example":"The hatched chicks were moved to a brooder.","exampleCN":"已出壳的雏被移进育雏箱。"},{"word":"cross-hatching","structure":"cross + hatching (compound)","meaning":"crossed shading lines","meaningCN":"交叉的阴影线","example":"Cross-hatching deepens the shadow.","exampleCN":"交叉排线加深了阴影。"},{"word":"hatching success","structure":"hatching + success (compound)","meaning":"the rate of eggs that produce young","meaningCN":"成功孵出的比率","example":"Hatching success dropped after the flood.","exampleCN":"洪水之后孵化成功率下降。"},{"word":"hatch a plan","structure":"hatch + a plan (idiom)","meaning":"to devise a plan secretly","meaningCN":"秘密策划","example":"They hatched a plan over the winter.","exampleCN":"他们在冬天里策划了一套方案。"},{"word":"hatchway","structure":"hatch + way (compound)","meaning":"an opening in a deck","meaningCN":"甲板上的舱口","example":"The hatchway was left open.","exampleCN":"舱口一直开着。"}],"latinEntries":[{"word":"excludere","structure":"excludere, exclusi, exclusum (verb, third conjugation)","meaning":"to shut out; of a chick, to hatch out","meaningCN":"关在外；指雏出壳"},{"word":"eclosio","structure":"eclosio, eclosionis (f., third declension, post-classical)","meaning":"a hatching out","meaningCN":"孵出"},{"word":"ova","structure":"ovum, ovi (n., second declension, plural ova)","meaning":"egg","meaningCN":"卵"}]}},{"word":"hatchling","ipa_uk":"/ˈhætʃlɪŋ/","ipa_us":"/ˈhætʃlɪŋ/","definition_zh":"刚出壳的幼体；幼雏；（爬行类、鸟类等的）初生个体","definition_en":"a young animal that has just come out of its egg","core_image":"一只刚出壳的小龟只有拇指盖大小，背甲还是软的，正从沙里往上顶，沙粒挂在身上","scene":"沙滩上的巢穴在夜里裂开，一串小龟从沙里钻出来，朝海的方向爬。 Each hatchling follows the brightest line it can see toward the water.","sceneCN":"这里 hatchling 指「刚出壳的幼体」（第 1 个义项：刚从卵中出来的幼小个体）；句意为每只刚出壳的小龟都朝着它能看到的最亮的一条线爬向海水。","pos":[{"tag":"n.","zh":"刚出壳的幼体；幼雏"}],"collocations":[{"phrase":"sea turtle hatchling","zh":"刚出壳的海龟幼体"},{"phrase":"hatchling survival","zh":"幼雏存活率"},{"phrase":"hatchling weight","zh":"雏体体重"},{"phrase":"newly hatched hatchling","zh":"刚出壳的幼体"},{"phrase":"hatchling emergence","zh":"幼体出巢"},{"phrase":"bird hatchling","zh":"鸟的雏鸟"}],"forms":[{"label":"原形","form":"hatchling"},{"label":"复数","form":"hatchlings"},{"label":"同根动词","form":"hatch"},{"label":"同根名词（过程）","form":"hatching"},{"label":"同根名词（场所）","form":"hatchery"}],"derivatives":[{"word":"hatch","pos":"v./n.","zh":"孵化；破壳；舱口"},{"word":"hatching","pos":"n.","zh":"出壳；晕线"},{"word":"hatchery","pos":"n.","zh":"孵化场"},{"word":"hatchling-stage","pos":"adj.","zh":"出壳阶段的"},{"word":"hatchling mortality","pos":"n.","zh":"幼体死亡率"}],"senses":[{"no":"01","title":"An animal just out of the egg","titleCN":"刚从卵中出来的幼体","definition":"a young animal at the stage immediately after leaving the egg","definitionCN":"刚离开卵、处于最初阶段的幼小动物","example":"Each hatchling follows the brightest line toward the water.","exampleCN":"每只刚出壳的小龟都朝最亮的一条线爬向海水。","why":"the -ling suffix marks something small and young, so hatchling means the little creature produced by hatching.","whyCN":"-ling 后缀标记小而年幼之物，因此 hatchling 指由出壳产生的那只小生物。"},{"no":"02","title":"A newly hatched bird","titleCN":"刚出壳的鸟（雏鸟）","definition":"a baby bird that has just broken the shell, before it can stand or feed itself","definitionCN":"刚破壳、尚不能站立或自行取食的幼鸟","example":"The hatchling opened its beak at every sound.","exampleCN":"雏鸟一有声响就张开嘴。","why":"birds are the commonest case in everyday use, so the word usually brings the image of an altricial chick.","whyCN":"鸟类是日常语境中最常见的情形，因此这个词通常唤起晚成雏的形象。"},{"no":"03","title":"A reptile or amphibian at emergence","titleCN":"爬行类或两栖类刚出壳的个体","definition":"a young reptile, amphibian or fish that has just left its egg or egg case","definitionCN":"刚离开卵或卵鞘的幼年爬行类、两栖类或鱼类","example":"A turtle hatchling must reach the sea before daylight.","exampleCN":"刚出壳的小龟必须在日光出现前到达海边。","why":"the suffix is not tied to birds, so the word serves wherever eggs hatch, including sand nests and egg cases.","whyCN":"这个后缀并不绑定鸟类，因此凡有卵孵化之处都可用，包括沙中巢与卵鞘。"},{"no":"04","title":"An insect just out of the egg","titleCN":"刚从卵中孵出的昆虫","definition":"the first larval or nymphal stage of an insect after eclosion","definitionCN":"昆虫孵化之后的最初幼虫或若虫阶段","example":"The hatchling caterpillar ate its own eggshell first.","exampleCN":"刚孵出的毛虫先吃掉自己的卵壳。","why":"entomology uses the same word for first-stage larvae, since the act is the same eclosion.","whyCN":"昆虫学用同一个词指第一阶段幼虫，因为行为同样是孵化。"},{"no":"05","title":"A size class in field surveys","titleCN":"野外调查中的一个体长等级","definition":"a category of animals grouped by the stage just after hatching for counting","definitionCN":"为计数方便，把刚孵化不久的个体归入的一类","example":"Surveyors counted hatchlings separately from juveniles.","exampleCN":"调查者把幼体与亚成体分开计数。","why":"when the exact age is unknown, stage names become counting units, and hatchling marks the youngest class.","whyCN":"年龄不可知时，阶段名就成为计数单位，hatchling 标记最年幼的一档。"},{"no":"06","title":"A fragile young bred in a hatchery","titleCN":"孵化场中人工孵出的幼苗","definition":"a young fish or bird from a commercial hatchery, released or moved soon after hatching","definitionCN":"来自商业孵化场、出壳后不久即放流或转移的幼鱼或幼鸟","example":"The river was restocked with hatchery hatchlings.","exampleCN":"河里补充了孵化场孵出的幼苗。","why":"the word describes the stage, not the origin, so hatchery stock takes it without qualification.","whyCN":"这个词描述的是阶段而非来源，因此孵化场产出的个体无需限定即可使用。"},{"no":"07","title":"The earliest vulnerable life stage","titleCN":"最脆弱的最初生命阶段","definition":"the stage at which the animal is most exposed to cold, hunger and predators","definitionCN":"动物最容易受寒、挨饿与被捕食的阶段","example":"Most hatchling deaths happen in the first two days.","exampleCN":"多数幼体的死亡发生在最初两天。","why":"because this stage carries almost all early mortality, the word appears in survival statistics rather than in friendly descriptions.","whyCN":"因为早期死亡几乎都集中在这一阶段，这个词多出现在存活率统计里，而不是亲切的描写里。"},{"no":"08","title":"Figurative: a raw new arrival","titleCN":"比喻：刚出道的生手","definition":"figurative, a person who has just entered a field and still needs protection","definitionCN":"比喻用法，指刚进入某领域、仍需保护的从业者","example":"Treat the hatchling reporters gently in their first month.","exampleCN":"对待刚上岗的记者，头一个月要宽容些。","why":"the metaphor keeps two features only: the very recent beginning and complete inexperience.","whyCN":"比喻只保留两个特征：开端极近，以及完全没有经验。"}],"etymology":{"intro":{"en":"Hatchling is an English compound of hatch plus the diminutive suffix -ling, a word recorded only in the modern period.","cn":"hatchling 是英语复合词，由 hatch 加指小后缀 -ling 构成，其记录仅见于近代。"},"items":[{"era":"HATCH","en":"The verb hatch, from Middle English hacche, meant to bring forth or break out of an egg before this compound appeared.","cn":"动词 hatch 出自中古英语 hacche，在本复合词出现之前已表示「产出、破壳」。"},{"era":"-LING SUFFIX","en":"The Germanic diminutive -ling marks small, young or subordinate beings, as in duckling, nestling and yearling.","cn":"日耳曼指小后缀 -ling 标记小而年幼或次要之物，如 duckling、nestling、yearling。"},{"era":"MODERN COMPOUND","en":"Hatchling was formed inside English and is recorded from the nineteenth century, when natural history writing expanded its vocabulary for young stages.","cn":"hatchling 在英语内部构成，19 世纪起有记录，正值博物学写作扩充幼体阶段词汇之时。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the pre-Germanic origin of hatch is unresolved; the Indo-European form often quoted is reconstructed, not attested.","cn":"来源不确定（词根）：hatch 在日耳曼语之前的来源无定论；常引的印欧形式属重构，并非有证。"},{"era":"ECOLOGICAL USE","en":"In the twentieth century the term settled into conservation and fisheries, where hatchling survival is a standard measure.","cn":"20 世纪这个词在保育与渔业中定型，hatchling survival 成为标准指标。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact earliest written use of hatchling is not firmly dated, so the dating here is approximate.","cn":"来源不确定（首见年代）：hatchling 最早书证的确切年代不详，此处年代为约数。"}]},"similar":{"note":{"en":"Group one separates the words that share the -ling ending; group two separates hatchling from other young-animal stages.","cn":"第一组区分共用 -ling 后缀的词；第二组区分 hatchling 与其它幼体阶段词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hatching","ipa":"/ˈhætʃɪŋ/","tag":"the event","definition":"Hatching is the breaking-out process; hatchling is the animal that results from it.","definitionCN":"hatching 是破壳过程；hatchling 是由此产生的动物。"},{"word":"nestling","ipa":"/ˈnestlɪŋ/","tag":"still in the nest","definition":"A nestling is a bird still confined to the nest; a hatchling may leave the nest within hours, as ducklings do.","definitionCN":"nestling 是仍困在巢中的鸟；hatchling 可数小时内离巢，如小鸭。"},{"word":"duckling","ipa":"/ˈdʌklɪŋ/","tag":"species-specific","definition":"Duckling names the young of one species; hatchling names the stage, whatever the species.","definitionCN":"duckling 指某一物种的幼体；hatchling 指阶段，不分物种。"},{"word":"yearling","ipa":"/ˈjɪəlɪŋ/","tag":"age-based","definition":"A yearling is an animal in its second year; hatchling marks days rather than a year.","definitionCN":"yearling 是进入第二年的动物；hatchling 以天计，而非以年计。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chick","ipa":"/tʃɪk/","tag":"everyday word","definition":"Chick is the plain word for a young bird; hatchling is the technical word used across egg-laying groups.","definitionCN":"chick 是幼鸟的日常词；hatchling 是跨卵生类群使用的技术词。"},{"word":"larva","ipa":"/ˈlɑːvə/","tag":"insect stage","definition":"A larva is the feeding stage of an insect after hatching; hatchling names only the first instant of that stage.","definitionCN":"larva 是昆虫孵化后的取食阶段；hatchling 只指该阶段的最初时刻。"},{"word":"fry","ipa":"/fraɪ/","tag":"fish specific","definition":"Fry is the fisheries word for newly hatched fish; hatchling is the general biological term.","definitionCN":"fry 是渔业中刚孵化鱼类的词；hatchling 是通用生物学术语。"},{"word":"neonate","ipa":"/ˈniːəneɪt/","tag":"medical register","definition":"Neonate is a clinical word for a newborn, usually of mammals; hatchling is for egg layers.","definitionCN":"neonate 是临床词，指新生个体，多用于哺乳类；hatchling 用于卵生类。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real suffix, real field terms and real sibling words.","cn":"正常联想：真实后缀、真实现场术语与真实同缀词。"},"normal":[{"en":"hatch + -ling: the small one produced by hatching.","cn":"hatch + -ling：由出壳产生的小个体。"},{"en":"The family runs hatch, hatching, hatchling, hatchery.","cn":"同族词包括 hatch、hatching、hatchling、hatchery。"},{"en":"Fixed phrases: hatchling survival, hatchling emergence, sea turtle hatchling.","cn":"固定搭配：幼体存活率、幼体出巢、刚出壳的海龟。"},{"en":"The -ling ending also builds nestling, duckling and yearling.","cn":"-ling 后缀还构成 nestling、duckling、yearling。"},{"en":"Conservation writing pairs hatchling with mortality almost as often as with survival.","cn":"保育写作中 hatchling 与 mortality 的搭配几乎和与 survival 一样常见。"}],"abstract":[{"en":"Picture a thing so new that the shell it came from is still beside it.","cn":"想象一个东西新到它出来的壳还在旁边。"},{"en":"Picture a soft shell that hardens only after the dangerous first mile.","cn":"想象一层软壳，要爬过危险的第一段路才变硬。"},{"en":"Picture a newcomer whose mistakes are forgiven for exactly one month.","cn":"想象一个新手，其错误只在头一个月被原谅。"}]},"examples":[{"en":"A single hatchling can be worth more than the whole clutch to researchers.","cn":"对研究者而言，一只幼体可能比整窝卵更有价值。"},{"en":"The hatchling weighed barely thirty grams at emergence.","cn":"这只幼体出壳时体重不过三十克。"},{"en":"Predators take most hatchlings in the first hour after they leave the nest.","cn":"捕食者在幼体离巢后的第一个小时里带走大部分。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hatch（破壳）+ ling（小）」——刚破壳的小东西 → 刚出壳的幼体","word":"hatchling"},"root":"hatch「破壳、孵出」+ 日耳曼指小后缀 -ling；hatch 出自中古英语 hacche，日耳曼语之前的词根来源不确定。hatchling 为英语内部近代构词。","sensesIntro":{"en":"Eight senses follow one newborn: a small wet animal leaves the shell, and the word then names the bird case, the reptile case, the insect case, a survey class, a hatchery product, the most fragile stage, and finally a raw newcomer among people.","cn":"八个义项沿一个新生个体展开：一只湿漉漉的小动物离开卵壳；词语随后指鸟的情形、爬行类的情形、昆虫的情形、调查中的一档、孵化场的产品、最脆弱的阶段，最后指人群中刚出道的生手。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thumb-sized body pushing up through sand, its shell still soft.","cn":"核心意象：拇指大小的身体从沙里往上顶，背甲还是软的。"},"chain":["OUT OF THE EGG","SMALL AND WET","BIRD OR REPTILE","FIRST INSECT STAGE","COUNTED CLASS","MOST FRAGILE HOURS"],"branches":[{"senses":"S1 · S2","en":"NEWLY OUT: the core stage, most often met as a baby bird.","cn":"刚出来：核心阶段，最常以雏鸟形式出现。"},{"senses":"S3 · S4","en":"EGG LAYERS WIDE: reptiles, amphibians and insects all qualify.","cn":"卵生类全覆盖：爬行类、两栖类与昆虫都算。"},{"senses":"S5","en":"COUNTED YOUNGEST CLASS: surveys need a name for the youngest group.","cn":"可数的最幼一档：调查需要最年幼群体的名称。"},{"senses":"S6 · S7","en":"PRODUCED AND EXPOSED: hatchery stock and early mortality belong to the same stage.","cn":"被产出与被暴露：孵化场产品与早期死亡属于同一阶段。"},{"senses":"S8","en":"HUMAN METAPHOR: an inexperienced newcomer keeps only the newness, not the shell.","cn":"人的比喻：生手只保留「新」，不保留卵壳。"}]},"affixes":{"intro":{"en":"Hatchling is a Germanic root plus a Germanic diminutive suffix, and both parts are still productive in English.","cn":"hatchling 是日耳曼词根加日耳曼指小后缀，两部分在英语中仍有能产性。"},"latinIntro":{"en":"No Latin element is present in hatchling; the Latin entries below are borrowed terms for the same newborn stage.","cn":"hatchling 不含拉丁成分；下列拉丁条目是为同一初生阶段借入的术语。"},"items":[{"word":"hatch","structure":"hatch (verb, Middle English hacche)","meaning":"to break out of an egg","meaningCN":"破壳而出","example":"The eggs hatch in late spring.","exampleCN":"卵在晚春孵出。"},{"word":"-ling","structure":"-ling (Germanic diminutive suffix)","meaning":"small, young or subordinate","meaningCN":"小、年幼或次要","example":"The suffix marks the small one.","exampleCN":"这个后缀标记小者。"},{"word":"hatching","structure":"hatch + -ing (gerund)","meaning":"the event of emerging","meaningCN":"出壳事件","example":"Hatching began before dawn.","exampleCN":"出壳在黎明前开始。"},{"word":"hatchery","structure":"hatch + -ery (place)","meaning":"a place where eggs are hatched","meaningCN":"孵卵场所","example":"The hatchery supplies local ponds.","exampleCN":"孵化场供应本地池塘。"},{"word":"nestling","structure":"nest + -ling","meaning":"a bird still in the nest","meaningCN":"仍在巢中的雏鸟","example":"Nestlings need warmth more than food.","exampleCN":"巢中雏更需要温度而非食物。"},{"word":"duckling","structure":"duck + -ling","meaning":"a young duck","meaningCN":"小鸭","example":"The ducklings left the nest at once.","exampleCN":"小鸭立刻离巢。"},{"word":"yearling","structure":"year + -ling","meaning":"an animal in its second year","meaningCN":"进入第二年的动物","example":"The yearlings grazed apart from the herd.","exampleCN":"一岁兽离群吃草。"},{"word":"hatchling survival","structure":"hatchling + survival (compound)","meaning":"the rate of young that live","meaningCN":"幼体存活率","example":"Hatchling survival is lowest on cold beaches.","exampleCN":"寒冷海滩上的幼体存活率最低。"},{"word":"hatchling mortality","structure":"hatchling + mortality (compound)","meaning":"the rate of young that die","meaningCN":"幼体死亡率","example":"Hatchling mortality peaks at dawn.","exampleCN":"幼体死亡率在黎明达到峰值。"}],"latinEntries":[{"word":"pullus","structure":"pullus, pulli (m., second declension)","meaning":"young animal, chick","meaningCN":"幼兽；雏"},{"word":"fetus","structure":"fetus, fetus (m., fourth declension)","meaning":"offspring, young","meaningCN":"后代；幼体"},{"word":"ovo","structure":"ovum, ovi (n., second declension)","meaning":"egg","meaningCN":"卵"}]}},{"word":"insect","ipa_uk":"/ˈɪnsekt/","ipa_us":"/ˈɪnsekt/","definition_zh":"昆虫；虫；（贬义）渺小的人；可鄙的人","definition_en":"a small animal with a body in three parts, six legs and usually wings, and often a pair of antennae","core_image":"一只甲虫停在叶背上，身体被两道细缝分成头、胸、腹三节，六只脚紧扣叶面，鞘翅像两片合上的门","scene":"孩子在灯下翻开图册，指着一种有六条腿、身体分三节的小生物问它叫什么。 A single insect may visit hundreds of flowers in one warm afternoon.","sceneCN":"这里 insect 指「昆虫」（第 1 个义项：身体分头胸腹三节、六足的小型节肢动物）；句意为一个温暖的下午里，一只昆虫可能访问上百朵花。","pos":[{"tag":"n.","zh":"昆虫；虫；（贬义）渺小可鄙的人"},{"tag":"adj.","zh":"昆虫的；像昆虫的"}],"collocations":[{"phrase":"insect species","zh":"昆虫物种"},{"phrase":"insect bite","zh":"虫咬"},{"phrase":"insect pest","zh":"害虫"},{"phrase":"insect population","zh":"昆虫种群"},{"phrase":"insect diversity","zh":"昆虫多样性"},{"phrase":"insect-borne disease","zh":"虫媒疾病"},{"phrase":"social insect","zh":"社会性昆虫"}],"forms":[{"label":"原形","form":"insect"},{"label":"复数","form":"insects"},{"label":"形容词","form":"insectan"},{"label":"同根形容词","form":"insectile"},{"label":"同根名词（杀虫剂）","form":"insecticide"}],"derivatives":[{"word":"insecticide","pos":"n.","zh":"杀虫剂"},{"word":"insectivorous","pos":"adj.","zh":"食虫的"},{"word":"insectile","pos":"adj.","zh":"昆虫的；像昆虫的"},{"word":"insectan","pos":"adj.","zh":"昆虫纲的"},{"word":"insectary","pos":"n.","zh":"昆虫饲养室"}],"senses":[{"no":"01","title":"A six-legged animal in three body parts","titleCN":"身体分三节、六足的小动物","definition":"a small invertebrate with a segmented body of head, thorax and abdomen, six legs and usually wings","definitionCN":"身体分为头、胸、腹三节、有六足、通常有翅的小型无脊椎动物","example":"A single insect may visit hundreds of flowers in one afternoon.","exampleCN":"一个下午里，一只昆虫可能访问上百朵花。","why":"Latin insectum means 'cut into', because the body appears divided into sections, and that visible cutting is the core of the word.","whyCN":"拉丁 insectum 意为「被切开」，因身体看起来分成几段；这种可见的分节就是词的核心。"},{"no":"02","title":"Any small crawling creature, loosely","titleCN":"口语中泛称各种小虫","definition":"in everyday speech, any small crawling or flying invertebrate, including spiders and worms","definitionCN":"日常口语中泛指各种小型爬行或飞行的无脊椎动物，包括蜘蛛与蠕虫","example":"Most people call a spider an insect without thinking.","exampleCN":"多数人不加思索地把蜘蛛叫作昆虫。","why":"lay usage groups small invertebrates by size and behaviour rather than by leg count, so the word widens beyond the technical class.","whyCN":"日常用法按大小与行为归类，而不是按足数归类，因此这个词超出了严格的分类范围。"},{"no":"03","title":"Insect pests of crops and stores","titleCN":"农作物与仓储中的害虫","definition":"insects treated as pests that damage crops, stored grain or timber","definitionCN":"被视为危害作物、储粮或木材的害虫的昆虫","example":"The stored grain was treated to kill insect pests.","exampleCN":"储粮经过处理以杀死害虫。","why":"an economic role narrows the word to those species that cause measurable loss.","whyCN":"经济角色把词义收窄到那些造成可测损失的物种。"},{"no":"04","title":"Vectors of human disease","titleCN":"传播人类疾病的媒介昆虫","definition":"insects that carry pathogens from one host to another","definitionCN":"把病原从一个宿主带到另一个宿主的昆虫","example":"Mosquitoes are the insect most often blamed for malaria.","exampleCN":"蚊子是最常被归咎于疟疾传播的昆虫。","why":"public health reuses the plain noun because the insect itself is the delivery mechanism, not the disease.","whyCN":"公共卫生沿用这个普通名词，因为传递机制是昆虫本身，而非疾病。"},{"no":"05","title":"Pollinators and food webs","titleCN":"传粉者与食物网中的一环","definition":"insects seen as pollinators, prey or decomposers within an ecosystem","definitionCN":"在生态系统中作为传粉者、猎物或分解者的昆虫","example":"Insect diversity is a rough measure of habitat health.","exampleCN":"昆虫多样性是生境健康的一个粗略指标。","why":"once insects are counted as a group, the word becomes an ecological category rather than an individual animal.","whyCN":"一旦把昆虫作为整体来计数，这个词就成了生态类别，而不再是个别动物。"},{"no":"06","title":"Social insects in colonies","titleCN":"群体生活的社会性昆虫","definition":"species such as ants, termites and bees that live in organised colonies with division of labour","definitionCN":"蚂蚁、白蚁、蜜蜂等在群体中分工生活的物种","example":"Social insects solve tasks no single individual could.","exampleCN":"社会性昆虫能解决任何个体单独做不到的任务。","why":"the qualifier social marks a special organisation of the same class, not a different animal.","whyCN":"限定语 social 标记同一类群中特殊的组织方式，而非另一种动物。"},{"no":"07","title":"Insect life stages as an object of study","titleCN":"作为研究对象的昆虫生活史","definition":"the insect as a subject of laboratory or field study, including its stages and behaviour","definitionCN":"作为实验室或野外研究对象的昆虫，包含其阶段与行为","example":"The lab keeps a colony of this insect for genetic work.","exampleCN":"实验室饲养这一昆虫的群体用于遗传研究。","why":"when a whole life cycle is reared in a room, the animal becomes a research system.","whyCN":"当一个完整生活史在室内被饲养，这种动物就成了研究体系。"},{"no":"08","title":"An insignificant or contemptible person","titleCN":"渺小可鄙的人（贬义）","definition":"derogatory, a person regarded as small, weak or worthless","definitionCN":"贬义，指被视为渺小、软弱或毫无价值的人","example":"He called his rival a miserable little insect.","exampleCN":"他把对手称作一只可怜的小虫。","why":"the metaphor keeps only size and insignificance, which is why the word stings when applied to a person.","whyCN":"比喻只保留「小」与「无足轻重」，这正是它加在人身上会刺人的原因。"}],"etymology":{"intro":{"en":"Insect comes from Latin insectum, a calque of Greek entomon, both meaning 'cut into' because the body is divided into segments.","cn":"insect 来自拉丁 insectum，是对希腊 entomon 的仿译，两者都意为「被切开」，因身体分成段落。"},"items":[{"era":"GREEK ENTOMON","en":"Greek entomon, from en- 'in' plus temnein 'to cut', described animals whose bodies were notched or divided.","cn":"希腊 entomon 由 en-「在内」加 temnein「切」构成，描述身体有刻痕或分段的动物。"},{"era":"LATIN INSECTUM","en":"Latin writers translated the Greek idea with insectum, literally 'cut into', from in- plus secare 'to cut'.","cn":"拉丁作者用 insectum 转译这一希腊观念，字面为「被切入」，由 in- 加 secare「切」构成。"},{"era":"SCIENTIFIC CLASS","en":"In the eighteenth century insect was fixed to the six-legged class, while everyday speech kept the older loose reach.","cn":"18 世纪 insect 被固定指六足纲，而日常口语保留较早的宽泛范围。"},{"era":"SENSE TRANSFER","en":"The idea of smallness and insignificance produced the insulting sense of a contemptible person.","cn":"「小」与「无足轻重」的想法产生了指可鄙之人的侮辱义。"},{"era":"COMPOUND GROWTH","en":"Insect became the base of insecticide, insectivorous and insectary as applied entomology grew.","cn":"随着应用昆虫学发展，insect 成为 insecticide、insectivorous、insectary 的词基。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact earliest English record of the insulting sense is not firmly dated; the root itself is clear.","cn":"来源不确定（首见年代）：侮辱义最早的英语书证年代不确定；词根本身是清楚的。"}]},"similar":{"note":{"en":"Group one separates the words built on the insect root; group two separates the true insect from the small creatures commonly called insects.","cn":"第一组区分建在 insect 词根上的词；第二组区分真正的昆虫与常被叫作昆虫的小生物。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"insecticide","ipa":"/ɪnˈsektɪsaɪd/","tag":"the killer","definition":"Insect + -cide 'cutting, killing': a substance that kills insects, not an insect itself.","definitionCN":"insect 加 -cide「杀」：杀死昆虫的物质，而非昆虫。"},{"word":"insectivorous","ipa":"/ˌɪnsekˈtɪvərəs/","tag":"the eater","definition":"Insect + -vorous 'eating': describes a plant or animal that feeds on insects.","definitionCN":"insect 加 -vorous「食」：描述以昆虫为食的动植物。"},{"word":"insectile","ipa":"/ɪnˈsektaɪl/","tag":"the adjective","definition":"A rare adjective meaning of or like insects; it modifies a noun rather than naming an animal.","definitionCN":"罕见的形容词，意为昆虫的或似昆虫的；它修饰名词而非命名动物。"},{"word":"entomology","ipa":"/ˌentəˈmɒlədʒi/","tag":"same idea, Greek line","definition":"The study of insects, built on Greek entomon rather than on Latin insectum; the two are calques of each other.","definitionCN":"昆虫学，建在希腊 entomon 而非拉丁 insectum 上；两者互为仿译。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bug","ipa":"/bʌɡ/","tag":"everyday and technical","definition":"In everyday use any small crawling thing; in entomology only the order Hemiptera, so it is narrower than insect.","definitionCN":"日常指任何小爬虫；昆虫学中仅指半翅目，因此比 insect 更窄。"},{"word":"arachnid","ipa":"/əˈræknɪd/","tag":"eight legs","definition":"Spiders, mites and scorpions: eight legs and two body parts, so never insects despite the everyday habit.","definitionCN":"蜘蛛、螨、蝎：八足、身体两节，因此绝非昆虫，尽管口语常混。"},{"word":"arthropod","ipa":"/ˈɑːθrəpɒd/","tag":"the wider phylum","definition":"The jointed-legged phylum that contains insects, spiders and crustaceans; insect is one class inside it.","definitionCN":"具关节足的整个门，包含昆虫、蜘蛛与甲壳类；昆虫是其中的一个纲。"},{"word":"pest","ipa":"/pest/","tag":"a judgement, not a class","definition":"Pest is any organism that harms human interests; an insect is a pest only when it does damage.","definitionCN":"pest 指任何损害人类利益的生物；昆虫只有在造成损害时才是害虫。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin composition, real compounds and real classification terms.","cn":"正常联想：真实的拉丁构成、真实复合词与真实分类术语。"},"normal":[{"en":"in- 'into' + secare 'cut': the body looks cut into head, thorax and abdomen.","cn":"in-「入」+ secare「切」：身体像是被切成头、胸、腹三段。"},{"en":"Six legs, three body parts and usually two antennae is the working check.","cn":"六足、三节身体、通常两触角，是实用的核验标准。"},{"en":"The family runs insect, insecticide, insectivorous, insectary.","cn":"同族词包括 insect、insecticide、insectivorous、insectary。"},{"en":"Fixed phrases: insect pest, insect bite, social insect.","cn":"固定搭配：害虫、虫咬、社会性昆虫。"},{"en":"Greek entomon and Latin insectum are exact calques, which is why entomology studies insects.","cn":"希腊 entomon 与拉丁 insectum 完全互为仿译，这正是 entomology 研究昆虫的原因。"}],"abstract":[{"en":"Picture a body with two seams cut across it, so the parts can move separately.","cn":"想象一具身体被横切两道，各部分能分别活动。"},{"en":"Picture a crowd of tiny workers each carrying one grain.","cn":"想象一群微小工人，每只搬一粒。"},{"en":"Picture a person so small in a room that no one turns to look.","cn":"想象一个人在房间里小到没人回头看。"}]},"examples":[{"en":"Insects make up more than half of all described animal species.","cn":"已描述的动物物种中，昆虫占一半以上。"},{"en":"The larvae of this insect bore into dead wood.","cn":"这种昆虫的幼虫钻入枯木。"},{"en":"He brushed an insect off his sleeve without looking at it.","cn":"他连看都没看就把一只虫子从袖子上拂开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in（入）+ sect（切）」——身体被切成三段的虫子 → 昆虫","word":"insect"},"root":"拉丁 insectum「被切入者」，为希腊 entomon（en-「在内」+ temnein「切」）的仿译；由 in- 加 secare「切」构成。词源清楚，仅个别义项首见年代不确定。","sensesIntro":{"en":"Eight senses follow one small body: a segmented six-legged creature is first the animal itself, then any crawling thing, then a pest, a disease carrier, an ecological count, a colony member, a laboratory subject, and finally an insult for a person.","cn":"八个义项沿一具小身体展开：分节六足的生物首先是动物本身，然后是任何爬虫、害虫、疾病载体、生态计数、群体成员、实验室对象，最后成为骂人的词。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beetle on a leaf, its body cut into three sections by two seams.","cn":"核心意象：叶上的一只甲虫，身体被两道缝切成三段。"},"chain":["SEGMENTED BODY","ANY SMALL CRAWLER","CROP DAMAGE","DISEASE CARRIER","ECOLOGICAL COUNT","CONTEMPTIBLE PERSON"],"branches":[{"senses":"S1 · S2","en":"CLASS AND LOOSE USE: the technical six-legged class and the everyday 'any bug'.","cn":"纲与宽泛用法：严格六足纲与日常「任何虫」。"},{"senses":"S3 · S4","en":"HARM TO PEOPLE: economic loss and disease transmission are two ways insects enter human affairs.","cn":"对人有害：经济损失与疾病传播是昆虫进入人类事务的两条路。"},{"senses":"S5 · S6","en":"COUNTED AND ORGANISED: a group in a food web, a member of a colony.","cn":"被计数与被组织：食物网中的一类，群体中的一员。"},{"senses":"S7","en":"REARED SUBJECT: the animal becomes a system for study.","cn":"被饲养的对象：动物成为研究体系。"},{"senses":"S8","en":"SMALLNESS ALONE: only size and insignificance survive in the insult.","cn":"只剩渺小：侮辱义里只留下体积与无足轻重。"}]},"affixes":{"intro":{"en":"Insect is a Latin participle used as a noun, so its parts can be read as a small sentence: cut into.","cn":"insect 是作名词用的拉丁分词，其成分可读成一句小句子：被切开。"},"latinIntro":{"en":"Latin secare supplies the root of insect and also of section, sector and segment.","cn":"拉丁 secare 提供 insect 的词根，也是 section、sector、segment 的词根。"},"items":[{"word":"in-","structure":"in- (Latin prefix, 'in, into')","meaning":"into","meaningCN":"入；向内","example":"The prefix marks a cutting inward.","exampleCN":"这个前缀标记向内切入。"},{"word":"secare","structure":"secare (Latin verb, first conjugation)","meaning":"to cut","meaningCN":"切","example":"The root also builds section and segment.","exampleCN":"这个词根也构成 section 与 segment。"},{"word":"insectum","structure":"in- + secare (past participle)","meaning":"cut into, notched","meaningCN":"被切开的；有刻痕的","example":"The Latin name describes a notched body.","exampleCN":"这个拉丁名描述一具带刻痕的身体。"},{"word":"-cide","structure":"insecticide = insect + -cide (killing)","meaning":"a killer of insects","meaningCN":"杀虫之物","example":"The orchard switched to a softer insecticide.","exampleCN":"果园改用了较温和的杀虫剂。"},{"word":"-vorous","structure":"insectivorous = insect + -vorous (eating)","meaning":"feeding on insects","meaningCN":"以昆虫为食","example":"The plant is insectivorous.","exampleCN":"这种植物食虫。"},{"word":"-ile","structure":"insectile = insect + -ile (of or like)","meaning":"of or like an insect","meaningCN":"昆虫的；似昆虫的","example":"The term insectile is rare outside older prose.","exampleCN":"insectile 一词在较古的文字之外少见。"},{"word":"-ary","structure":"insectary = insect + -ary (place)","meaning":"a place for keeping insects","meaningCN":"饲养昆虫的场所","example":"The insectary supplies sterile males.","exampleCN":"昆虫饲养室提供不育雄虫。"},{"word":"section","structure":"secare + -tion (same root)","meaning":"a cutting, a part","meaningCN":"切；部分","example":"Section shares the root but not the prefix.","exampleCN":"section 与该词同根但不同前缀。"},{"word":"-an","structure":"insectan = insect + -an (belonging to)","meaning":"belonging to insects","meaningCN":"属于昆虫的","example":"The insectan body plan has three tagmata.","exampleCN":"昆虫的身体构型有三个体段。"}],"latinEntries":[{"word":"secare","structure":"secare, secui, sectum (verb, first conjugation)","meaning":"to cut","meaningCN":"切"},{"word":"insectum","structure":"insectum, insecti (n., second declension)","meaning":"a creature cut into segments","meaningCN":"分节的生物"},{"word":"sectio","structure":"sectio, sectionis (f., third declension)","meaning":"a cutting, division","meaningCN":"切；分割"}]}},{"word":"entomology","ipa_uk":"/ˌentəˈmɒlədʒi/","ipa_us":"/ˌentəˈmɑːlədʒi/","definition_zh":"昆虫学；研究昆虫的学科；（某领域的）昆虫研究","definition_en":"the branch of zoology that studies insects","core_image":"一张长桌上摆满插着针的标本盒，每个小格里都是同一个身体结构的不同式样，旁边是记录本与放大镜","scene":"博物馆的地下室里，一整面墙的抽屉装着按科排列的标本。 Her work in entomology began with a box of beetles she caught as a child.","sceneCN":"这里 entomology 指「昆虫学」（第 1 个义项：研究昆虫的动物学分支）；句意为她的昆虫学研究始于童年时抓到的一盒甲虫。","pos":[{"tag":"n.","zh":"昆虫学；（特定范围的）昆虫研究"}],"collocations":[{"phrase":"forensic entomology","zh":"法医昆虫学"},{"phrase":"medical entomology","zh":"医学昆虫学"},{"phrase":"applied entomology","zh":"应用昆虫学"},{"phrase":"economic entomology","zh":"经济昆虫学"},{"phrase":"degree in entomology","zh":"昆虫学学位"},{"phrase":"field entomology","zh":"野外昆虫学"}],"forms":[{"label":"原形","form":"entomology"},{"label":"从业者","form":"entomologist"},{"label":"形容词","form":"entomological"},{"label":"副词","form":"entomologically"},{"label":"研究对象的单数","form":"insect"}],"derivatives":[{"word":"entomologist","pos":"n.","zh":"昆虫学家"},{"word":"entomological","pos":"adj.","zh":"昆虫学的"},{"word":"entomologically","pos":"adv.","zh":"从昆虫学角度"},{"word":"entomofauna","pos":"n.","zh":"某地区的昆虫区系"},{"word":"entomophilous","pos":"adj.","zh":"虫媒的（靠昆虫传粉）"}],"senses":[{"no":"01","title":"The science of insects","titleCN":"研究昆虫的科学","definition":"the branch of zoology concerned with the structure, classification, behaviour and ecology of insects","definitionCN":"动物学中研究昆虫结构、分类、行为与生态的分支","example":"Her work in entomology began with a box of beetles.","exampleCN":"她的昆虫学研究始于一盒甲虫。","why":"Greek entomon 'insect' plus -logia 'study' states exactly what the discipline studies, with no metaphor involved.","whyCN":"希腊 entomon「昆虫」加 -logia「学问」，直接说明这门学科研究什么，不含比喻。"},{"no":"02","title":"An academic department or degree subject","titleCN":"大学的系所或学位科目","definition":"the institutional form of the subject, as a department, course or degree","definitionCN":"该学科的制度形态，如系、课程或学位","example":"The university opened a department of entomology in 1911.","exampleCN":"这所大学于 1911 年设立了昆虫学系。","why":"a discipline's name also names the unit that teaches it, since the unit is defined by the subject.","whyCN":"学科名也命名教授它的单位，因为单位是由学科定义的。"},{"no":"03","title":"The published body of insect research","titleCN":"已发表的昆虫研究总体","definition":"the accumulated literature and knowledge about insects","definitionCN":"关于昆虫的累积文献与知识","example":"The taxonomy of that family is buried in old entomology.","exampleCN":"那一科的分类埋在陈旧的昆虫学文献里。","why":"when a field is cited as a body of writing, the name of the field stands for its literature.","whyCN":"当一门学科被当作一批文字来称引时，学科名就代指其文献。"},{"no":"04","title":"Forensic use of insect evidence","titleCN":"法医利用昆虫证据","definition":"the applied branch that reads insects on a body to estimate time since death","definitionCN":"通过尸体上的昆虫推断死亡时间的应用分支","example":"Forensic entomology placed the interval at four days.","exampleCN":"法医昆虫学把时间间隔定在四天。","why":"the qualifier forensic marks a use, and the base word still means the study of insects.","whyCN":"限定语 forensic 标记用途，词基仍指对昆虫的研究。"},{"no":"05","title":"Medical and veterinary entomology","titleCN":"医学与兽医昆虫学","definition":"the branch studying insects that bite, parasitise or transmit disease to humans and livestock","definitionCN":"研究叮咬、寄生或向人畜传播疾病的昆虫的分支","example":"Medical entomology drove the campaign against malaria.","exampleCN":"医学昆虫学推动了抗击疟疾的运动。","why":"the same science, narrowed by the practical problem it serves.","whyCN":"同一门科学，被它所服务的实际问题收窄。"},{"no":"06","title":"Economic and agricultural entomology","titleCN":"经济与农业昆虫学","definition":"the branch concerned with insects as pests, pollinators or biological controls in farming","definitionCN":"关注昆虫在农业中作为害虫、传粉者或生物防治手段的分支","example":"Economic entomology counts the cost of every sprayed field.","exampleCN":"经济昆虫学计算每块喷药田的成本。","why":"applied branches are named by the sector they answer to, not by a different science.","whyCN":"应用分支以其所服务的部门命名，而不是另一门科学。"},{"no":"07","title":"Amateur study and collecting","titleCN":"业余研究与采集","definition":"the pursuit of naming and collecting insects outside professional employment","definitionCN":"在职业之外命名与采集昆虫的爱好活动","example":"Local entomology thrives in the county recording scheme.","exampleCN":"本地的业余昆虫研究靠郡记录计划兴旺起来。","why":"the word is not restricted to professionals, so it also covers careful amateur work.","whyCN":"这个词不限于专业者，因此也涵盖严谨的业余工作。"},{"no":"08","title":"Figurative: obsessive attention to tiny detail","titleCN":"比喻：对细枝末节的执迷","definition":"figurative and mildly ironic, an excessive concern with trivial particulars","definitionCN":"比喻且略带讽刺，指对琐屑细节的过度关注","example":"Reviewing the footnotes felt like entomology rather than editing.","exampleCN":"审读脚注更像在做昆虫学，而不是在编辑。","why":"the metaphor uses the discipline's focus on very small things to mock a person who studies details too closely.","whyCN":"比喻借用这门学科对微小之物的专注，嘲弄过度钻研细节的人。"}],"etymology":{"intro":{"en":"Entomology joins Greek entomon 'insect' with -logia 'study'; entomon itself means 'cut into', the same image Latin insectum translated.","cn":"entomology 把希腊 entomon「昆虫」与 -logia「学问」结合；entomon 本身意为「被切开」，与拉丁 insectum 所译的是同一意象。"},"items":[{"era":"GREEK ENTOMON","en":"Entomon, from en- 'in' and temnein 'to cut', described a creature whose body is divided into sections.","cn":"entomon 由 en-「在内」与 temnein「切」构成，描述身体分成段落的生物。"},{"era":"GREEK -LOGIA","en":"The suffix -logia meant the study or account of something, from logos 'word, reason'.","cn":"后缀 -logia 意为对某物的研究或论述，出自 logos「言、理」。"},{"era":"SEVENTEENTH-CENTURY COINAGE","en":"Entomology entered English in the seventeenth century as the learned name for insect study, parallel to Latin-based insect.","cn":"entomology 于 17 世纪进入英语，作为昆虫研究的学术名称，与拉丁式的 insect 并行。"},{"era":"DISCIPLINE FORMATION","en":"In the nineteenth century the word settled as a university subject with its own journals, collections and methods.","cn":"19 世纪这个词定型为一门大学科目，有其期刊、收藏与方法。"},{"era":"APPLIED BRANCHES","en":"Forensic, medical and economic qualifiers appeared as the science was turned to practical problems.","cn":"随着这门科学转向实际问题，forensic、medical、economic 等限定语相继出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact earliest English use of entomology is not firmly dated, and Greek temnein has no fully settled Indo-European root.","cn":"来源不确定（首见年代）：entomology 最早英语书证的确切年代不详，希腊 temnein 的印欧词根亦无完全定论。"}]},"similar":{"note":{"en":"Group one separates the entomology word family; group two separates it from neighbouring biological disciplines.","cn":"第一组区分 entomology 词族；第二组区分它与邻近的生物学学科。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"entomologist","ipa":"/ˌentəˈmɒlədʒɪst/","tag":"the person","definition":"The -ist suffix marks the person who practises entomology; the discipline and its practitioner are not interchangeable.","definitionCN":"-ist 后缀标记从事昆虫学的人；学科与其从业者不可互换。"},{"word":"entomological","ipa":"/ˌentəməˈlɒdʒɪkl/","tag":"the adjective","definition":"The adjective describes what belongs to entomology, as in an entomological collection.","definitionCN":"形容词描述属于昆虫学的事物，如昆虫学收藏。"},{"word":"etymology","ipa":"/ˌetɪˈmɒlədʒi/","tag":"near look, other field","definition":"Etymology studies word origins from Greek etymon 'true sense'; one letter apart from entomology and often confused.","definitionCN":"etymology 由希腊 etymon「真义」研究词源；与 entomology 只差一字母，常被混淆。"},{"word":"insect","ipa":"/ˈɪnsekt/","tag":"the object, Latin line","definition":"The animal studied; entomology is the Latin calque's Greek counterpart, so the pair looks unrelated but means the same thing.","definitionCN":"被研究的动物；entomology 是拉丁仿译的希腊对应词，因此二者看似无关而同义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"zoology","ipa":"/zəʊˈɒlədʒi/","tag":"the parent field","definition":"The study of animals as a whole; entomology is one branch of it, limited to insects.","definitionCN":"研究整个动物界；昆虫学是其中一个分支，只限昆虫。"},{"word":"arachnology","ipa":"/ˌærəkˈnɒlədʒi/","tag":"spiders, not insects","definition":"The study of spiders and related eight-legged animals; it is a separate discipline from entomology.","definitionCN":"研究蜘蛛及相关八足动物；与昆虫学是不同学科。"},{"word":"ecology","ipa":"/ɪˈkɒlədʒi/","tag":"relations, not a group","definition":"Ecology studies relations between organisms and their surroundings; entomology studies a taxonomic group.","definitionCN":"ecology 研究生物与环境的关系；entomology 研究一个分类群。"},{"word":"apiology","ipa":"/ˌeɪpiˈɒlədʒi/","tag":"bees only","definition":"The specialised study of bees; a narrow slice of entomology with its own name.","definitionCN":"专门研究蜜蜂的学问；昆虫学的一个窄切片，另有其名。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek morphemes, real institutional phrases and real sister disciplines.","cn":"正常联想：真实的希腊语素、真实机构用语与真实姊妹学科。"},"normal":[{"en":"entomon 'insect' + -logia 'study': the study of the cut-into animals.","cn":"entomon「昆虫」+ -logia「学问」：研究「被切开」的动物。"},{"en":"The family runs entomology, entomologist, entomological, entomofauna.","cn":"同族词包括 entomology、entomologist、entomological、entomofauna。"},{"en":"Fixed phrases: forensic entomology, medical entomology, applied entomology.","cn":"固定搭配：法医昆虫学、医学昆虫学、应用昆虫学。"},{"en":"Do not confuse entomology with etymology: one studies insects, the other studies word origins.","cn":"勿把 entomology 与 etymology 混：前者研究昆虫，后者研究词源。"},{"en":"The Greek and Latin names for insect are calques, so entomology and insect describe the same animal.","cn":"昆虫的希腊名与拉丁名互为仿译，因此 entomology 与 insect 描述同一种动物。"}],"abstract":[{"en":"Picture a library where every drawer holds one kind of small body.","cn":"想象一座图书馆，每个抽屉装一种小身体。"},{"en":"Picture a magnifying glass that turns a speck into a landscape.","cn":"想象一只放大镜，把一粒斑点变成一片风景。"},{"en":"Picture a scholar who reads a whole page to judge one comma.","cn":"想象一位学者读完整页只为判断一个逗号。"}]},"examples":[{"en":"Entomology has described about a million species and estimates many more remain.","cn":"昆虫学已描述约一百万种，并估计还有更多未被记录。"},{"en":"The museum's entomology collection fills forty cabinets.","cn":"博物馆的昆虫学收藏装满了四十个柜子。"},{"en":"She turned to entomology after finding a nest of wasps in the garden.","cn":"她在花园里发现一窝黄蜂后转向昆虫学。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「entom（昆虫）+ ology（学科）」——研究被切成三段的虫子 → 昆虫学","word":"entomology"},"root":"希腊 entomon「昆虫」= en-（在内）+ temnein「切」，指身体分成段落的生物；加 -logia「学问」构成 entomology。temnein 的印欧词根无完全定论，首见年代不确定。","sensesIntro":{"en":"Eight senses follow one discipline: the study of insects is first a science, then a department, then a literature, then three applied branches, then amateur collecting, and finally a joke about someone who studies details too closely.","cn":"八个义项沿一门学科展开：昆虫研究首先是一门科学，然后是系所、文献、三个应用分支、业余采集，最后成为讥讽过度钻研细节者的笑话。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall of drawers, each holding one kind of small segmented body.","cn":"核心意象：一整墙抽屉，每格装一种分节的小身体。"},"chain":["STUDY THE INSECT","NAME THE DISCIPLINE","TEACH AND PUBLISH","SERVE COURT AND CLINIC","SERVE THE FARM","MOCK THE PEDANT"],"branches":[{"senses":"S1 · S2","en":"SCIENCE AND INSTITUTION: the subject and the unit that teaches it.","cn":"科学与机构：学科与教授它的单位。"},{"senses":"S3","en":"WRITTEN BODY: the field cited as its accumulated papers.","cn":"文字总体：学科被称引为其累积的论文。"},{"senses":"S4 · S5 · S6","en":"APPLIED FACES: court, clinic and farm each narrow the same science.","cn":"应用面貌：法庭、诊所与农场各自收窄同一门科学。"},{"senses":"S7","en":"AMATEUR HOURS: careful collecting outside a salary.","cn":"业余时间：薪水之外的严谨采集。"},{"senses":"S8","en":"DETAIL OBSESSION: the smallness of the object becomes a joke about the observer.","cn":"细节执迷：对象之小变成关于观察者的笑话。"}]},"affixes":{"intro":{"en":"Entomology is two Greek elements joined by a linking -o-, and the same suffix builds dozens of discipline names.","cn":"entomology 是两个希腊成分由连接元音 -o- 相连，同一后缀还构成数十个学科名。"},"latinIntro":{"en":"The word is Greek, not Latin; Latin insectum is its calque, so the Latin entries below are the parallel forms rather than the source.","cn":"这个词是希腊语而非拉丁语；拉丁 insectum 是它的仿译，因此下列拉丁条目是平行形式而非来源。"},"items":[{"word":"en-","structure":"en- (Greek prefix, 'in')","meaning":"in","meaningCN":"在内","example":"The prefix marks a cut made inward.","exampleCN":"这个前缀标记向内做的切。"},{"word":"temnein","structure":"temnein (Greek verb, 'to cut')","meaning":"to cut","meaningCN":"切","example":"The root supplies the image of a notched body.","exampleCN":"这个词根提供「带刻痕的身体」这一意象。"},{"word":"entomon","structure":"en- + temnein (Greek noun)","meaning":"an insect, a cut-into creature","meaningCN":"昆虫；被切开的生物","example":"Greek entomon names the animal directly.","exampleCN":"希腊 entomon 直接命名这种动物。"},{"word":"-logia","structure":"-logia (Greek suffix, 'study of')","meaning":"the study or account of","meaningCN":"对……的研究或论述","example":"The suffix builds biology and zoology too.","exampleCN":"这个后缀也构成 biology 与 zoology。"},{"word":"-ist","structure":"entomologist = entomology + -ist","meaning":"one who practises","meaningCN":"从事者","example":"The entomologist pinned the specimen.","exampleCN":"昆虫学家把标本插针固定。"},{"word":"-ical","structure":"entomological = entomology + -ical","meaning":"relating to","meaningCN":"与……有关的","example":"The entomological journal appears quarterly.","exampleCN":"这份昆虫学期刊按季出版。"},{"word":"-fauna","structure":"entomofauna = entomo- + -fauna","meaning":"the insect fauna of a region","meaningCN":"某地区的昆虫区系","example":"The entomofauna of the island is poorly known.","exampleCN":"该岛的昆虫区系所知甚少。"},{"word":"-philous","structure":"entomophilous = entomo- + -philous","meaning":"pollinated by insects","meaningCN":"由昆虫传粉的","example":"Most orchard trees are entomophilous.","exampleCN":"多数果树由昆虫传粉。"},{"word":"-logy","structure":"-logy (English form of -logia)","meaning":"a named field of study","meaningCN":"一门有名称的学科","example":"Entomology follows the same pattern as zoology.","exampleCN":"entomology 与 zoology 构词方式相同。"}],"latinEntries":[{"word":"insectum","structure":"insectum, insecti (n., second declension)","meaning":"a segmented creature, insect","meaningCN":"分节的生物；昆虫"},{"word":"secare","structure":"secare, secui, sectum (verb, first conjugation)","meaning":"to cut","meaningCN":"切"},{"word":"animal","structure":"animal, animalis (n., third declension)","meaning":"a living creature","meaningCN":"生物；动物"}]}},{"word":"entomologist","ipa_uk":"/ˌentəˈmɒlədʒɪst/","ipa_us":"/ˌentəˈmɑːlədʒɪst/","definition_zh":"昆虫学家；研究昆虫的专家","definition_en":"a scientist who studies insects","core_image":"一个人蹲在草丛边，手里拿着小瓶与镊子，眼睛贴着一片叶子背面看不动的小点","scene":"天还没亮，研究者已经蹲在湿地边，把夜里落进诱捕瓶的虫子一只只分装。 The entomologist sorted the catch by family before the heat made the specimens brittle.","sceneCN":"这里 entomologist 指「昆虫学家」（第 1 个义项：以科学研究方式研究昆虫的人）；句意为昆虫学家趁高温使标本变脆之前，把捕获物按科分拣。","pos":[{"tag":"n.","zh":"昆虫学家；（某一类群的）昆虫研究专家"}],"collocations":[{"phrase":"field entomologist","zh":"野外昆虫学家"},{"phrase":"forensic entomologist","zh":"法医昆虫学家"},{"phrase":"medical entomologist","zh":"医学昆虫学家"},{"phrase":"amateur entomologist","zh":"业余昆虫学家"},{"phrase":"consulting entomologist","zh":"咨询昆虫学家"},{"phrase":"resident entomologist","zh":"常驻昆虫学家"}],"forms":[{"label":"原形","form":"entomologist"},{"label":"复数","form":"entomologists"},{"label":"学科","form":"entomology"},{"label":"形容词","form":"entomological"},{"label":"阴性形式（少见）","form":"entomologiste"}],"derivatives":[{"word":"entomology","pos":"n.","zh":"昆虫学"},{"word":"entomological","pos":"adj.","zh":"昆虫学的"},{"word":"entomologically","pos":"adv.","zh":"从昆虫学角度"},{"word":"entomofauna","pos":"n.","zh":"昆虫区系"},{"word":"entomophilous","pos":"adj.","zh":"虫媒的"}],"senses":[{"no":"01","title":"A scientist who studies insects","titleCN":"以科学方式研究昆虫的人","definition":"a person trained to study the biology, classification and ecology of insects","definitionCN":"受过训练、研究昆虫生物学、分类与生态的人","example":"The entomologist sorted the catch by family.","exampleCN":"昆虫学家把捕获物按科分拣。","why":"entomology plus -ist marks the practitioner, so the word names a person by the discipline practised.","whyCN":"entomology 加 -ist 标记从事者，因此这个词以所从事的学科来命名一个人。"},{"no":"02","title":"A specialist in one insect group","titleCN":"专攻某一类群的专家","definition":"a researcher who works on a single order, family or genus rather than on insects generally","definitionCN":"只研究某一个目、科或属、而非泛研究昆虫的研究者","example":"She is the entomologist for the beetle collection.","exampleCN":"她是甲虫收藏方面的昆虫学家。","why":"specialisation is expressed by the object added, while the title itself stays general.","whyCN":"专化由所加的对象表达，而头衔本身保持通用。"},{"no":"03","title":"A field surveyor of insect populations","titleCN":"野外昆虫种群的调查者","definition":"a person who counts and samples insects in the field for monitoring or conservation","definitionCN":"为监测或保育而在野外计数与取样昆虫的人","example":"The entomologist walked the same transect every week for a year.","exampleCN":"这位昆虫学家一年里每周走同一条样带。","why":"the discipline's main evidence comes from field samples, so the practitioner is often met as a surveyor.","whyCN":"这门学科的主要证据来自野外取样，因此实践者常以调查者形象出现。"},{"no":"04","title":"A forensic expert reading insect evidence","titleCN":"解读昆虫证据的法医专家","definition":"a specialist who uses insects on a body or at a scene to estimate time and circumstances","definitionCN":"利用尸体或现场上的昆虫推断时间与情形的专家","example":"The entomologist was called before the body was moved.","exampleCN":"尸体被移动之前，昆虫学家就被叫到了现场。","why":"the same training is applied to legal questions, and the title follows the person rather than the setting.","whyCN":"同样的训练被用于法律问题，头衔随人走而不随场合变。"},{"no":"05","title":"A museum curator of insect collections","titleCN":"管理昆虫收藏的馆员","definition":"a person responsible for naming, preserving and organising a reference collection","definitionCN":"负责命名、保存与整理参考收藏的人","example":"The entomologist found the type specimen mislabelled.","exampleCN":"这位昆虫学家发现模式标本标签贴错了。","why":"collections are the discipline's archive, so curation is part of the professional role.","whyCN":"收藏是该学科的档案，因此管理收藏是职业角色的一部分。"},{"no":"06","title":"A medical or veterinary specialist","titleCN":"医学或兽医方向的专家","definition":"a specialist in insects that bite, parasitise or transmit disease","definitionCN":"研究叮咬、寄生或传播疾病的昆虫的专家","example":"A medical entomologist traced the outbreak to standing water.","exampleCN":"一位医学昆虫学家把疫情追溯到积水。","why":"public health employs the same title with a qualifier, because the object of study is still insects.","whyCN":"公共卫生以限定语使用同一头衔，因为研究对象仍是昆虫。"},{"no":"07","title":"A knowledgeable amateur","titleCN":"博学的业余研究者","definition":"a non-professional who has acquired reliable expert knowledge of a local insect fauna","definitionCN":"在本地昆虫区系上获得可靠专门知识的非职业者","example":"The county's best entomologist is a retired postal clerk.","exampleCN":"这个郡最好的昆虫学家是一位退休邮局职员。","why":"the title tracks knowledge rather than employment, so long observation can earn it.","whyCN":"这个头衔跟知识走而不跟职位走，因此长期观察也能赢来。"},{"no":"08","title":"Informal: the person who knows the bugs","titleCN":"口语：懂虫子的人","definition":"loosely, anyone consulted about an insect problem, such as a pest-control specialist","definitionCN":"泛指任何就昆虫问题被咨询的人，如害虫防治专家","example":"They called the entomologist before spraying the warehouse.","exampleCN":"他们在给仓库喷药之前先叫来了昆虫专家。","why":"in everyday use the word marks expertise about insects rather than a research career.","whyCN":"在日常用法里，这个词标记的是关于昆虫的专长，而非研究生涯。"}],"etymology":{"intro":{"en":"Entomologist is entomology plus the agent suffix -ist, so it simply means the person who practises the study of insects.","cn":"entomologist 是 entomology 加施事后缀 -ist，意思就是从事昆虫研究的人。"},"items":[{"era":"GREEK ENTOMON","en":"Entomon 'insect' comes from en- 'in' plus temnein 'to cut', naming a body divided into sections.","cn":"entomon「昆虫」由 en-「在内」加 temnein「切」构成，命名身体分成段落的生物。"},{"era":"-LOGIA TO -LOGY","en":"Greek -logia passed into English as -logy, and from the seventeenth century it named learned fields of study.","cn":"希腊 -logia 进入英语作 -logy，自 17 世纪起用于命名各门学术领域。"},{"era":"-IST","en":"The suffix -ist, from Greek -istes, marks a person engaged in an activity, as in botanist and geologist.","cn":"后缀 -ist 出自希腊 -istes，标记从事某种活动的人，如 botanist、geologist。"},{"era":"PROFESSIONAL FORMATION","en":"Entomologist became a recognised occupational title in the nineteenth century as museums and universities hired specialists.","cn":"19 世纪博物馆与大学开始聘用专家，entomologist 成为被承认的职业头衔。"},{"era":"APPLIED TITLES","en":"Forensic, medical and consulting qualifiers appeared as the expertise was applied outside academia.","cn":"随着这一专长在学术界之外应用，forensic、medical、consulting 等限定语出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English record of entomologist is not firmly dated, and Greek temnein lacks a fully settled Indo-European root.","cn":"来源不确定（首见年代）：entomologist 最早英语书证年代不确定，希腊 temnein 的印欧词根亦无完全定论。"}]},"similar":{"note":{"en":"Group one separates the entomologist from the other words of the same family; group two separates the specialist from neighbouring experts.","cn":"第一组区分 entomologist 与同族其它词；第二组区分这位专家与邻近领域的专家。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"entomology","ipa":"/ˌentəˈmɒlədʒi/","tag":"the discipline","definition":"The field itself; the -ist person practices it, so the two cannot replace each other in a sentence.","definitionCN":"学科本身；-ist 者从事它，二者在句中不能互换。"},{"word":"entomological","ipa":"/ˌentəməˈlɒdʒɪkl/","tag":"the adjective","definition":"Describes what relates to the field, as in entomological survey; it never names a person.","definitionCN":"描述与该领域相关的事物，如昆虫学调查；它从不命名人。"},{"word":"etymologist","ipa":"/ˌetɪˈmɒlədʒɪst/","tag":"one letter away","definition":"An etymologist studies word origins; the similarity to entomologist is a classic source of confusion.","definitionCN":"etymologist 研究词源；与 entomologist 的相似是经典的混淆来源。"},{"word":"insect","ipa":"/ˈɪnsekt/","tag":"the object studied","definition":"The animal, from the Latin calque; the person who studies it carries the Greek-based title.","definitionCN":"动物本身，出自拉丁仿译；研究它的人则用希腊式头衔。"}]},{"heading":"NEAR MEANING","entries":[{"word":"zoologist","ipa":"/zuˈɒlədʒɪst/","tag":"wider field","definition":"A zoologist studies animals in general; an entomologist is a zoologist specialised in one class.","definitionCN":"zoologist 研究整个动物界；entomologist 是专攻一个纲的动物学家。"},{"word":"arachnologist","ipa":"/ˌærəkˈnɒlədʒɪst/","tag":"eight legs","definition":"Studies spiders and their relatives, which are not insects; the title is a separate specialism.","definitionCN":"研究蜘蛛及其近亲，它们不是昆虫；这是另一个专门领域。"},{"word":"ecologist","ipa":"/ɪˈkɒlədʒɪst/","tag":"relations, not group","definition":"An ecologist studies relations between organisms and habitat, and may work with insects without being an entomologist.","definitionCN":"生态学家研究生物与生境的关系，可能研究昆虫但不是昆虫学家。"},{"word":"exterminator","ipa":"/ɪkˈstɜːmɪneɪtə/","tag":"the trade","definition":"A pest-control worker removes infestations; the title marks a service trade, not a research qualification.","definitionCN":"害虫防治人员清除虫害；这个头衔标记服务行业，而非研究资历。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real agent suffix, real professional titles and a real confusable pair.","cn":"正常联想：真实施事后缀、真实职业头衔与一对真实易混词。"},"normal":[{"en":"entomology + -ist: the person who does the study.","cn":"entomology + -ist：从事这门研究的人。"},{"en":"The family runs entomology, entomologist, entomological, entomofauna.","cn":"同族词包括 entomology、entomologist、entomological、entomofauna。"},{"en":"Fixed phrases: field entomologist, forensic entomologist, medical entomologist.","cn":"固定搭配：野外昆虫学家、法医昆虫学家、医学昆虫学家。"},{"en":"The -ist suffix also builds botanist, zoologist and geologist.","cn":"-ist 后缀还构成 botanist、zoologist、geologist。"},{"en":"Entomologist and etymologist differ by one letter and by an entire field.","cn":"entomologist 与 etymologist 差一个字母，也差一整门学科。"}],"abstract":[{"en":"Picture a person who can name every small thing in a meadow.","cn":"想象一个人能叫出草地上每一样小东西的名字。"},{"en":"Picture a notebook filled with dates and weather, one line per sighting.","cn":"想象一本记满日期与天气的本子，每次目击一行。"},{"en":"Picture a courtroom where the expert evidence is a fly on a leaf.","cn":"想象一个法庭，专家证据是叶上的一只蝇。"}]},"examples":[{"en":"An entomologist can identify the species from a single wing.","cn":"昆虫学家能凭一片翅识别物种。"},{"en":"The park employs an entomologist to monitor pollinators.","cn":"公园聘用一位昆虫学家监测传粉者。"},{"en":"He became an entomologist after raising moths as a boy.","cn":"他小时候养蛾，后来成了昆虫学家。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「entomo（昆虫）+ logist（研究者）」——研究虫子的人 → 昆虫学家","word":"entomologist"},"root":"entomology（希腊 entomon「昆虫」+ -logia「学问」）+ -ist（从事者）；entomon = en-（在内）+ temnein（切）。首见年代与 temnein 词根存疑。","sensesIntro":{"en":"Eight senses follow one expert: a person studies insects as a science, then narrows to a group, walks a field transect, reads evidence for a court, curates a collection, serves public health, earns the title as an amateur, and finally is anyone consulted about a bug.","cn":"八个义项沿一位专家展开：此人以科学方式研究昆虫，随后收窄到某一类群、走野外样带、为法庭解读证据、管理收藏、服务公共卫生、以业余身份赢得头衔，最后成为任何被问及虫子的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person crouched by a leaf, naming a speck nobody else can see.","cn":"核心意象：有人蹲在叶旁，叫出别人看不见的那一粒小点的名字。"},"chain":["STUDY INSECTS","MASTER ONE GROUP","SAMPLE THE FIELD","SERVE COURT AND CLINIC","KEEP THE COLLECTION","KNOW WITHOUT A DEGREE"],"branches":[{"senses":"S1 · S2","en":"TRAINED EYE: general science first, then a narrow specialism.","cn":"受训的眼：先是通用科学，再是狭窄专攻。"},{"senses":"S3","en":"FIELD PRESENCE: the same eye counting along a transect.","cn":"野外在场：同一双眼沿样带计数。"},{"senses":"S4 · S6","en":"SERVICE ROLES: court and clinic borrow the expertise.","cn":"服务角色：法庭与诊所借用这份专长。"},{"senses":"S5","en":"ARCHIVE KEEPER: collections are the discipline's memory.","cn":"档案守护：收藏是学科的记性。"},{"senses":"S7 · S8","en":"TITLE BY KNOWLEDGE: a patient observer or a consulted trader may carry the name.","cn":"凭知识得名：耐心的观察者或被咨询的从业者也可带此名。"}]},"affixes":{"intro":{"en":"Entomologist is a Greek-derived compound plus a Greek agent suffix, so each element marks either the object or the person.","cn":"entomologist 是希腊来源的复合词加希腊施事后缀，每一成分标记对象或人。"},"latinIntro":{"en":"The word is Greek throughout; Latin insectum is the calque of entomon and appears in the parallel English word insect.","cn":"这个词全程为希腊语；拉丁 insectum 是 entomon 的仿译，见于平行的英语词 insect。"},"items":[{"word":"en-","structure":"en- (Greek prefix, 'in')","meaning":"in","meaningCN":"在内","example":"The prefix marks a body cut inward.","exampleCN":"这个前缀标记向内切开的身体。"},{"word":"temnein","structure":"temnein (Greek verb, 'to cut')","meaning":"to cut","meaningCN":"切","example":"The root supplies the image of segmentation.","exampleCN":"这个词根提供分节的意象。"},{"word":"entomon","structure":"en- + temnein (Greek noun)","meaning":"insect","meaningCN":"昆虫","example":"Entomon is the object of the study.","exampleCN":"entomon 是研究的对象。"},{"word":"-logia","structure":"-logia (Greek suffix, 'study')","meaning":"study of","meaningCN":"对……的研究","example":"The suffix names the field.","exampleCN":"这个后缀命名这门领域。"},{"word":"-logy","structure":"-logy (English form)","meaning":"a discipline","meaningCN":"一门学科","example":"Entomology is the discipline name.","exampleCN":"entomology 是学科名。"},{"word":"-ist","structure":"entomologist = entomology + -ist","meaning":"one who practises","meaningCN":"从事者","example":"The entomologist pinned the type.","exampleCN":"昆虫学家把模式标本插针固定。"},{"word":"-ical","structure":"entomological = entomology + -ical","meaning":"relating to the field","meaningCN":"与这门领域有关的","example":"The entomological record is incomplete.","exampleCN":"昆虫学记录并不完整。"},{"word":"-fauna","structure":"entomofauna = entomo- + -fauna","meaning":"insect fauna of a region","meaningCN":"某地区昆虫区系","example":"The entomofauna of the delta was surveyed twice.","exampleCN":"三角洲的昆虫区系被调查过两次。"},{"word":"-philous","structure":"entomophilous = entomo- + -philous","meaning":"insect-pollinated","meaningCN":"虫媒的","example":"Entomophilous flowers usually have colour and scent.","exampleCN":"虫媒花通常有色有香。"}],"latinEntries":[{"word":"insectum","structure":"insectum, insecti (n., second declension)","meaning":"insect","meaningCN":"昆虫"},{"word":"naturalis","structure":"naturalis, naturalis (adj., third declension)","meaning":"of nature, natural","meaningCN":"自然的；关于自然的"},{"word":"investigator","structure":"investigator, investigatoris (m., third declension)","meaning":"one who searches out","meaningCN":"探究者"}]}},{"word":"insecticide","ipa_uk":"/ɪnˈsektɪsaɪd/","ipa_us":"/ɪnˈsektɪsaɪd/","definition_zh":"杀虫剂；杀昆虫剂；（比喻）摧毁某类人群的手段","definition_en":"a substance used to kill insects","core_image":"一只喷雾器在叶背喷出极细的白雾，雾里的细滴落在虫体上，虫子几分钟内松开了抓握的脚","scene":"农场在播种前把药液兑进水箱，沿着田垄均匀喷洒。 The insecticide is applied at dusk, when the bees have stopped flying.","sceneCN":"这里 insecticide 指「杀虫剂」（第 1 个义项：用于杀死昆虫的化学制剂）；句意为杀虫剂在黄昏施用，那时蜜蜂已经停止飞行。","pos":[{"tag":"n.","zh":"杀虫剂；杀昆虫剂"}],"collocations":[{"phrase":"spray insecticide","zh":"喷洒杀虫剂"},{"phrase":"broad-spectrum insecticide","zh":"广谱杀虫剂"},{"phrase":"insecticide resistance","zh":"杀虫剂抗性"},{"phrase":"insecticide residue","zh":"杀虫剂残留"},{"phrase":"insecticide use","zh":"杀虫剂使用"},{"phrase":"systemic insecticide","zh":"内吸性杀虫剂"},{"phrase":"insecticide-treated net","zh":"浸药蚊帐"}],"forms":[{"label":"原形","form":"insecticide"},{"label":"复数","form":"insecticides"},{"label":"形容词","form":"insecticidal"},{"label":"同根名词（昆虫）","form":"insect"},{"label":"相关名词（杀真菌剂）","form":"fungicide"}],"derivatives":[{"word":"insecticidal","pos":"adj.","zh":"杀虫的"},{"word":"insect","pos":"n.","zh":"昆虫"},{"word":"pesticide","pos":"n.","zh":"农药；除害剂"},{"word":"herbicide","pos":"n.","zh":"除草剂"},{"word":"fungicide","pos":"n.","zh":"杀真菌剂"}],"senses":[{"no":"01","title":"A substance that kills insects","titleCN":"能杀死昆虫的物质","definition":"a chemical or biological agent used to kill insects","definitionCN":"用于杀死昆虫的化学或生物制剂","example":"The insecticide is applied at dusk.","exampleCN":"杀虫剂在黄昏施用。","why":"insect plus Latin -cide 'killing' states the function directly, so the word needs no explanation beyond its parts.","whyCN":"insect 加拉丁 -cide「杀」直接表明功能，因此这个词除字面成分外无需解释。"},{"no":"02","title":"A product class in farming","titleCN":"农业中的一个产品类别","definition":"one product category among the crop-protection chemicals sold to growers","definitionCN":"出售给种植者的作物保护化学品中的一个产品类别","example":"Insecticide accounts for a shrinking share of the budget.","exampleCN":"杀虫剂在预算中所占比重正在缩小。","why":"a category name is used uncountably to mean the whole product line, not one bottle.","whyCN":"类别名以不可数形式指整条产品线，而非某一瓶。"},{"no":"03","title":"A broad-spectrum agent","titleCN":"广谱杀虫剂","definition":"a preparation that kills many insect species rather than one target","definitionCN":"杀死许多昆虫物种而非单一目标对象的制剂","example":"Broad-spectrum insecticides also remove the predators.","exampleCN":"广谱杀虫剂连捕食者一并清除。","why":"the qualifier describes the range of the same agent, since the killing function does not change.","whyCN":"限定语描述同一制剂的作用范围，杀灭功能并未改变。"},{"no":"04","title":"A selective or systemic agent","titleCN":"选择性或内吸性药剂","definition":"an agent that acts on one group, or one taken up by the plant and carried through its tissue","definitionCN":"只对某类昆虫起作用、或被植物吸收并在组织中输送的药剂","example":"A systemic insecticide protects new growth from inside.","exampleCN":"内吸性杀虫剂从内部保护新生的枝叶。","why":"the technical qualifiers describe how the agent moves, not a different kind of substance.","whyCN":"技术限定语描述药剂如何移动，而非另一类物质。"},{"no":"05","title":"Residue left on food or in water","titleCN":"食物或水中的残留","definition":"the trace of the chemical that remains on produce, soil or water after use","definitionCN":"使用后留在农产品、土壤或水中的化学痕迹","example":"Tests found insecticide residue on the imported fruit.","exampleCN":"检测在进口水果上发现杀虫剂残留。","why":"the mass noun is used for the measurable remainder, because the material is the same as the product.","whyCN":"物质名词用于可测量的余留量，因为其材料与产品相同。"},{"no":"06","title":"The problem of resistance","titleCN":"抗性问题","definition":"the condition in which target insects survive treatment and pass on tolerance","definitionCN":"目标昆虫在施药后存活并把耐受性传下去的情形","example":"Insecticide resistance appeared within a decade.","exampleCN":"抗药性在十年之内就出现了。","why":"the word stands for the pressure the chemical applies, so the insects' answer is named against it.","whyCN":"这个词代表药剂施加的压力，因此昆虫的应对是依它命名的。"},{"no":"07","title":"Household and public-health products","titleCN":"家用与公共卫生用品","definition":"consumer or public-health preparations such as sprays, powders and treated nets","definitionCN":"喷雾、粉剂与浸药蚊帐等消费或公共卫生制剂","example":"The clinic distributes insecticide-treated nets each spring.","exampleCN":"诊所每年春天发放浸药蚊帐。","why":"the delivery form changes, but the active function is still killing insects.","whyCN":"施用形式变了，但有效功能仍是杀死昆虫。"},{"no":"08","title":"Figurative: something that wipes out a group","titleCN":"比喻：一举清除某类人的东西","definition":"figurative, any measure that eliminates a category of people or things wholesale","definitionCN":"比喻用法，指成批清除某类人或事物的任何手段","example":"Critics called the policy an insecticide for small shops.","exampleCN":"批评者把这项政策称为针对小店铺的杀虫剂。","why":"the metaphor keeps the wholesale killing and drops the insects, which makes the word deliberately harsh.","whyCN":"比喻保留成批杀灭、舍去昆虫，正因如此这个词显得刻意刺人。"}],"etymology":{"intro":{"en":"Insecticide is a nineteenth-century compound of insect and Latin -cide 'a cutting, a killing', from caedere 'to cut, strike'.","cn":"insecticide 是 19 世纪复合词，由 insect 与拉丁 -cide「切、杀」构成，后者出自 caedere「切、击」。"},"items":[{"era":"LATIN CAEDERE","en":"Caedere meant 'to cut, strike, kill', and its combining form -cide builds homicide, suicide and pesticide.","cn":"caedere 意为「切、击、杀」，其组合形式 -cide 构成 homicide、suicide、pesticide。"},{"era":"INSECT","en":"Insect came from Latin insectum 'cut into', the calque of Greek entomon, and named the target of the agent.","cn":"insect 来自拉丁 insectum「被切开」，是希腊 entomon 的仿译，命名药剂的作用对象。"},{"era":"NINETEENTH-CENTURY COINAGE","en":"The compound appeared in English as chemical control of crop pests expanded in the nineteenth century.","cn":"随着 19 世纪化学防治农作物害虫的扩展，这个复合词在英语中出现。"},{"era":"TWENTIETH-CENTURY EXPANSION","en":"Synthetic organic compounds made insecticide a mass-market product, and residue and resistance entered the vocabulary with it.","cn":"合成有机化合物使杀虫剂成为大众市场产品，residue 与 resistance 随之进入词汇。"},{"era":"BROADER FAMILY","en":"The model spread to herbicide, fungicide and rodenticide, which share the -cide ending but name different targets.","cn":"这一模式扩展到 herbicide、fungicide、rodenticide，共用 -cide 词尾但对象不同。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the exact earliest English use of insecticide is not firmly dated, so the dating here is approximate.","cn":"来源不确定（首见年代）：insecticide 最早英语书证的确切年代不详，此处年代为约数。"}]},"similar":{"note":{"en":"Group one separates the -cide family, where the target, not the suffix, decides the meaning; group two separates insecticide from related control methods.","cn":"第一组区分 -cide 词族，决定词义的是对象而非后缀；第二组区分杀虫剂与相关防治手段。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pesticide","ipa":"/ˈpestɪsaɪd/","tag":"the wider class","definition":"Pest + -cide covers insects, weeds, fungi and rodents; insecticide is the insect-only member of that class.","definitionCN":"pest 加 -cide 涵盖虫、草、菌、鼠；insecticide 是该类中只针对昆虫的成员。"},{"word":"herbicide","ipa":"/ˈhɜːbɪsaɪd/","tag":"plants","definition":"Herb + -cide kills plants; the ending is the same but the target is entirely different.","definitionCN":"herb 加 -cide 杀植物；词尾相同但对象完全不同。"},{"word":"fungicide","ipa":"/ˈfʌndʒɪsaɪd/","tag":"fungi","definition":"Kills fungi; the shared ending marks killing, not insects.","definitionCN":"杀真菌；共用词尾只标记「杀」，与昆虫无关。"},{"word":"insecticidal","ipa":"/ɪnˌsektɪˈsaɪdl/","tag":"the adjective","definition":"The adjective describes a substance or effect that kills insects; the noun is the substance itself.","definitionCN":"形容词描述杀虫的物质或效果；名词指物质本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"repellent","ipa":"/rɪˈpelənt/","tag":"drives away","definition":"A repellent keeps insects away rather than killing them, so it works before contact.","definitionCN":"驱避剂把昆虫赶开而非杀死，因此在接触之前起作用。"},{"word":"fumigant","ipa":"/ˈfjuːmɪɡənt/","tag":"gas treatment","definition":"A fumigant is a gas released in an enclosed space; it may be insecticidal but is defined by its form.","definitionCN":"熏蒸剂是在封闭空间释放的气体；可能具杀虫性，但以形态定义。"},{"word":"biological control","ipa":"/ˌbaɪəˈlɒdʒɪkl kənˈtrəʊl/","tag":"living agent","definition":"Uses predators or parasites instead of chemicals; insecticide implies a substance, not an organism.","definitionCN":"用捕食者或寄生者代替化学品；insecticide 暗示物质而非生物。"},{"word":"poison","ipa":"/ˈpɔɪzn/","tag":"general harm","definition":"Poison is any harmful substance; insecticide is a poison formulated and labelled for insects.","definitionCN":"poison 泛指任何有害物质；insecticide 是为昆虫配制并标示的毒物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin components, real product terms and real sibling compounds.","cn":"正常联想：真实拉丁成分、真实产品术语与真实同构复合词。"},"normal":[{"en":"insect + -cide 'killing': literally the insect killer.","cn":"insect + -cide「杀」：字面就是杀虫之物。"},{"en":"The -cide family runs pesticide, herbicide, fungicide, rodenticide.","cn":"-cide 词族包括 pesticide、herbicide、fungicide、rodenticide。"},{"en":"Fixed phrases: insecticide resistance, insecticide residue, broad-spectrum insecticide.","cn":"固定搭配：杀虫剂抗性、杀虫剂残留、广谱杀虫剂。"},{"en":"Latin caedere 'to cut, kill' also gives homicide and suicide.","cn":"拉丁 caedere「切、杀」还构成 homicide 与 suicide。"},{"en":"The adjective is insecticidal, formed with -al.","cn":"形容词是 insecticidal，由 -al 构成。"}],"abstract":[{"en":"Picture a fine mist that makes a grip loosen in minutes.","cn":"想象一层细雾，几分钟内就让紧抓的脚松开。"},{"en":"Picture a field where the loudest insects are gone and the quiet ones starve.","cn":"想象一片田，最吵的虫子没了，安静的也随之饿死。"},{"en":"Picture a word so harsh it turns a policy into a poison.","cn":"想象一个词严厉到把政策说成毒药。"}]},"examples":[{"en":"Farmers rotated two insecticides to slow resistance.","cn":"农民轮换使用两种杀虫剂以延缓抗性。"},{"en":"The label warns that the insecticide is toxic to fish.","cn":"标签警告该杀虫剂对鱼有毒。"},{"en":"Bees are exposed to insecticide dust drifting from treated fields.","cn":"蜜蜂会接触到从施药田飘来的杀虫剂粉尘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「insect（昆虫）+ cide（杀）」——杀昆虫的药 → 杀虫剂","word":"insecticide"},"root":"insect（拉丁 insectum「被切开者」，即昆虫）+ 拉丁 -cide「杀」，出自 caedere「切、击、杀」。词源清楚，仅首见年代不确定。","sensesIntro":{"en":"Eight senses follow one spray: an agent kills insects, and the word then names a product class, a broad range, a selective action, a residue, a resistance problem, a household form, and finally any measure that clears a group of people.","cn":"八个义项沿一次喷雾展开：药剂杀死昆虫；词语随后指产品类别、宽作用范围、选择性作用、残留、抗性问题、家用形态，最后指任何成批清除某类人的手段。"},"semanticMap":{"core":{"en":"CORE IMAGE: a fine mist settling on an insect, whose grip loosens within minutes.","cn":"核心意象：细雾落在虫体上，它的抓握几分钟内松开。"},"chain":["KILL INSECTS","A PRODUCT CLASS","WIDE OR NARROW RANGE","LEFT AS RESIDUE","INSECTS ADAPT","A HARSH METAPHOR"],"branches":[{"senses":"S1 · S2","en":"AGENT AND CATEGORY: one substance, then the whole product line.","cn":"药剂与类别：一种物质，然后是整条产品线。"},{"senses":"S3 · S4","en":"RANGE AND ROUTE: broad or selective, contact or systemic.","cn":"范围与路径：广谱或选择，触杀或内吸。"},{"senses":"S5","en":"WHAT REMAINS: the same material measured after use.","cn":"余留之物：使用后被测量的同一材料。"},{"senses":"S6","en":"THE ANSWER: insects evolve around the chemical.","cn":"回应：昆虫在化学压力下演化。"},{"senses":"S7 · S8","en":"FORM AND FIGURE: a household sachet, or a harsh metaphor for elimination.","cn":"形态与修辞：家用小包，或关于清除的严厉比喻。"}]},"affixes":{"intro":{"en":"Insecticide is two roots joined without a prefix: a target noun and a Latin killing suffix.","cn":"insecticide 是两个词根直接相连，无前缀：一个对象名词加拉丁「杀」后缀。"},"latinIntro":{"en":"Latin caedere supplies -cide, and the same suffix builds pesticide, herbicide and homicide; insectum supplies the target.","cn":"拉丁 caedere 提供 -cide，同一后缀构成 pesticide、herbicide、homicide；insectum 提供对象。"},"items":[{"word":"insect","structure":"in- + secare (Latin participle used as noun)","meaning":"a segmented creature","meaningCN":"分节的生物","example":"The insect is the target.","exampleCN":"昆虫是目标。"},{"word":"-cide","structure":"-cide (Latin suffix, from caedere 'to kill')","meaning":"killing; a killer","meaningCN":"杀；杀者","example":"The suffix states the function.","exampleCN":"这个后缀说明功能。"},{"word":"caedere","structure":"caedere, cecidi, caesum (verb, third conjugation)","meaning":"to cut, strike, kill","meaningCN":"切；击；杀","example":"The same root builds homicide.","exampleCN":"同一词根构成 homicide。"},{"word":"-al","structure":"insecticidal = insecticide + -al","meaning":"having the quality of killing insects","meaningCN":"具杀虫性质的","example":"The dust had an insecticidal effect.","exampleCN":"这种粉尘有杀虫效果。"},{"word":"pesticide","structure":"pest + -cide","meaning":"a killer of pests generally","meaningCN":"泛指杀灭有害生物之物","example":"Pesticide is the wider legal category.","exampleCN":"pesticide 是更宽的法律类别。"},{"word":"herbicide","structure":"herb + -cide","meaning":"a killer of plants","meaningCN":"杀植物之物","example":"Herbicide is used between the rows.","exampleCN":"除草剂用在行间。"},{"word":"fungicide","structure":"fungi + -cide","meaning":"a killer of fungi","meaningCN":"杀真菌之物","example":"Fungicide protects the vines.","exampleCN":"杀真菌剂保护葡萄藤。"},{"word":"rodenticide","structure":"rodent + -cide","meaning":"a killer of rodents","meaningCN":"杀鼠剂","example":"Rodenticide is placed in bait stations.","exampleCN":"杀鼠剂放在饵站里。"},{"word":"-cidal","structure":"-cidal (adjectival form of -cide)","meaning":"killing, as a suffix","meaningCN":"具杀灭作用的（后缀）","example":"The label lists the cidal spectrum.","exampleCN":"标签列出杀灭谱。"}],"latinEntries":[{"word":"caedere","structure":"caedere, cecidi, caesum (verb, third conjugation)","meaning":"to cut, strike, kill","meaningCN":"切；击；杀"},{"word":"insectum","structure":"insectum, insecti (n., second declension)","meaning":"insect","meaningCN":"昆虫"},{"word":"caedes","structure":"caedes, caedis (f., third declension)","meaning":"a cutting down, slaughter","meaningCN":"砍倒；杀戮"}]}},{"word":"butterfly","ipa_uk":"/ˈbʌtəflaɪ/","ipa_us":"/ˈbʌtərflaɪ/","definition_zh":"蝴蝶；蝶泳；（因紧张而）心里发慌、七上八下；社交场上的活跃者；蝶式（布局）","definition_en":"an insect with four large often brightly coloured wings, flying by day and resting with wings held together","core_image":"一片晒暖的石头上停着一只蝶，四片薄翼合成一面竖起的纸扇，被风一吹又张开成两页书","scene":"阳光落在石墙上，一只翅膀上有黑边的橙色昆虫停了几秒，又忽然飞起。 A butterfly opened and closed its wings on the warm stone before drifting to the next flower.","sceneCN":"这里 butterfly 指「蝴蝶」（第 1 个义项：白天活动、四翅宽大的鳞翅目昆虫）；句意为一只蝴蝶在暖石上开合双翅，随后飘向下一朵花。","pos":[{"tag":"n.","zh":"蝴蝶；蝶泳；紧张感；社交活跃者；蝶式"},{"tag":"v.","zh":"（口语）紧张得发慌；把……切成蝶形"}],"collocations":[{"phrase":"butterfly wing","zh":"蝶翼"},{"phrase":"butterfly stroke","zh":"蝶泳"},{"phrase":"butterflies in one's stomach","zh":"心里七上八下"},{"phrase":"butterfly garden","zh":"蝶园"},{"phrase":"monarch butterfly","zh":"黑脉金斑蝶"},{"phrase":"butterfly effect","zh":"蝴蝶效应"}],"forms":[{"label":"原形","form":"butterfly"},{"label":"复数","form":"butterflies"},{"label":"三单（动词）","form":"butterflies"},{"label":"过去式","form":"butterflied"},{"label":"现在分词","form":"butterflying"},{"label":"同根名词（幼虫）","form":"caterpillar"}],"derivatives":[{"word":"butterfly","pos":"n./v.","zh":"蝴蝶；蝶泳；紧张"},{"word":"butterflying","pos":"n.","zh":"蝶式剖切；蝶形加工"},{"word":"butterfly-like","pos":"adj.","zh":"蝶状的"},{"word":"butterflyfish","pos":"n.","zh":"蝴蝶鱼"},{"word":"butterfly net","pos":"n.","zh":"捕蝶网"}],"senses":[{"no":"01","title":"The day-flying insect with broad wings","titleCN":"白日活动的宽翅昆虫","definition":"an insect of the order Lepidoptera that flies by day and has four broad, usually patterned wings","definitionCN":"鳞翅目中白天活动、有四大片通常带花纹的翅的昆虫","example":"A butterfly opened and closed its wings on the warm stone.","exampleCN":"一只蝴蝶在暖石上开合双翅。","why":"the core sense is the animal itself, and every other sense extends some visible feature of it: wings, fluttering, or flight.","whyCN":"核心义就是这种动物，其它义项都是对它某一可见特征的延伸：翅、扑动或飞行。"},{"no":"02","title":"The contrast with moths","titleCN":"与蛾相对的那一类","definition":"the group of Lepidoptera distinguished from moths by day flight and by club-tipped antennae","definitionCN":"鳞翅目中因白日飞行与棒状触角而与蛾相区分的那一类","example":"Butterflies rest with wings closed; most moths spread theirs flat.","exampleCN":"蝴蝶停歇时合起翅膀；多数蛾则平展。","why":"the word is used as a category name where the contrast, not the individual, is the point.","whyCN":"当重点是对照而非个体时，这个词用作类别名。"},{"no":"03","title":"A named species or group","titleCN":"某一具体种类或类群","definition":"a particular species, family or genus within the butterflies","definitionCN":"蝴蝶中的一个具体种、科或属","example":"The monarch butterfly migrates thousands of kilometres.","exampleCN":"黑脉金斑蝶迁徙数千公里。","why":"common names attach to the general word, so the species is named by qualifying it rather than by a new noun.","whyCN":"俗名附着于通名，因此物种靠加限定语命名，而不另造名词。"},{"no":"04","title":"The swimming stroke","titleCN":"游泳的蝶泳","definition":"a swimming stroke in which both arms move together over the water and the body undulates","definitionCN":"双臂同时越出水面、身体起伏前进的泳姿","example":"She swam the butterfly for the last fifty metres.","exampleCN":"最后五十米她游的是蝶泳。","why":"the stroke imitates the symmetrical flapping of wings, so the insect name became the name of the motion.","whyCN":"这种泳姿模仿双翅对称扑动，因此昆虫名成了动作名。"},{"no":"05","title":"A nervous fluttering in the stomach","titleCN":"紧张时腹中的扑动感","definition":"a fluttering sensation of anxiety felt before something important","definitionCN":"在重要事情之前感到的、类似扑动的焦虑感","example":"He had butterflies before stepping onto the stage.","exampleCN":"上台之前他心里七上八下。","why":"the metaphor keeps only the fluttering motion inside the body, which is why the plural is fixed in this idiom.","whyCN":"比喻只保留体内扑动的动感，因此这个习语固定用复数。"},{"no":"06","title":"A socially active person","titleCN":"社交场上四处穿梭的人","definition":"a person who moves from one group to another at social events","definitionCN":"在社交场合从一群人飘到另一群人的人","example":"He is a social butterfly who knows every room.","exampleCN":"他是个社交蝴蝶，每个场合都熟。","why":"the metaphor keeps the movement from flower to flower, with people standing in for flowers.","whyCN":"比喻保留「从花到花」的移动，只是把花换成了人。"},{"no":"07","title":"A small sensitive dependence in a system","titleCN":"系统中微小的敏感依赖","definition":"in chaos theory, the property that a tiny change in initial conditions grows into a large difference","definitionCN":"混沌理论中，初始条件的极小改变会发展成巨大差异的性质","example":"The butterfly effect makes long-range forecasts unreliable.","exampleCN":"蝴蝶效应使长期预报不可靠。","why":"the image is a wingbeat that ends in a storm, so the insect supplies the name for a mathematical property.","whyCN":"意象是一次振翅最终引来风暴，昆虫于是为一种数学性质提供了名称。"},{"no":"08","title":"A shape that opens from a centre","titleCN":"自中心向两侧展开的形状","definition":"a layout or cut that spreads symmetrically from a central line, as in a butterfly roof or a butterfly valve","definitionCN":"沿中线对称展开的布局或切法，如蝶形屋顶或蝶阀","example":"The butterfly roof collects rain at the centre.","exampleCN":"蝶形屋顶在中线汇水。","why":"the shape of two wings joined at a body is simply transferred to objects, with no change of meaning beyond form.","whyCN":"两翅相接于身体的形状被直接移植到物件上，除形态外词义无变化。"}],"etymology":{"intro":{"en":"Butterfly is an Old English compound whose first element is disputed; the second is fly, and the whole has meant the insect since the earliest records.","cn":"butterfly 是古英语复合词，第一成分的来历有争议；第二成分是 fly「蝇」，整体自最早记录起就指这种昆虫。"},"items":[{"era":"OLD ENGLISH BUTORFLEOGE","en":"Old English butorfleoge already meant the butterfly, so the compound is older than any surviving explanation of its first element.","cn":"古英语 butorfleoge 已指蝴蝶，因此这个复合词比任何关于第一成分的现存解释都更古老。"},{"era":"BUTTER HYPOTHESIS","en":"One common explanation links the first element to butter, either from the colour of some species or from an old belief that butterflies stole butter.","cn":"常见解释之一把第一成分与 butter「黄油」联系，理由或是一些种类的颜色，或旧时传说蝶会偷黄油。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the first element is not settled; a link to a Germanic word for a butterfly or to a churning motion has also been proposed, and none is demonstrated.","cn":"来源不确定（词根）：第一成分尚无定论；也有把它联系到日耳曼语某种蝴蝶名称或搅拌动作的说法，均未得到证明。"},{"era":"FLY","en":"The second element is the native fly, used loosely in old compounds for any flying insect.","cn":"第二成分是本族词 fly「蝇」，在古复合词中宽泛指任何飞虫。"},{"era":"SPORTING AND MEDICAL EXTENSIONS","en":"The swimming stroke and the fluttering of the stomach both appeared in the twentieth century as images of wing motion.","cn":"蝶泳与腹中扑动感都出现于 20 世纪，取自振翅的意象。"},{"era":"TECHNICAL USE","en":"In the later twentieth century butterfly named symmetric shapes in engineering and a sensitive dependence in chaos theory.","cn":"20 世纪后期，butterfly 指工程中的对称形状，也指混沌理论中的敏感依赖。"}]},"similar":{"note":{"en":"Group one separates butterfly from its nearest look-alikes among insects; group two separates the word from the other senses it is often confused with.","cn":"第一组区分 butterfly 与近似的昆虫名；第二组区分它与常被混淆的其它义项。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"moth","ipa":"/mɒθ/","tag":"the night relative","definition":"The other large group of Lepidoptera: mostly nocturnal, antennae not club-tipped, wings held flat at rest.","definitionCN":"鳞翅目的另一大类：多夜间活动，触角非棒状，停歇时翅平展。"},{"word":"caterpillar","ipa":"/ˈkætəpɪlə/","tag":"the larva","definition":"The feeding stage that hatches from the egg; the butterfly is the adult it becomes after pupation.","definitionCN":"自卵孵出的取食阶段；蝴蝶是它化蛹后的成虫。"},{"word":"butterflyfish","ipa":"/ˈbʌtəflaɪfɪʃ/","tag":"a fish, not an insect","definition":"A reef fish named for its wing-like fins; the compound looks like a butterfly but names a vertebrate.","definitionCN":"珊瑚礁鱼，因鳍似翅而得名；复合词形似蝴蝶，却指脊椎动物。"},{"word":"butterfly net","ipa":"/ˈbʌtəflaɪ net/","tag":"the tool","definition":"A light net on a hoop for catching butterflies; the word modifies an object rather than naming the animal.","definitionCN":"用来捕蝶的轻网配圆框；这个词修饰物件而非命名动物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"flutter","ipa":"/ˈflʌtə/","tag":"the motion","definition":"Flutter is the quick irregular movement of wings; butterfly names the animal or, by transfer, the stroke.","definitionCN":"flutter 指翅膀快速不规则的动；butterfly 指动物，或经转移指泳姿。"},{"word":"nervousness","ipa":"/ˈnɜːvəsnəs/","tag":"the feeling","definition":"Nervousness is the plain word for the state; butterflies is the informal image of the same state.","definitionCN":"nervousness 是这一状态的普通词；butterflies 是同一状态的口语意象。"},{"word":"socialite","ipa":"/ˈsəʊʃəlaɪt/","tag":"the person, neutral","definition":"A socialite is a prominent person in fashionable society; social butterfly is lighter and mildly mocking.","definitionCN":"socialite 指上流社交界的知名人物；social butterfly 更轻，略带调侃。"},{"word":"dragonfly","ipa":"/ˈdræɡənflaɪ/","tag":"different order","definition":"A dragonfly has two pairs of long narrow wings held outstretched and is not a butterfly at all.","definitionCN":"蜻蜓有两对长而窄的翅平展在外，完全不是蝴蝶。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real compound, real species names and real transferred senses.","cn":"正常联想：真实复合结构、真实物种名与真实转移义。"},"normal":[{"en":"butter + fly is the traditional reading, though the first element is not settled.","cn":"butter + fly 是传统解读，但第一成分尚无定论。"},{"en":"The family runs butterfly, butterflies, butterflyfish, butterfly net.","cn":"同族词包括 butterfly、butterflies、butterflyfish、butterfly net。"},{"en":"Fixed phrases: butterfly stroke, monarch butterfly, butterfly effect.","cn":"固定搭配：蝶泳、黑脉金斑蝶、蝴蝶效应。"},{"en":"The idiom butterflies in one's stomach is fixed in the plural.","cn":"习语 butterflies in one's stomach 固定用复数。"},{"en":"The larva is a caterpillar; the adult is a butterfly.","cn":"幼虫是 caterpillar；成虫是 butterfly。"}],"abstract":[{"en":"Picture two pages of a book joined at the spine, opening and closing.","cn":"想象一本书的两页在书脊相连，一开一合。"},{"en":"Picture a person crossing a room in short hops from group to group.","cn":"想象一个人在一间屋里，从一群到另一群地短跳。"},{"en":"Picture one wingbeat that ends, months later, in a storm.","cn":"想象一次振翅，数月之后终于成了一场风暴。"}]},"examples":[{"en":"Butterflies warm their flight muscles in direct sun before taking off.","cn":"蝴蝶起飞前会在直射阳光下暖起飞行肌。"},{"en":"The butterfly effect was named after a wingbeat in a weather model.","cn":"蝴蝶效应得名于天气模型中的一次振翅。"},{"en":"She felt butterflies the moment her name was called.","cn":"名字被叫到的那一刻，她心里一阵发慌。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「butter（黄油）+ fly（飞虫）」——传说偷黄油的飞虫 → 蝴蝶；引申为扑动、蝶泳","word":"butterfly"},"root":"古英语 butorfleoge「蝴蝶」，第二成分是本族 fly「飞虫」；第一成分来历有争议，与 butter「黄油」的联系属常见解释而非已证词源，词根来源不确定。","sensesIntro":{"en":"Eight senses follow one pair of wings: a broad-winged insect flies by day, and its shape and motion are then given to a stroke, a stomach fluttering, a sociable person, a chaotic system, and two symmetric structures.","cn":"八个义项沿一对翅膀展开：宽翅昆虫白日飞行；它的形状与动作随后被交给一种泳姿、腹中的扑动、社交活跃者、混沌系统，以及两种对称结构。"},"semanticMap":{"core":{"en":"CORE IMAGE: four thin wings meeting at a small body, opening like two pages.","cn":"核心意象：四片薄翅汇于一个小身体，像两页书那样开合。"},"chain":["BROAD WINGS","DAY FLIGHT","NAMED SPECIES","SYMMETRIC STROKE","FLUTTER INSIDE","SENSITIVE SYSTEM"],"branches":[{"senses":"S1 · S2 · S3","en":"THE ANIMAL: individual, category, and one named species.","cn":"动物本身：个体、类别与某一具名物种。"},{"senses":"S4 · S8","en":"SYMMETRY: two wings moving together become a stroke and a roof.","cn":"对称：双翅同动成为一种泳姿与一片屋顶。"},{"senses":"S5","en":"FLUTTER INSIDE: the motion moves from air into the stomach.","cn":"体内扑动：动作从空中移到腹中。"},{"senses":"S6","en":"FLITTING BETWEEN PEOPLE: flowers are replaced by groups of people.","cn":"在人之间飘走：花被一群人换掉。"},{"senses":"S7","en":"SMALL CAUSE: one wingbeat grows into a storm.","cn":"微小起因：一次振翅长成风暴。"}]},"affixes":{"intro":{"en":"Butterfly is a native compound of two English words, and neither element is a Latin prefix or suffix.","cn":"butterfly 是两个英语词构成的本族复合词，两个成分都不是拉丁前后缀。"},"latinIntro":{"en":"No Latin element is involved; the Latin entries below are the learned names for butterflies and for scales.","cn":"此处不涉及拉丁成分；下列拉丁条目是蝴蝶与鳞片的学术名称。"},"items":[{"word":"butter","structure":"butter (native noun, first element)","meaning":"butter, by the traditional explanation","meaningCN":"黄油（按传统解释）","example":"The first element is explained by colour or by an old legend.","exampleCN":"第一成分由颜色或旧传说解释。"},{"word":"fly","structure":"fly (native noun, second element)","meaning":"a flying insect","meaningCN":"飞虫","example":"Old compounds use fly for any winged insect.","exampleCN":"古复合词用 fly 泛指任何有翅昆虫。"},{"word":"butterflies","structure":"butterfly + -es (plural)","meaning":"more than one butterfly","meaningCN":"多只蝴蝶","example":"Butterflies gather at the wet sand.","exampleCN":"蝴蝶聚在湿沙上。"},{"word":"-fish","structure":"butterflyfish = butterfly + fish","meaning":"a fish with wing-like fins","meaningCN":"鳍似翅的鱼","example":"The butterflyfish pairs for years.","exampleCN":"蝴蝶鱼成对多年。"},{"word":"-like","structure":"butterfly-like = butterfly + -like","meaning":"resembling a butterfly","meaningCN":"似蝴蝶的","example":"The kite had a butterfly-like outline.","exampleCN":"这只风筝外形似蝶。"},{"word":"-ed","structure":"butterflied = butterfly + -ed (verb participle)","meaning":"cut open and spread like wings","meaningCN":"剖开摊成蝶形的","example":"The chef butterflied the fish.","exampleCN":"厨师把鱼剖开摊平。"},{"word":"-ing","structure":"butterflying = butterfly + -ing","meaning":"the act of spreading open","meaningCN":"摊开成蝶形的动作","example":"Butterflying shortens the cooking time.","exampleCN":"剖开摊平能缩短烹饪时间。"},{"word":"stroke","structure":"butterfly stroke (compound)","meaning":"the swimming stroke","meaningCN":"蝶泳","example":"The butterfly stroke is the hardest to learn.","exampleCN":"蝶泳最难学。"},{"word":"effect","structure":"butterfly effect (compound)","meaning":"sensitive dependence on small causes","meaningCN":"对小起因的敏感依赖","example":"The butterfly effect limits forecasts.","exampleCN":"蝴蝶效应限制预报。"}],"latinEntries":[{"word":"papilio","structure":"papilio, papilionis (m., third declension)","meaning":"butterfly","meaningCN":"蝴蝶"},{"word":"lepidoptera","structure":"Greek lepis 'scale' + pteron 'wing' (order name)","meaning":"the scaled-winged insects","meaningCN":"鳞翅目昆虫"},{"word":"squama","structure":"squama, squamae (f., first declension)","meaning":"scale","meaningCN":"鳞片"}]}},{"word":"moth","ipa_uk":"/mɒθ/","ipa_us":"/mɑːθ/","definition_zh":"蛾；蛾类；（衣物等的）蛀虫；蛾状物","definition_en":"a mainly night-flying insect related to the butterfly, with wings that are usually held flat and antennae without clubs","core_image":"一只灰褐色的蛾贴着墙停在灯下，翅平摊成一片薄瓦，粉末状的鳞在手一抹就掉","scene":"夜里灯一亮，窗玻璃上就贴满了灰扑扑的翅膀。 A pale moth circled the lamp three times before settling on the wall.","sceneCN":"这里 moth 指「蛾」（第 1 个义项：多夜间活动、停歇时翅平展的鳞翅目昆虫）；句意为一只浅色蛾绕灯三圈，最后停在墙上。","pos":[{"tag":"n.","zh":"蛾；蛾类；蛀虫（衣蛾等）"},{"tag":"adj.","zh":"蛾的；被蛾蛀坏的（多用于复合词）"}],"collocations":[{"phrase":"clothes moth","zh":"衣蛾"},{"phrase":"moth-eaten","zh":"被虫蛀的；破旧的"},{"phrase":"moth trap","zh":"诱蛾灯；捕蛾器"},{"phrase":"moth ball","zh":"樟脑丸；防蛾球"},{"phrase":"silkworm moth","zh":"蚕蛾"},{"phrase":"moth species","zh":"蛾类物种"},{"phrase":"moth wing","zh":"蛾翅"}],"forms":[{"label":"原形","form":"moth"},{"label":"复数","form":"moths"},{"label":"形容词（被蛀的）","form":"moth-eaten"},{"label":"复合名词（防蛾丸）","form":"mothball"},{"label":"复合名词（诱蛾灯）","form":"moth trap"}],"derivatives":[{"word":"mothball","pos":"n./v.","zh":"防蛾丸；封存、搁置"},{"word":"moth-eaten","pos":"adj.","zh":"被虫蛀的；陈旧的"},{"word":"mothproof","pos":"adj./v.","zh":"防蛀的；做防蛀处理"},{"word":"mothy","pos":"adj.","zh":"满是蛾的；有蛾蛀痕迹的"},{"word":"moth trap","pos":"n.","zh":"诱蛾器"}],"senses":[{"no":"01","title":"The night-flying relative of the butterfly","titleCN":"蝴蝶的近亲，多在夜间活动","definition":"an insect of the order Lepidoptera that is usually active at night and rests with wings spread flat","definitionCN":"鳞翅目中通常夜间活动、停歇时平展双翅的昆虫","example":"A pale moth circled the lamp three times.","exampleCN":"一只浅色蛾绕灯转了三圈。","why":"the word has meant this animal since Old English, and everything else it names is taken from the insect's habits or its damage.","whyCN":"这个词自上古英语起就指这种动物，其它所指都取自它的习性或其造成的损害。"},{"no":"02","title":"The whole group contrasted with butterflies","titleCN":"与蝴蝶相对的整个类群","definition":"the nocturnal division of the Lepidoptera, as a category in classification and in counts","definitionCN":"鳞翅目中的夜间类群，作为分类与计数中的一个类别","example":"Moths outnumber butterflies in almost every habitat.","exampleCN":"在几乎所有生境中，蛾的数量都超过蝴蝶。","why":"as a category the word is plural and uncountable in practice, because the point is the group, not one animal.","whyCN":"作为类别，这个词实际上用复数且近乎不可数，因为重点是群体而非一只。"},{"no":"03","title":"The household clothes moth","titleCN":"家中的衣蛾","definition":"a small species whose larvae eat wool, fur and stored fabric","definitionCN":"幼虫取食羊毛、毛皮与储存织物的小型物种","example":"A moth had eaten a hole through the sleeve.","exampleCN":"一只衣蛾在袖子上蛀出一个洞。","why":"the everyday sense narrows to the one species that enters houses and causes loss.","whyCN":"日常义收窄到那一种进入住宅并造成损失的物种。"},{"no":"04","title":"Damage described as moth-eaten","titleCN":"以「被蛾蛀」形容的损坏","definition":"the state of fabric or fur that has been holed by moth larvae","definitionCN":"织物或毛皮被蛾类幼虫蛀出孔洞的状态","example":"The coat was moth-eaten at the collar.","exampleCN":"这件外套的领子被虫蛀了。","why":"the insect's name becomes an adjective for its effect, so damage is described by its cause.","whyCN":"昆虫名转为描述其效果的形容词，因此损坏由起因来描述。"},{"no":"05","title":"A ball that keeps moths away","titleCN":"驱蛾的丸球","definition":"a small ball of a strong-smelling chemical placed among stored clothes to repel moths","definitionCN":"放在储存衣物之间、以强烈气味驱蛾的小球","example":"She put a moth ball in each wool blanket.","exampleCN":"她在每条羊毛毯里放了一颗防蛾丸。","why":"the compound names the object by the insect it repels, a common pattern in household vocabulary.","whyCN":"这个复合词以它所驱赶的昆虫来命名物件，这是家用词汇中常见的模式。"},{"no":"06","title":"To mothball a ship or a plan","titleCN":"把船或计划封存搁置","definition":"to put a ship, factory or plan into storage, out of use but kept in condition","definitionCN":"把船、工厂或计划封存起来，停用但保持状态","example":"The fleet was mothballed for a decade.","exampleCN":"这支船队被封存了十年。","why":"the verb grew from the noun mothball, and then generalized to any suspended project.","whyCN":"动词由名词 mothball 长出，随后泛化到任何被搁置的项目。"},{"no":"07","title":"Attraction to a light trap","titleCN":"被灯光诱捕","definition":"the habit of moths flying to artificial light, used in survey traps","definitionCN":"蛾飞向人造光源的习性，被用于调查诱捕","example":"The moth trap ran all night and filled with hundreds of species.","exampleCN":"诱蛾灯整夜开着，装满了数百个物种。","why":"the word stands for the animal whose behaviour defines the method.","whyCN":"这个词代表那类动物，而其习性定义了这种方法。"},{"no":"08","title":"Figurative: drawn toward one's own harm","titleCN":"比喻：被引向自身的毁灭","definition":"figurative, a person or thing irresistibly attracted to what will destroy it","definitionCN":"比喻用法，指被必将毁灭自己之物不可抗拒地吸引的人或事物","example":"He went to the meeting like a moth to a flame.","exampleCN":"他去赴会，像飞蛾扑火一样。","why":"the metaphor keeps two features only: attraction and self-destruction, dropping the insect.","whyCN":"比喻只保留两个特征：被吸引与自我毁灭，昆虫本身被舍去。"}],"etymology":{"intro":{"en":"Moth is an Old English word with Germanic relatives and a disputed deeper origin; the related sense of clothes damage is medieval.","cn":"moth 是古英语词，有日耳曼同族词，更深来源有争议；与衣物损害相关的义项为中世纪所出。"},"items":[{"era":"OLD ENGLISH MOTHTHE","en":"Old English moththe meant both the insect and the larva that eats cloth, a double sense the modern word keeps.","cn":"古英语 moththe 既指昆虫，也指吃布的幼虫，现代词保留了这双重含义。"},{"era":"GERMANIC COGNATES","en":"Old Norse motti, Middle Dutch mot and German Motte point to a common Germanic stock rather than a borrowing.","cn":"古诺斯语 motti、中古荷兰语 mot、德语 Motte 表明共同的日耳曼来源，而非借词。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the pre-Germanic origin of moth is unresolved; a link to a word for a maggot or for a gnawing creature has been suggested but not demonstrated.","cn":"来源不确定（词根）：moth 在日耳曼语之前的来源无定论；与「蛆」或「啃咬者」某词的联系属提议，未获得证明。"},{"era":"HOUSEHOLD SENSE","en":"From the medieval period the word was applied to the small cloth-eating species, and mothball followed in the nineteenth century.","cn":"自中世纪起这个词用于吃布的小型物种，mothball 于 19 世纪随之出现。"},{"era":"VERB BY CONVERSION","en":"Mothball became a verb meaning to store and preserve, later extended to any suspended plan.","cn":"mothball 转为动词，意为封存保存，后扩展至任何被搁置的计划。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest record of the figurative 'moth to a flame' use is not firmly dated, so the dating here is approximate.","cn":"来源不确定（首见年代）：比喻义「飞蛾扑火」的最早记录年代不详，此处年代为约数。"}]},"similar":{"note":{"en":"Group one separates moth from the insects it is confused with; group two separates it from the words built on its name.","cn":"第一组区分 moth 与易混昆虫；第二组区分它与建在其名上的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"butterfly","ipa":"/ˈbʌtəflaɪ/","tag":"the day relative","definition":"Flies by day, antennae club-tipped, wings held together at rest; the everyday dividing line between the two groups.","definitionCN":"白天飞行、触角棒状、停歇时合翅；这是两群之间的日常分界。"},{"word":"moth-eaten","ipa":"/ˈmɒθ iːtn/","tag":"the adjective","definition":"Describes fabric holed by larvae, and figuratively anything worn out or stale.","definitionCN":"描述被幼虫蛀出孔的织物，比喻义指陈旧破败之物。"},{"word":"mothball","ipa":"/ˈmɒθbɔːl/","tag":"the object and the verb","definition":"As a noun a repellent ball, as a verb to store something out of use.","definitionCN":"名词指驱蛾球，动词指把某物封存停用。"},{"word":"silkworm","ipa":"/ˈsɪlkwɜːm/","tag":"the larva of a moth","definition":"The caterpillar of a domesticated moth; the adult is a moth, but the economic word is for the larva.","definitionCN":"家养蛾的幼虫；成虫是蛾，但经济用词指的是幼虫。"}]},{"heading":"NEAR MEANING","entries":[{"word":"larva","ipa":"/ˈlɑːvə/","tag":"the stage","definition":"Larva is the feeding stage of any insect; the cloth-damaging moth is only the larval stage of a small species.","definitionCN":"larva 是任何昆虫的取食阶段；蛀布者只是某一小型种的幼虫阶段。"},{"word":"midge","ipa":"/mɪdʒ/","tag":"small fly","definition":"A midge is a small two-winged fly, not a moth; the confusion comes from size and night flight.","definitionCN":"midge 是小型双翅蝇类，不是蛾；混淆来自体型与夜间飞行。"},{"word":"bug","ipa":"/bʌɡ/","tag":"loose label","definition":"A general word for a small crawling insect; it carries none of the night-flight or cloth-eating detail.","definitionCN":"小爬虫的泛称，不含夜飞或蛀布的细节。"},{"word":"vermin","ipa":"/ˈvɜːmɪn/","tag":"a judgement","definition":"Vermin is a category of harmful animals; a moth is vermin only when it damages stored goods.","definitionCN":"vermin 是有害动物的类别；蛾只在损害储存物时才算。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Germanic relatives, real compounds and real idioms.","cn":"正常联想：真实日耳曼同族词、真实复合词与真实习语。"},"normal":[{"en":"The Germanic relatives are Old Norse motti, Middle Dutch mot and German Motte.","cn":"日耳曼同族词是古诺斯语 motti、中古荷兰语 mot、德语 Motte。"},{"en":"The family runs moth, moths, mothball, moth-eaten, mothproof, moth trap.","cn":"同族词包括 moth、moths、mothball、moth-eaten、mothproof、moth trap。"},{"en":"Fixed phrases: clothes moth, silkworm moth, moth species.","cn":"固定搭配：衣蛾、蚕蛾、蛾类物种。"},{"en":"The idiom like a moth to a flame is the standard figurative use.","cn":"习语 like a moth to a flame 是标准比喻用法。"},{"en":"Moths hold their wings flat; butterflies close theirs.","cn":"蛾平展双翅；蝴蝶合起。"}],"abstract":[{"en":"Picture a dust of scales left on a hand after one touch.","cn":"想象一触之后留在手上的那层鳞粉。"},{"en":"Picture a coat kept for thirty years with three holes in the collar.","cn":"想象一件存了三十年的外套，领子上三个洞。"},{"en":"Picture a light so bright that it ends the flyer.","cn":"想象一盏亮到足以终结飞者的灯。"}]},"examples":[{"en":"Most moths are active only after the light fails.","cn":"多数蛾只在光线消失之后活动。"},{"en":"The specimen drawer was sealed to keep moths out.","cn":"标本抽屉密封起来，以防蛾进入。"},{"en":"They mothballed the plant rather than sell it.","cn":"他们选择封存工厂，而不是出售。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「moth」——夜里绕灯、翅上掉粉、还蛀衣服的虫 → 蛾","word":"moth"},"root":"古英语 moththe「蛾；吃布的幼虫」，与古诺斯语 motti、中古荷兰语 mot、德语 Motte 同出日耳曼词；日耳曼语之前词根来源不确定。","sensesIntro":{"en":"Eight senses follow one night flyer: a flat-winged insect comes to the lamp, and the word then names a whole category, a household pest, its damage, the ball that repels it, the act of storing something away, a survey method, and finally a figure for self-destructive attraction.","cn":"八个义项沿一只夜行飞虫展开：平翅昆虫来到灯下；词语随后指整个类群、家中害虫、它造成的损坏、驱它的丸球、把东西封存起来的行为、一种调查方法，最后指自毁式吸引的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a grey-brown flyer pressed flat against the wall under a lamp.","cn":"核心意象：一只灰褐色飞虫在灯下平贴墙上。"},"chain":["FLAT WINGS AT NIGHT","THE NOCTURNAL GROUP","CLOTH-EATING LARVA","THE REPELLENT BALL","STORE AND SUSPEND","DRAWN TO THE LIGHT"],"branches":[{"senses":"S1 · S2","en":"ANIMAL AND CATEGORY: one insect, then the group it belongs to.","cn":"动物与类别：一只昆虫，然后是它所属的群。"},{"senses":"S3 · S4","en":"HOUSEHOLD LOSS: the small species and the holes it leaves.","cn":"家中损失：小型物种与它留下的洞。"},{"senses":"S5 · S6","en":"REPELLENT AND STORAGE: the ball first keeps moths away, then names putting things away.","cn":"驱避与封存：丸球先把蛾赶走，随后指把东西收起来。"},{"senses":"S7","en":"METHOD: the animal's attraction becomes a survey tool.","cn":"方法：动物的趋光性成为调查工具。"},{"senses":"S8","en":"SELF-DESTRUCTION: the flame image survives without the insect.","cn":"自我毁灭：火的意象留存，昆虫被舍去。"}]},"affixes":{"intro":{"en":"Moth is a bare Germanic noun that forms compounds rather than taking Latin affixes.","cn":"moth 是裸露的日耳曼名词，主要构成复合词，而不接拉丁词缀。"},"latinIntro":{"en":"No Latin element is present; the Latin entries below are the learned nouns for moth and for the order it belongs to.","cn":"此处不含拉丁成分；下列拉丁条目是蛾及其所属目的学术名称。"},"items":[{"word":"moth","structure":"moth (Old English noun)","meaning":"the night-flying insect","meaningCN":"夜行飞虫","example":"A moth came in through the open window.","exampleCN":"一只蛾从开着的窗进来。"},{"word":"-s","structure":"moths = moth + -s (plural)","meaning":"more than one moth","meaningCN":"多只蛾","example":"Moths filled the trap by midnight.","exampleCN":"到午夜诱捕器已装满蛾。"},{"word":"-eaten","structure":"moth-eaten = moth + eaten (compound adjective)","meaning":"holed by moth larvae","meaningCN":"被蛾类幼虫蛀出孔的","example":"The blanket was moth-eaten.","exampleCN":"毯子被虫蛀了。"},{"word":"-ball","structure":"mothball = moth + ball (compound noun)","meaning":"a ball that repels moths","meaningCN":"驱蛾的球","example":"Mothballs smell of camphor.","exampleCN":"防蛾丸有樟脑味。"},{"word":"-proof","structure":"mothproof = moth + -proof (protecting against)","meaning":"treated to resist moths","meaningCN":"经处理而防蛾的","example":"The wool was mothproofed before storage.","exampleCN":"羊毛在储存前做了防蛀处理。"},{"word":"moth trap","structure":"moth + trap (compound)","meaning":"a device that attracts and catches moths","meaningCN":"诱捕蛾的装置","example":"The moth trap ran from dusk to dawn.","exampleCN":"诱蛾灯从黄昏开到黎明。"},{"word":"clothes moth","structure":"clothes + moth (compound)","meaning":"the species that damages fabric","meaningCN":"损害织物的蛾种","example":"Clothes moths avoid light.","exampleCN":"衣蛾避光。"},{"word":"silkworm moth","structure":"silkworm + moth (compound)","meaning":"the adult of the silk-producing species","meaningCN":"产丝种的成虫","example":"The silkworm moth cannot fly well.","exampleCN":"蚕蛾飞行能力差。"},{"word":"mothy","structure":"moth + -y (adjective)","meaning":"full of moths, or marked by moth damage","meaningCN":"多蛾的；有蛀痕的","example":"The attic smelled mothy.","exampleCN":"阁楼里有股蛀虫味。"}],"latinEntries":[{"word":"tinea","structure":"tinea, tineae (f., first declension)","meaning":"a clothes moth, a gnawing worm","meaningCN":"衣蛾；蛀虫"},{"word":"papilio","structure":"papilio, papilionis (m., third declension)","meaning":"butterfly or moth","meaningCN":"蝴蝶或蛾"},{"word":"lepidoptera","structure":"Greek lepis 'scale' + pteron 'wing' (order name)","meaning":"the scaled-winged insects","meaningCN":"鳞翅目昆虫"}]}},{"word":"beetle","ipa_uk":"/ˈbiːtl/","ipa_us":"/ˈbiːtl/","definition_zh":"甲虫；鞘翅目昆虫；（口语）匆匆小跑","definition_en":"an insect whose front wings are hardened into protective cases over the folded hind wings","core_image":"一段朽木上趴着一只黑亮的甲虫，背上两片硬壳合得严丝合缝，像一扇关紧的柜门","scene":"林子里倒下的树干被雨泡软了，树皮下有许多细小的通道。 A beetle worked its way along the fallen log, its hard wing cases catching the light.","sceneCN":"这里 beetle 指「甲虫」（第 1 个义项：前翅硬化为鞘、覆盖后翅的昆虫）；句意为一只甲虫沿着倒木爬行，坚硬的鞘翅反着光。","pos":[{"tag":"n.","zh":"甲虫；鞘翅目昆虫"},{"tag":"v.","zh":"（口语）匆匆地走；小跑"}],"collocations":[{"phrase":"dung beetle","zh":"蜣螂；屎壳郎"},{"phrase":"bark beetle","zh":"树皮甲虫（小蠹）"},{"phrase":"stag beetle","zh":"锹甲"},{"phrase":"beetle species","zh":"甲虫物种"},{"phrase":"beetle wing case","zh":"甲虫鞘翅"},{"phrase":"beetle larva","zh":"甲虫幼虫"}],"forms":[{"label":"原形","form":"beetle"},{"label":"复数","form":"beetles"},{"label":"三单（动词）","form":"beetles"},{"label":"过去式","form":"beetled"},{"label":"现在分词","form":"beetling"},{"label":"同根名词（小甲虫）","form":"beetle larva"}],"derivatives":[{"word":"beetles","pos":"n.","zh":"甲虫（复数）"},{"word":"dung beetle","pos":"n.","zh":"蜣螂"},{"word":"beetle-browed","pos":"adj.","zh":"眉骨突出、眉头紧锁的（另一词源）"},{"word":"bark beetle","pos":"n.","zh":"树皮甲虫"},{"word":"beetling","pos":"adj.","zh":"悬垂突出的（另一词源）"}],"senses":[{"no":"01","title":"The insect with hard wing cases","titleCN":"前翅硬化为鞘的昆虫","definition":"an insect of the order Coleoptera, whose front wings form hard cases protecting the folded hind wings","definitionCN":"鞘翅目的昆虫，前翅变成硬壳以保护折叠的后翅","example":"A beetle worked its way along the fallen log.","exampleCN":"一只甲虫沿着倒木爬行。","why":"the hardened wing case is the single feature that defines the group, so the word names the animal by its housing.","whyCN":"硬化的鞘翅是定义这个类群的单一特征，因此这个词以它的「外壳」命名动物。"},{"no":"02","title":"The whole order as a category","titleCN":"作为类目的整个鞘翅目","definition":"one of the largest orders of insects, treated as a group in counts, keys and collections","definitionCN":"昆虫中最大的目之一，在计数、检索表与收藏中作为一个群处理","example":"Beetles make up a quarter of all known animal species.","exampleCN":"甲虫占已知动物物种的四分之一。","why":"once the group is counted, the plural stands for the category rather than for individual animals.","whyCN":"一旦把该群用于计数，复数就代表类目，而不是个别动物。"},{"no":"03","title":"A single named kind","titleCN":"某一具名的种类","definition":"a species or family identified by a qualifier, such as stag, bark or dung beetle","definitionCN":"由限定语指明的种或科，如锹甲、树皮甲虫、蜣螂","example":"The stag beetle male carries enormous jaws.","exampleCN":"锹甲的雄性带着巨大的大颚。","why":"common names for kinds are made by putting a modifier before the general word.","whyCN":"各类的俗名是在通名之前加修饰语构成的。"},{"no":"04","title":"A pest of timber and stored goods","titleCN":"危害木材与储物的害虫","definition":"a species whose larvae bore into wood, grain or flour and cause economic loss","definitionCN":"幼虫钻入木材、谷物或面粉并造成经济损失的物种","example":"Bark beetles killed the spruce along the valley.","exampleCN":"树皮甲虫杀死了谷地一路的云杉。","why":"an economic role singles out those species whose boring does visible damage.","whyCN":"经济角色挑出那些钻孔造成可见损害的物种。"},{"no":"05","title":"A recycler of dung and carrion","titleCN":"粪便与腐尸的回收者","definition":"a species that buries or consumes dung, carcasses and dead plant matter","definitionCN":"掩埋或取食粪便、尸体与枯死植物的物种","example":"Dung beetles bury waste faster than any machine.","exampleCN":"蜣螂埋粪的速度快过任何机器。","why":"ecology names the function rather than the anatomy, so the same word carries a service meaning.","whyCN":"生态学命名功能而非解剖结构，因此同一个词带有「服务」义。"},{"no":"06","title":"A laboratory model organism","titleCN":"实验室的模式生物","definition":"a species reared under controlled conditions for genetic or physiological research","definitionCN":"在受控条件下饲养、用于遗传或生理研究的物种","example":"The flour beetle is cheap to keep and quick to breed.","exampleCN":"面粉甲虫饲养便宜、繁殖快。","why":"a well-known animal becomes a research system, and its name stands for the system.","whyCN":"一种熟悉的动物成为研究体系，其名称代表这个体系。"},{"no":"07","title":"An object of collection and display","titleCN":"被收藏与陈列的对象","definition":"the pinned specimen itself, valued for pattern, colour or rarity","definitionCN":"被插针固定的标本本身，因花纹、颜色或稀有而受重视","example":"The beetle in the case had been collected in 1889.","exampleCN":"标本盒里那只甲虫是 1889 年采到的。","why":"collectors speak of the specimen by the animal's name, so the word can mean the pinned object.","whyCN":"收藏者以动物名指称标本，因此这个词也可指插针的物件。"},{"no":"08","title":"To hurry along, in informal British use","titleCN":"口语（英式）：匆匆赶路","definition":"informal, to move quickly with short hurried steps","definitionCN":"口语，指迈着短促急步快速移动","example":"She beetled off to catch the last bus.","exampleCN":"她匆匆赶去搭末班车。","why":"the verb is often linked to the insect's scuttling walk, though a separate origin has also been suggested, so the link is plausible rather than certain.","whyCN":"这个动词常与昆虫急促的爬行相联系，但也有人提出另有来源，因此这一联系只是可能而非确定。"}],"etymology":{"intro":{"en":"Beetle for the insect goes back to Old English bitela, a derivative of the verb bitan 'to bite'; a separate beetle names a wooden mallet.","cn":"指昆虫的 beetle 可追溯到古英语 bitela，是动词 bitan「咬」的派生词；另有同形的 beetle 指木槌，来源不同。"},"items":[{"era":"OLD ENGLISH BITELA","en":"Bitela was a small biting creature, formed from bitan 'to bite' with a diminutive ending, and it named beetles.","cn":"bitela 指会咬的小生物，由 bitan「咬」加指小词尾构成，用来指甲虫。"},{"era":"GERMANIC RELATIVES","en":"German Käfer and Dutch kever are different formations, but the English word belongs to the same Germanic world of biting names.","cn":"德语 Käfer 与荷兰语 kever 是不同构词，但英语这个词属于同一套日耳曼「咬」的命名传统。"},{"era":"THE OTHER BEETLE","en":"A homograph beetle, from Old English bietel, means a heavy wooden mallet; it explains beetle-browed and beetling cliffs, not the insect.","cn":"同形的另一个 beetle 出自古英语 bietel，指沉重的木槌；它解释 beetle-browed 与 beetling cliffs，与昆虫无关。"},{"era":"SCIENTIFIC ORDER","en":"Coleoptera, from Greek koleos 'sheath' and pteron 'wing', became the order name for beetles in the eighteenth century.","cn":"Coleoptera 由希腊 koleos「鞘」与 pteron「翅」构成，18 世纪成为甲虫的目名。"},{"era":"VERB USE","en":"The verb beetle, to scuttle, is recorded from the sixteenth century with an uncertain origin.","cn":"动词 beetle「急走」自 16 世纪有记录，来源不确定。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (verb origin): whether the scuttling verb comes from the insect or from another source is unresolved; the insect noun itself is clear.","cn":"来源不确定（动词来源）：急走动词是否来自昆虫或另有来源尚无定论；昆虫名词本身是清楚的。"}]},"similar":{"note":{"en":"Group one separates beetle from insects it is mistaken for; group two separates the insect word from its homograph and from related categories.","cn":"第一组区分 beetle 与易被误认的昆虫；第二组区分这个昆虫词与同形词及相关类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bug","ipa":"/bʌɡ/","tag":"wider and narrower","definition":"Everyday for any small crawling insect; technically only the true bugs, which have piercing mouthparts, so a beetle is not a bug.","definitionCN":"日常泛指小爬虫；严格只指口器刺吸的半翅目，因此甲虫不是 bug。"},{"word":"weevil","ipa":"/ˈwiːvl/","tag":"a beetle family","definition":"A weevil is a beetle with an elongated snout; it is one family inside Coleoptera, not a separate kind of animal.","definitionCN":"象甲是带长吻的甲虫，属鞘翅目中的一个科，并非另一类动物。"},{"word":"cockroach","ipa":"/ˈkɒkrəʊtʃ/","tag":"leathery wings","definition":"A cockroach has leathery forewings that overlap rather than hard cases meeting in a line; it is not a beetle.","definitionCN":"蟑螂前翅革质交叠，不像甲虫硬鞘沿中线合拢；它不是甲虫。"},{"word":"beetle-browed","ipa":"/ˈbiːtl braʊd/","tag":"the homograph","definition":"Built on the mallet sense of beetle, meaning heavy projecting brows; it has nothing to do with insects.","definitionCN":"建在 beetle「木槌」义上，指眉骨重而突出；与昆虫无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"insect","ipa":"/ˈɪnsekt/","tag":"the class","definition":"The whole six-legged class; beetle is the largest order within it.","definitionCN":"整个六足纲；甲虫是其中最大的目。"},{"word":"arthropod","ipa":"/ˈɑːθrəpɒd/","tag":"the phylum","definition":"The jointed-legged phylum that contains beetles along with spiders and crabs.","definitionCN":"具关节足的整个门，甲虫与蜘蛛、蟹都在其中。"},{"word":"grub","ipa":"/ɡrʌb/","tag":"the larva","definition":"A grub is the thick-bodied larva of a beetle; the adult is the beetle itself.","definitionCN":"grub 是甲虫粗壮身体的幼虫；成虫才是 beetle。"},{"word":"scuttle","ipa":"/ˈskʌtl/","tag":"the motion","definition":"To scuttle is to run with short quick steps; it is the neutral equivalent of the informal verb beetle.","definitionCN":"scuttle 指迈短促快步跑；它是口语动词 beetle 的中性对应词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Old English derivation, real family names and the homograph warning.","cn":"正常联想：真实古英语派生、真实科名与同形词警示。"},"normal":[{"en":"Old English bitela comes from bitan 'to bite', so beetle once meant the biting little one.","cn":"古英语 bitela 出自 bitan「咬」，因此 beetle 原意是「会咬的小东西」。"},{"en":"Greek koleos 'sheath' plus pteron 'wing' gives Coleoptera, the beetle order.","cn":"希腊 koleos「鞘」加 pteron「翅」构成 Coleoptera，即甲虫目。"},{"en":"Fixed phrases: dung beetle, bark beetle, stag beetle.","cn":"固定搭配：蜣螂、树皮甲虫、锹甲。"},{"en":"Do not mix the insect with the mallet homograph behind beetle-browed.","cn":"勿把昆虫与 beetle-browed 背后那个「木槌」同形词混为一谈。"},{"en":"The larva of a beetle is usually called a grub.","cn":"甲虫的幼虫通常叫 grub。"}],"abstract":[{"en":"Picture two cupboard doors shut over folded cloth inside.","cn":"想象两扇柜门合起，里面是折好的布。"},{"en":"Picture a small body that can survive being stepped on.","cn":"想象一具小身体，被踩一脚也还能活。"},{"en":"Picture a walk so hurried it looks like scuttling.","cn":"想象一种急到像在窜的走法。"}]},"examples":[{"en":"Beetles were the first animals to be used in this kind of experiment.","cn":"甲虫是最早被用于这类实验的动物。"},{"en":"The log was riddled with beetle galleries under the bark.","cn":"树皮下的木头被甲虫的虫道蛀得满是孔。"},{"en":"He beetled across the yard before the rain started.","cn":"雨还没下，他就匆匆穿过院子。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「beetle」——背上两片硬壳像柜门一样合上 → 甲虫","word":"beetle"},"root":"古英语 bitela「甲虫」，由 bitan「咬」加指小词尾构成；另有同形词 beetle 出自古英语 bietel「木槌」，二者不同源。动词「急走」来源不确定。","sensesIntro":{"en":"Eight senses follow one hard case: an insect folds its wings under two shutters, and the word then names the order, a species, a timber pest, a waste recycler, a laboratory animal, a pinned specimen, and finally a hurried walk.","cn":"八个义项沿一副硬壳展开：昆虫把翅折在两扇「柜门」下；词语随后指整个目、某一物种、木材害虫、废物回收者、实验室动物、插针标本，最后指一种匆忙的走法。"},"semanticMap":{"core":{"en":"CORE IMAGE: two hard shutters meeting in a straight line over folded wings.","cn":"核心意象：两片硬壳沿一条直线合拢，盖住折叠的翅。"},"chain":["HARD WING CASE","THE BEETLE ORDER","A NAMED SPECIES","BORING PEST","PINNED SPECIMEN","HURRIED WALK"],"branches":[{"senses":"S1 · S2","en":"BODY AND ORDER: the shutters of one beetle, then the largest order of insects.","cn":"身体与目：一只甲虫的鞘翅，然后是昆虫中最大的目。"},{"senses":"S3","en":"NAMED KIND: stag, bark and dung beetles are modifiers on one word.","cn":"具名种类：锹甲、树皮甲虫、蜣螂都是同一词上的修饰语。"},{"senses":"S4 · S5","en":"TWO ECONOMIES: one species destroys timber, another removes waste.","cn":"两种经济：一种毁木材，另一种清废物。"},{"senses":"S6 · S7","en":"HUMAN USES: a research system and a collected object.","cn":"人的用途：一个研究体系与一件被收藏之物。"},{"senses":"S8","en":"THE WALK: the scuttle borrows the insect's hurried gait, though the origin is uncertain.","cn":"走法：急走借用了昆虫仓促的步态，尽管来源不确定。"}]},"affixes":{"intro":{"en":"Beetle is a native noun formed with an old diminutive ending; the modern word is monomorphemic to most speakers.","cn":"beetle 是本族名词，由古老的指小词尾构成；对多数使用者而言现代词已不可再分。"},"latinIntro":{"en":"Latin contributes only the scientific order name Coleoptera, from Greek; beetle itself has no Latin root.","cn":"拉丁语只提供学术目名 Coleoptera（本身出自希腊语）；beetle 自身不含拉丁词根。"},"items":[{"word":"bitan","structure":"bitan (Old English verb, 'to bite')","meaning":"to bite","meaningCN":"咬","example":"The name began as 'the biting one'.","exampleCN":"这个名字起初是「会咬的那个」。"},{"word":"-ela","structure":"-ela (Old English diminutive ending)","meaning":"small one","meaningCN":"小者","example":"The ending made the name a small creature word.","exampleCN":"这个词尾使名词成为「小生物」的说法。"},{"word":"beetle","structure":"bitela > beetle (noun)","meaning":"the hard-winged insect","meaningCN":"具硬翅的昆虫","example":"The beetle closed its wing cases.","exampleCN":"甲虫合上了鞘翅。"},{"word":"-s","structure":"beetles = beetle + -s (plural)","meaning":"more than one","meaningCN":"多只","example":"Beetles filled the trap.","exampleCN":"诱捕器里满是甲虫。"},{"word":"dung beetle","structure":"dung + beetle (compound)","meaning":"a beetle that uses dung","meaningCN":"利用粪便的甲虫","example":"Dung beetles roll the dung away.","exampleCN":"蜣螂把粪滚走。"},{"word":"bark beetle","structure":"bark + beetle (compound)","meaning":"a beetle living under bark","meaningCN":"生活在树皮下的甲虫","example":"Bark beetles spread in warm winters.","exampleCN":"暖冬里树皮甲虫扩散。"},{"word":"stag beetle","structure":"stag + beetle (compound)","meaning":"a beetle with antler-like jaws","meaningCN":"具鹿角状大颚的甲虫","example":"The stag beetle is protected here.","exampleCN":"锹甲在此受保护。"},{"word":"beetle-browed","structure":"beetle (mallet) + brow + -ed","meaning":"with heavy projecting brows","meaningCN":"眉骨重而突出的","example":"Beetle-browed comes from the mallet, not the insect.","exampleCN":"beetle-browed 出自木槌而非昆虫。"},{"word":"beetling","structure":"beetle (mallet) + -ing","meaning":"overhanging, projecting","meaningCN":"悬垂突出的","example":"A beetling cliff hung over the path.","exampleCN":"一片突出的崖壁悬在路上。"}],"latinEntries":[{"word":"coleoptera","structure":"Greek koleos 'sheath' + pteron 'wing' (order name)","meaning":"sheath-winged insects","meaningCN":"鞘翅昆虫"},{"word":"scarabaeus","structure":"scarabaeus, scarabaei (m., second declension)","meaning":"a dung beetle, scarab","meaningCN":"蜣螂；圣甲虫"},{"word":"larva","structure":"larva, larvae (f., first declension)","meaning":"a mask, a ghost; later a young stage","meaningCN":"面具、鬼；后指幼体"}]}},{"word":"ant","ipa_uk":"/ænt/","ipa_us":"/ænt/","definition_zh":"蚂蚁；蚁类；（喻）勤劳的人；成群的小人物","definition_en":"a small social insect that lives in colonies, usually with wingless workers, and is related to bees and wasps","core_image":"一条从地缝里出来的细线，几十只黑点在糖粒与洞口之间来回，每只都沿着上一位留下的气味走","scene":"厨房地板上落了一小块饼干屑，不到十分钟就有东西围了上来。 An ant followed the scent trail back to the crumb under the cupboard.","sceneCN":"这里 ant 指「蚂蚁」（第 1 个义项：生活在群体中、工蚁无翅的小型社会性昆虫）；句意为一只蚂蚁沿着气味路线回到柜下的碎屑。","pos":[{"tag":"n.","zh":"蚂蚁；蚁类"}],"collocations":[{"phrase":"worker ant","zh":"工蚁"},{"phrase":"queen ant","zh":"蚁后"},{"phrase":"ant colony","zh":"蚁群；蚁巢"},{"phrase":"fire ant","zh":"红火蚁"},{"phrase":"ant nest","zh":"蚁巢"},{"phrase":"ant trail","zh":"蚁道"},{"phrase":"ants in one's pants","zh":"坐立不安"}],"forms":[{"label":"原形","form":"ant"},{"label":"复数","form":"ants"},{"label":"指小形式","form":"antlet"},{"label":"同根形容词","form":"formic"},{"label":"学科名（蚁学）","form":"myrmecology"}],"derivatives":[{"word":"ants","pos":"n.","zh":"蚂蚁（复数）"},{"word":"antlike","pos":"adj.","zh":"像蚂蚁的"},{"word":"antbird","pos":"n.","zh":"蚁鸟（随蚁群觅食的鸟）"},{"word":"antlion","pos":"n.","zh":"蚁狮（脉翅目幼虫）"},{"word":"formicary","pos":"n.","zh":"蚁巢"}],"senses":[{"no":"01","title":"The small colony-living insect","titleCN":"群居的小型昆虫","definition":"a small hymenopteran insect living in organised colonies, with wingless workers and usually a winged queen","definitionCN":"生活在有组织群体中的小型膜翅目昆虫，工蚁无翅，通常有带翅的蚁后","example":"An ant followed the scent trail back to the crumb.","exampleCN":"一只蚂蚁沿着气味路线回到碎屑处。","why":"the core sense is the animal, and the word has meant it since Old English with almost no semantic drift.","whyCN":"核心义就是这种动物，自上古英语以来词义几乎未变。"},{"no":"02","title":"The colony as a unit","titleCN":"作为一个单位的蚁群","definition":"the colony itself, often treated as a single superorganism with division of labour","definitionCN":"群体本身，常被看作分工的单一超个体","example":"The whole ant moved as one when the stone was lifted.","exampleCN":"石头被掀开时，整窝蚁像一体般动起来。","why":"individuals are rarely counted, so the singular often stands for the colony by metonymy.","whyCN":"很少逐个计数，因此单数常以转喻指整个群体。"},{"no":"03","title":"A named species or caste","titleCN":"具名的种类或品级","definition":"a particular species or caste identified by a qualifier, such as fire ant, worker ant or queen ant","definitionCN":"由限定语指明的具体物种或品级，如红火蚁、工蚁、蚁后","example":"The fire ant builds mounds in open ground.","exampleCN":"红火蚁在空地筑起蚁丘。","why":"species and castes are named by adding a modifier to the general word rather than by new nouns.","whyCN":"物种与品级靠给通名加修饰语命名，而不另造名词。"},{"no":"04","title":"A household and garden nuisance","titleCN":"家中与园中的麻烦","definition":"ants regarded as pests that enter buildings or farm aphids","definitionCN":"进入建筑或饲养蚜虫而被视为害虫的蚂蚁","example":"Ants found the sugar bowl within a day.","exampleCN":"蚂蚁一天之内就找到了糖罐。","why":"a practical judgement narrows the word to the species that inconvenience people.","whyCN":"实用的判断把词义收窄到给人带来不便的物种。"},{"no":"05","title":"An ecological mover of soil and seeds","titleCN":"翻动土壤、搬运种子的生态角色","definition":"the role of ants in turning soil, dispersing seeds and protecting plants","definitionCN":"蚂蚁在翻土、传播种子与保护植物方面的角色","example":"Ants carried a third of the seeds into their nests.","exampleCN":"蚂蚁把三分之一的种子搬进了巢里。","why":"ecology speaks of the group and its work, so the plural names a process rather than animals.","whyCN":"生态学谈的是群体与其工作，因此复数命名的是一个过程而非动物。"},{"no":"06","title":"A model of collective problem-solving","titleCN":"集体解题的模型","definition":"the colony used as an inspiration for algorithms and distributed systems","definitionCN":"以蚁群为灵感来源的算法与分布式系统","example":"Delivery routes are planned by an ant colony optimization.","exampleCN":"配送路线用蚁群优化算法规划。","why":"the insect's trail-laying and following becomes a computing metaphor, keeping only the coordination.","whyCN":"昆虫留下与跟随气味的做法成为计算比喻，只保留协调的一面。"},{"no":"07","title":"The industrious worker of fables","titleCN":"寓言里勤劳的工人","definition":"the figure of tireless industry, especially in the fable of the ant and the grasshopper","definitionCN":"不知疲倦劳作的形象，尤见于蚂蚁与蚱蜢的寓言","example":"The story sets the ant against the grasshopper every summer.","exampleCN":"这个故事每年夏天都把蚂蚁与蚱蜢对立起来。","why":"a fable fixes a trait to an animal, and the trait then becomes available as a metaphor for people.","whyCN":"寓言把一种品性固定到动物身上，这种品性随后可用作对人的比喻。"},{"no":"08","title":"Restless fidgeting, in the fixed idiom","titleCN":"坐立不安，见于固定习语","definition":"in the idiom ants in one's pants, a state of restless impatience","definitionCN":"在习语 ants in one's pants 中，指坐立难耐的状态","example":"The children had ants in their pants before the trip.","exampleCN":"出发前孩子们坐立不安。","why":"the idiom imagines crawling insects under clothing, so restlessness is described by a physical itch.","whyCN":"这个习语想象衣下有小虫在爬，因此把坐立不安说成一种身体上的痒。"}],"etymology":{"intro":{"en":"Ant is a native English word recorded in Old English as aemete, later shortened; its Germanic relatives all mean the ant.","cn":"ant 是本族英语词，古英语作 aemete，后世缩短；其日耳曼同族词都指蚂蚁。"},"items":[{"era":"OLD ENGLISH AEMETE","en":"The Old English form was aemete, and the modern ant is a worn-down version of it, the middle syllable lost.","cn":"古英语形式为 aemete，现代 ant 是其磨损后的形式，中间音节脱落。"},{"era":"GERMANIC COGNATES","en":"German Ameise and Dutch mier come from the same Germanic word, which literally seems to mean 'the biter-off' or 'the cutter'.","cn":"德语 Ameise 与荷兰语 mier 出自同一个日耳曼词，字面似指「咬断者」或「切割者」。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the pre-Germanic origin is unresolved; the usual reading as 'cutting insect' depends on a reconstructed root, so it is an interpretation rather than a demonstrated fact.","cn":"来源不确定（词根）：日耳曼语之前的来源无定论；常把它读作「切割的昆虫」依赖一个重构词根，因此属解释而非已证事实。"},{"era":"SCIENTIFIC NAMES","en":"The family name Formicidae and the adjective formic come from Latin formica, a separate word for the same animal.","cn":"科名 Formicidae 与形容词 formic 来自拉丁 formica，是同一动物的另一个词。"},{"era":"FABLE AND PROVERB","en":"The industrious ant of Aesop's fable fixed the insect as a figure of thrift and labour in European languages.","cn":"伊索寓言中勤劳的蚂蚁把这种昆虫固定为节俭与劳作的象征，通行于欧洲诸语。"},{"era":"TECHNICAL METAPHOR","en":"In the late twentieth century ant colonies supplied the model for optimization algorithms and distributed control.","cn":"20 世纪后期，蚁群为优化算法与分布式控制提供了模型。"}]},"similar":{"note":{"en":"Group one separates ant from the insects it is confused with; group two separates the word from its figurative and technical uses.","cn":"第一组区分 ant 与易混昆虫；第二组区分这个词与其比喻、技术用法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"termite","ipa":"/ˈtɜːmaɪt/","tag":"often mistaken for an ant","definition":"A termite is a separate order, related to cockroaches; its workers are pale and soft-bodied, and it eats wood.","definitionCN":"白蚁是另一个目，与蟑螂近缘；工蚁苍白软体，且蛀食木材。"},{"word":"wasp","ipa":"/wɒsp/","tag":"same order, different body","definition":"A wasp is a close relative with a narrow waist and usually wings; ants are the wingless social members of the same order.","definitionCN":"黄蜂是近亲，腰细且通常有翅；蚂蚁是同一目中的无翅社会成员。"},{"word":"bee","ipa":"/biː/","tag":"pollen, not prey","definition":"A bee collects nectar and pollen and is usually fuzzy; ants are mostly predators and scavengers.","definitionCN":"蜜蜂采集花蜜花粉，通常多毛；蚂蚁多为捕食与食腐。"},{"word":"antbird","ipa":"/ˈæntbɜːd/","tag":"a bird","definition":"Antbird is a bird that follows army ants; the compound contains ant but names a vertebrate.","definitionCN":"antbird 是跟随行军蚁的鸟；复合词含 ant 却指脊椎动物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"insect","ipa":"/ˈɪnsekt/","tag":"the class","definition":"The whole six-legged class; the ant is one family within it.","definitionCN":"整个六足纲；蚂蚁是其中一个科。"},{"word":"colony","ipa":"/kəˈləʊni/","tag":"the organisation","definition":"Colony names the social unit; ant names the animal that forms it.","definitionCN":"colony 命名社会单位；ant 命名组成它的动物。"},{"word":"swarm","ipa":"/swɔːm/","tag":"a crowd in motion","definition":"A swarm is a mass of moving insects; ants on a trail form a line, not a swarm.","definitionCN":"swarm 是移动的虫群；蚁道上的蚂蚁成线而非成团。"},{"word":"formicary","ipa":"/ˈfɔːmɪkəri/","tag":"the nest","definition":"Formicary is the learned word for an ant nest, built on Latin formica.","definitionCN":"formicary 是蚁巢的学术词，建在拉丁 formica 上。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Germanic history, real castes and real idioms.","cn":"正常联想：真实日耳曼历史、真实品级与真实习语。"},"normal":[{"en":"Old English aemete was worn down to ant, losing its middle syllable.","cn":"古英语 aemete 磨损成 ant，中间音节脱落。"},{"en":"German Ameise and Dutch mier are the surviving Germanic relatives.","cn":"德语 Ameise 与荷兰语 mier 是存留的日耳曼同族词。"},{"en":"Fixed phrases: worker ant, queen ant, ant colony, fire ant.","cn":"固定搭配：工蚁、蚁后、蚁群、红火蚁。"},{"en":"Latin formica gives the family name Formicidae and the adjective formic.","cn":"拉丁 formica 提供科名 Formicidae 与形容词 formic。"},{"en":"The idiom ants in one's pants means restless impatience.","cn":"习语 ants in one's pants 意为坐立不安。"}],"abstract":[{"en":"Picture dozens of dots walking a line nobody drew.","cn":"想象几十个点走在一条没人画过的线上。"},{"en":"Picture a whole city that fits under a stone.","cn":"想象一座整城，藏在石头下面。"},{"en":"Picture a worker who never looks up from the task.","cn":"想象一个从不抬头看别处的工人。"}]},"examples":[{"en":"Ants farm aphids for the honeydew they produce.","cn":"蚂蚁饲养蚜虫，取食其分泌的蜜露。"},{"en":"A single ant colony can contain millions of workers.","cn":"一个蚁群可含数百万只工蚁。"},{"en":"The children had ants in their pants all morning.","cn":"孩子们一整个上午都坐立不安。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ant」——短短一个音节，正像一只小虫的名字 → 蚂蚁","word":"ant"},"root":"古英语 aemete「蚂蚁」，现代形式为磨损缩短；与德语 Ameise、荷兰语 mier 同出日耳曼词，字面或指「咬断、切割者」，但依赖重构词根，来源不确定。","sensesIntro":{"en":"Eight senses follow one trail: a small insect walks a scent line, and the word then names the colony, a caste, a household nuisance, a soil mover, a computing model, a fable's worker, and finally a physical itch of impatience.","cn":"八个义项沿一条路线展开：小昆虫沿着气味线走；词语随后指群体、品级、家中麻烦、翻土者、计算模型、寓言中的工人，最后指一种坐不住的痒。"},"semanticMap":{"core":{"en":"CORE IMAGE: dozens of black dots walking one invisible line between food and hole.","cn":"核心意象：几十个黑点沿一条看不见的线，在食物与洞口之间往返。"},"chain":["SMALL WORKER","THE COLONY","A CASTE OR SPECIES","HOUSEHOLD PEST","MODEL FOR ALGORITHMS","FABLE OF INDUSTRY"],"branches":[{"senses":"S1 · S2","en":"ONE AND MANY: the animal and the superorganism it belongs to.","cn":"一与多：动物本身与它所属的超个体。"},{"senses":"S3","en":"NAMED ROLES: castes and species are qualifiers on one word.","cn":"具名角色：品级与物种都是同一词的限定语。"},{"senses":"S4 · S5","en":"TWO JUDGEMENTS: a nuisance indoors, a service outdoors.","cn":"两种判断：室内是麻烦，野外是服务。"},{"senses":"S6 · S7","en":"BORROWED BY PEOPLE: algorithms copy the trail, fables copy the labour.","cn":"被人借用：算法复制路线，寓言复制劳作。"},{"senses":"S8","en":"CRAWLING SENSATION: restlessness is felt as insects under cloth.","cn":"爬动的感觉：坐立不安被感受为衣下的小虫。"}]},"affixes":{"intro":{"en":"Ant is a single worn-down Germanic word; compounds and Greek-based technical names do the rest of the work.","cn":"ant 是单个磨损的日耳曼词；其余工作由复合词与希腊式术语完成。"},"latinIntro":{"en":"Latin formica is the separate word for ant that supplies formic, formicary and the family name Formicidae.","cn":"拉丁 formica 是蚂蚁的另一个词，提供 formic、formicary 与科名 Formicidae。"},"items":[{"word":"aemete","structure":"aemete (Old English form)","meaning":"ant","meaningCN":"蚂蚁","example":"The modern word is a worn-down aemete.","exampleCN":"现代形式是 aemete 磨损而来。"},{"word":"ant","structure":"ant (modern noun)","meaning":"the social insect","meaningCN":"社会性昆虫","example":"An ant crossed the page.","exampleCN":"一只蚂蚁爬过书页。"},{"word":"-s","structure":"ants = ant + -s (plural)","meaning":"many ants","meaningCN":"许多蚂蚁","example":"Ants covered the step.","exampleCN":"台阶上爬满蚂蚁。"},{"word":"-like","structure":"antlike = ant + -like","meaning":"resembling an ant","meaningCN":"似蚂蚁的","example":"The robot has an antlike gait.","exampleCN":"这个机器人步态似蚁。"},{"word":"-bird","structure":"antbird = ant + bird","meaning":"a bird that follows ants","meaningCN":"跟随蚁群的鸟","example":"The antbird watches the raid.","exampleCN":"蚁鸟盯着蚁群的行进。"},{"word":"-lion","structure":"antlion = ant + lion","meaning":"a larva that traps ants","meaningCN":"捕蚁的幼虫","example":"The antlion waits under the sand.","exampleCN":"蚁狮在沙下等待。"},{"word":"formic","structure":"formica + -ic (adjective)","meaning":"of ants; also the acid ants spray","meaningCN":"蚂蚁的；也指蚁酸","example":"Formic acid takes its name from ants.","exampleCN":"蚁酸之名取自蚂蚁。"},{"word":"-ary","structure":"formicary = formica + -ary (place)","meaning":"an ant nest","meaningCN":"蚁巢","example":"The formicary was under the paving.","exampleCN":"蚁巢在铺地之下。"},{"word":"myrmecology","structure":"Greek myrmex 'ant' + -logia","meaning":"the study of ants","meaningCN":"蚁学","example":"Myrmecology is a branch of entomology.","exampleCN":"蚁学是昆虫学的一个分支。"}],"latinEntries":[{"word":"formica","structure":"formica, formicae (f., first declension)","meaning":"ant","meaningCN":"蚂蚁"},{"word":"formicarium","structure":"formicarium, formicarii (n., second declension)","meaning":"an ant nest or ant farm","meaningCN":"蚁巢；养蚁箱"},{"word":"myrmex","structure":"Greek myrmex, myrmekos (m., third declension)","meaning":"ant","meaningCN":"蚂蚁"}]}},{"word":"termite","ipa_uk":"/ˈtɜːmaɪt/","ipa_us":"/ˈtɜːrmaɪt/","definition_zh":"白蚁；（喻）从内部慢慢蛀空组织的人或事物","definition_en":"a pale, soft-bodied social insect that feeds on wood and lives in colonies with distinct castes","core_image":"一块外表完好的木板被撬开，里面是无数细小管道，像被谁用针一层层掏空，只剩一层薄壳","scene":"老房子的地板踩上去还是硬的，可撬开一角，底下已经全是细土一样的碎渣。 One termite is harmless, but a colony can hollow a beam without touching its surface.","sceneCN":"这里 termite 指「白蚁」（第 1 个义项：体色浅、体软、蛀食木材的群居昆虫）；句意为一只白蚁无害，但一个蚁群能在不碰表面的情况下把梁掏空。","pos":[{"tag":"n.","zh":"白蚁；白蚁类"}],"collocations":[{"phrase":"subterranean termite","zh":"地下白蚁"},{"phrase":"drywood termite","zh":"干木白蚁"},{"phrase":"termite colony","zh":"白蚁群"},{"phrase":"termite damage","zh":"白蚁造成的损坏"},{"phrase":"termite mound","zh":"白蚁丘"},{"phrase":"termite inspection","zh":"白蚁检查"},{"phrase":"termite treatment","zh":"白蚁防治"}],"forms":[{"label":"原形","form":"termite"},{"label":"复数","form":"termites"},{"label":"同根形容词（白蚁的）","form":"termitic"},{"label":"学科名（白蚁学）","form":"isopterology"},{"label":"旧称（白蚁）","form":"white ant"}],"derivatives":[{"word":"termites","pos":"n.","zh":"白蚁（复数）"},{"word":"termitic","pos":"adj.","zh":"白蚁的；由白蚁引起的"},{"word":"termitarium","pos":"n.","zh":"白蚁巢；白蚁丘"},{"word":"termiticide","pos":"n.","zh":"杀白蚁剂"},{"word":"white ant","pos":"n.","zh":"白蚁（旧称，实为误称）"}],"senses":[{"no":"01","title":"The pale wood-eating social insect","titleCN":"浅色、蛀食木材的群居昆虫","definition":"a soft-bodied, usually pale insect of the cockroach lineage that lives in colonies and feeds mainly on wood","definitionCN":"体软、通常色浅、属蟑螂谱系、群居并以木材为主食的昆虫","example":"One termite is harmless, but a colony can hollow a beam.","exampleCN":"一只白蚁无害，但一个蚁群能把梁掏空。","why":"the word names the animal, and the whole vocabulary of damage, mounds and castes is built outward from it.","whyCN":"这个词命名动物，关于损坏、蚁丘与品级的整套词汇都由它向外生长出来。"},{"no":"02","title":"The colony with its castes","titleCN":"有品级分工的群体","definition":"the organised society of workers, soldiers and reproductives living in one nest","definitionCN":"在同一巢中生活的工蚁、兵蚁与繁殖个体组成的有组织社会","example":"The termite colony was three metres deep and twenty years old.","exampleCN":"这个白蚁群深达三米，已有二十年。","why":"because individuals are almost never seen alone, the singular often stands for the whole society.","whyCN":"因为个体几乎从不单独出现，单数常代指整个社会。"},{"no":"03","title":"A named ecological type","titleCN":"具名的生态类型","definition":"a kind identified by habit, such as subterranean, drywood or mound-building termites","definitionCN":"按习性区分的类型，如地下白蚁、干木白蚁、筑丘白蚁","example":"Drywood termites need no contact with soil at all.","exampleCN":"干木白蚁完全不需要接触土壤。","why":"types are distinguished by where they live, so a qualifier carries the whole difference.","whyCN":"类型由栖息处区分，因此一个限定语承担了全部差别。"},{"no":"04","title":"A destroyer of timber in buildings","titleCN":"建筑木材的破坏者","definition":"the species regarded as a structural pest because it consumes wood from the inside","definitionCN":"因从内部吃空木材而被视为结构害虫的物种","example":"Termite damage went unnoticed until the floor sagged.","exampleCN":"白蚁的损坏直到地板下沉才被发现。","why":"the damage is described by its agent because the insect leaves a hollow shell rather than a visible hole.","whyCN":"损坏由施害者来描述，因为昆虫留下的是空壳而不是明显的洞。"},{"no":"05","title":"A decomposer of dead wood","titleCN":"枯木的分解者","definition":"the ecological role of breaking down fallen timber and returning nutrients to the soil","definitionCN":"分解倒木、把养分归还土壤的生态角色","example":"Termites clear dead wood faster than fungi in dry forests.","exampleCN":"在干燥森林里，白蚁分解枯木比真菌更快。","why":"the same activity that ruins a house recycles a forest, so the word carries both judgements.","whyCN":"毁屋与还林是同一种活动，因此这个词同时承载两种判断。"},{"no":"06","title":"A subject for symbiosis research","titleCN":"共生研究的对象","definition":"the insect as a host whose gut microbes digest wood, studied as a model of symbiosis","definitionCN":"肠道微生物帮它消化木材，因而作为共生模型被研究的昆虫","example":"The termite depends on microbes it passes to its young.","exampleCN":"白蚁依赖它传给后代的微生物。","why":"a striking biological dependency makes the animal a research system, and the name stands for the system.","whyCN":"一种显著的生物依赖使这种动物成为研究体系，其名称代表这个体系。"},{"no":"07","title":"A builder of ventilated mounds","titleCN":"建造通风蚁丘的建筑者","definition":"the mound-building species whose structures regulate heat and gas exchange","definitionCN":"所筑结构能调节热量与气体交换的筑丘物种","example":"The termite mound keeps a steady temperature through the day.","exampleCN":"白蚁丘昼夜保持稳定温度。","why":"architecture is attributed to a builder, so the insect's name travels to the structure it makes.","whyCN":"建筑被归给建造者，因此昆虫之名也移向它所造的结构。"},{"no":"08","title":"Figurative: something hollowing from within","titleCN":"比喻：从内部慢慢蛀空","definition":"figurative, a person or institution that undermines a group secretly and gradually","definitionCN":"比喻用法，指暗中、逐步蛀空某个群体的人或机构","example":"The report called the smuggling network a termite in the customs service.","exampleCN":"报告把走私网络称作海关内部的白蚁。","why":"the metaphor keeps only the hidden, internal, gradual hollowing, which is exactly what the insect does.","whyCN":"比喻只保留隐蔽、内部、渐进的掏空，而这正是这种昆虫所做的事。"}],"etymology":{"intro":{"en":"Termite is a late eighteenth-century learned word from Latin termes, the name for a woodworm; its earlier English name was the misleading white ant.","cn":"termite 是 18 世纪后期的学术词，出自拉丁 termes「木蠹虫」；其较早英语名是易致误解的 white ant。"},"items":[{"era":"LATIN TERMES","en":"Latin termes named a woodworm or a gnawing insect, and English naturalists revived it for the tropical wood-eating insect.","cn":"拉丁 termes 指木蠹虫或蛀咬的昆虫，英语博物学家把它复活用于热带蛀木昆虫。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root): the origin of Latin termes itself is unresolved; a link to a verb for gnawing has been suggested, but the form given for it is reconstructed.","cn":"来源不确定（词根）：拉丁 termes 本身的来源无定论；与某个表示「啃咬」的动词的联系属提议，且所给形式为重构。"},{"era":"WHITE ANT","en":"The older English name white ant treated the insect as a pale ant, a mistake that modern classification has corrected.","cn":"较早的英语名 white ant 把它当作浅色的蚂蚁，这一错误已被现代分类纠正。"},{"era":"CLASSIFICATION","en":"Termites are now placed with cockroaches rather than with ants, a result of twentieth-century anatomical and molecular work.","cn":"白蚁现被归入蟑螂一类而非蚂蚁，这是 20 世纪解剖与分子研究的结果。"},{"era":"ECONOMIC SENSE","en":"As timber construction spread, the word became a household word for structural damage and for the inspection trade.","cn":"随着木结构建筑普及，这个词成为关于结构损坏与检查行业的日常词。"},{"era":"FIGURATIVE USE","en":"The image of hidden internal hollowing produced the political metaphor of a termite inside an institution.","cn":"隐蔽内部掏空的意象产生了「机构内部白蚁」的政治比喻。"}]},"similar":{"note":{"en":"Group one separates termite from the insects it is historically confused with; group two separates the animal from its products and its metaphors.","cn":"第一组区分 termite 与其历史上易混的昆虫；第二组区分动物本身与其产物、比喻。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ant","ipa":"/ænt/","tag":"the older misnomer","definition":"The insect once called a white ant; ants are darker, have a narrow waist and belong to a different order.","definitionCN":"曾被叫作白蚁的昆虫；蚂蚁颜色更深、腰细，且属另一目。"},{"word":"white ant","ipa":"/ˈwaɪt ænt/","tag":"the outdated name","definition":"An old English name for the termite, still met in older books; the insect is neither white nor an ant.","definitionCN":"白蚁的旧英语名，仍见于旧书；它既不白也不是蚂蚁。"},{"word":"termitarium","ipa":"/ˌtɜːmɪˈteəriəm/","tag":"the structure","definition":"The nest or mound itself, not the insect; the -arium suffix marks a place.","definitionCN":"巢或丘本身，而非昆虫；-arium 后缀标记场所。"},{"word":"termiticide","ipa":"/ˌtɜːmɪˈtɪsaɪd/","tag":"the chemical","definition":"A product that kills termites, built with the -cide suffix of killing.","definitionCN":"杀白蚁的产品，由表「杀」的 -cide 后缀构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"woodworm","ipa":"/ˈwʊdwɜːm/","tag":"the old English sense","definition":"Woodworm names the larvae of wood-boring beetles; Latin termes covered similar gnawers before it was fixed to termites.","definitionCN":"woodworm 指蛀木甲虫的幼虫；拉丁 termes 在被固定指白蚁前也涵盖类似的蛀虫。"},{"word":"carpenter ant","ipa":"/ˈkɑːpəntə ænt/","tag":"hollows, does not eat","definition":"A carpenter ant excavates galleries in wood but does not eat it; a termite actually digests the wood.","definitionCN":"木匠蚁在木中挖道但不吃木；白蚁则真正消化木材。"},{"word":"borer","ipa":"/ˈbɔːrə/","tag":"the action, not the species","definition":"Borer names any animal that drills into wood or stems; termite names a particular social insect.","definitionCN":"borer 指任何钻入木材或茎的动物；termite 指特定的社会性昆虫。"},{"word":"decomposer","ipa":"/ˌdiːkəmˈpəʊzə/","tag":"the ecological function","definition":"Decomposer is a functional role in a food web; termite is the organism that fills it in dry forests.","definitionCN":"decomposer 是食物网中的功能角色；白蚁是在干燥森林中承担该角色的生物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin source, the real misnomer and real trade terms.","cn":"正常联想：真实拉丁来源、真实误称与真实行业用语。"},"normal":[{"en":"Latin termes meant a woodworm, and English took it for the tropical wood-eater.","cn":"拉丁 termes 指木蠹虫，英语用它指热带的蛀木者。"},{"en":"The old name white ant is a double mistake: not white, not an ant.","cn":"旧名 white ant 是双重错误：既不白，也不是蚂蚁。"},{"en":"Fixed phrases: termite damage, termite mound, termite inspection.","cn":"固定搭配：白蚁损坏、白蚁丘、白蚁检查。"},{"en":"Termites are now classified with cockroaches, not with ants.","cn":"白蚁现被归入蟑螂一类，而非蚂蚁。"},{"en":"Termites digest wood with microbes in their gut, a standard case of symbiosis.","cn":"白蚁靠肠道微生物消化木材，是共生的标准案例。"}],"abstract":[{"en":"Picture a beam that sounds solid when tapped and is dust inside.","cn":"想象一根梁，敲起来是实的，里面却是粉。"},{"en":"Picture a city of narrow corridors built without a single window.","cn":"想象一座全是窄走廊、没有一扇窗的城市。"},{"en":"Picture a flaw that eats an organisation while its reports look clean.","cn":"想象一个缺陷在吞噬机构，而报告看起来一切正常。"}]},"examples":[{"en":"Termites reached the sill through a mud tube built in the dark.","cn":"白蚁沿着在暗处筑成的泥管到达了门槛。"},{"en":"The mound was opened and the termites were gone within an hour.","cn":"蚁丘被打开后，白蚁一小时内就撤空了。"},{"en":"Inspectors look for termites before any sale of the house.","cn":"房屋出售前，检查人员会找白蚁。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ter（土）+ mite」——在土里做巢、把木头蛀成粉的虫 → 白蚁","word":"termite"},"root":"拉丁 termes「木蠹虫、蛀虫」，英语在 18 世纪后期借入指白蚁；拉丁词本身的更深来源不确定，与「啃咬」动词的联系仅为重构性提议。旧英语名 white ant 属误称。","sensesIntro":{"en":"Eight senses follow one hidden hollowing: a pale insect eats wood from inside, and the word then names the colony, a type, a structural pest, a decomposer, a symbiosis model, a mound builder, and finally a person who undermines from within.","cn":"八个义项沿一种隐蔽的掏空展开：浅色昆虫从内部吃木；词语随后指群体、类型、结构害虫、分解者、共生模型、筑丘者，最后指从内部蛀空的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beam that looks intact until the shell is lifted and only dust remains.","cn":"核心意象：一根看似完好的梁，撬开薄壳后只剩粉末。"},"chain":["EAT FROM INSIDE","THE COLONY","A NAMED TYPE","HOLLOW THE HOUSE","BUILD THE MOUND","UNDERMINE A GROUP"],"branches":[{"senses":"S1 · S2","en":"INSECT AND SOCIETY: one animal, then the caste system it never leaves.","cn":"昆虫与社会：一只动物，然后是它从不脱离的品级体系。"},{"senses":"S3","en":"HABIT TYPES: subterranean, drywood and mound builders are one word plus a qualifier.","cn":"习性命型：地下、干木、筑丘都是一个词加限定语。"},{"senses":"S4 · S5","en":"TWO VERDICTS: destroyer of a building, restorer of a forest.","cn":"两种裁断：建筑的破坏者，森林的恢复者。"},{"senses":"S6 · S7","en":"RESEARCH AND ARCHITECTURE: the gut microbes and the ventilated mound.","cn":"研究与建筑：肠道微生物与通风的蚁丘。"},{"senses":"S8","en":"HIDDEN CORROSION: the insect becomes an accusation about institutions.","cn":"隐蔽腐蚀：昆虫变成对机构的指控。"}]},"affixes":{"intro":{"en":"Termite is a learned Latin borrowing with no English prefix; its family is built with Latin and Greek suffixes.","cn":"termite 是拉丁学术借词，无英语前缀；其词族由拉丁与希腊后缀构成。"},"latinIntro":{"en":"Latin termes gives termite and termitarium; Greek isopteron 'equal wing' gives the old order name Isoptera.","cn":"拉丁 termes 提供 termite 与 termitarium；希腊 isopteron「等翅」提供旧目名 Isoptera。"},"items":[{"word":"termes","structure":"termes, termitis (m., third declension)","meaning":"woodworm, gnawing worm","meaningCN":"木蠹虫；蛀虫","example":"The Latin word named a wood-eater long before the tropics were studied.","exampleCN":"这个拉丁词早在热带被研究之前就指蛀木者。"},{"word":"termite","structure":"termes > English termite","meaning":"the wood-eating social insect","meaningCN":"蛀木的群居昆虫","example":"The termite builds tubes of mud.","exampleCN":"白蚁筑泥管。"},{"word":"-s","structure":"termites = termite + -s (plural)","meaning":"many termites","meaningCN":"许多白蚁","example":"Termites worked through the floor.","exampleCN":"白蚁把地板吃穿了。"},{"word":"-arium","structure":"termitarium = termite + -arium (place)","meaning":"a termite nest","meaningCN":"白蚁巢","example":"The termitarium rose two metres.","exampleCN":"白蚁巢高出两米。"},{"word":"-cide","structure":"termiticide = termite + -cide (killing)","meaning":"a substance that kills termites","meaningCN":"杀白蚁剂","example":"The soil was treated with a termiticide.","exampleCN":"土壤用杀白蚁剂处理过。"},{"word":"-ic","structure":"termitic = termite + -ic (relating to)","meaning":"of or caused by termites","meaningCN":"白蚁的；白蚁造成的","example":"The damage was termitic in origin.","exampleCN":"这项损坏源自白蚁。"},{"word":"Isoptera","structure":"Greek isos 'equal' + pteron 'wing' (order name)","meaning":"the equal-winged insects","meaningCN":"等翅类昆虫","example":"Isoptera is the older order name for termites.","exampleCN":"Isoptera 是白蚁的旧目名。"},{"word":"-ology","structure":"isopterology = Isoptera + -logy","meaning":"the study of termites","meaningCN":"白蚁学","example":"Isopterology has few specialists.","exampleCN":"研究白蚁的专家很少。"},{"word":"white ant","structure":"white + ant (old compound name)","meaning":"an outdated and wrong name","meaningCN":"过时且错误的名称","example":"White ant appears only in older texts.","exampleCN":"white ant 只见于较旧的文本。"}],"latinEntries":[{"word":"termes","structure":"termes, termitis (m., third declension)","meaning":"woodworm, a gnawing insect","meaningCN":"木蠹虫；蛀虫"},{"word":"tinea","structure":"tinea, tineae (f., first declension)","meaning":"a gnawing worm, clothes moth","meaningCN":"蛀虫；衣蛾"},{"word":"lignum","structure":"lignum, ligni (n., second declension)","meaning":"wood","meaningCN":"木材"}]}}]);
